#[allow(clippy::too_many_arguments)]
fn prover_nested(walk: &mut ProverWalk, block: &Block, lambda: Option<Vec<String>>, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, unaliased: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, shape_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    let is_lambda = lambda.is_some();
    if is_lambda {
        let mut inner = scope.clone();
        for param in nikaia_std::index::or(lambda, || vec![].into()) {
            inner.rebind(&walk.arena, &param);
            inner.loose.insert(param.to_owned());
        }
        inner.path = None;
        inner.exact = false;
        prover_block(walk, block, &mut inner, &at.inside(true), program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    } else {
        let mut inner = scope.blind();
        prover_block(walk, block, &mut inner, &at.inside(false), program, words, own, library, ask, model, escape, holes_of, unaliased, written_of, shape_of, condition);
    }
}

#[allow(clippy::too_many_arguments)]
fn prover_a_call(walk: &mut ProverWalk, callee: &str, args: &[Expr], span: Span, scope: &ProverScope, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) {
    if scope.locals.contains(callee) { return; }
    let caller = carrying_function((at.function).as_deref());
    if caller.is_some() { walk.state.edges.insert((nikaia_std::index::or(caller, || "".into()), callee.to_owned())); }
    let pre = if walk.state.collecting { prover_precondition_in(&walk.state.known, callee) } else { prover_precondition_in(&walk.state.preconditions, callee) };
    if pre.is_some() {
        let function = match free_function(program, words, callee) { Some(__nikaia_value) => __nikaia_value, None => return };
        let found = nikaia_std::index::or(pre, || Precondition::none());
        prover_record_call(walk, callee, &function.params, &found.claims, args, span, scope, at, words, ask, model, escape, written_of);
        return;
    }
    let foreign = match prover_foreign_contract(walk, callee, own, condition) { Some(__nikaia_value) => __nikaia_value, None => return };
    if !foreign.requires.is_empty() { prover_record_call(walk, callee, &foreign.params, &foreign.requires, args, span, scope, at, words, ask, model, escape, written_of); }
}

#[allow(clippy::too_many_arguments)]
fn prover_record_call(walk: &mut ProverWalk, callee: &str, params: &[String], claims: &[PreClaim], args: &[Expr], span: Span, scope: &ProverScope, at: &ProverWhere, words: &winnow_grammar::InternerContext, ask: &impl Fn(&TermArena, &[i64], i64) -> SolverAnswer, model: &impl Fn(&TermArena, &[i64], i64) -> Option<collections::BTreeMap<String, i64>>, escape: &impl Fn(&str) -> String, written_of: &impl Fn(&Expr) -> String) {
    let outcome = walk.state.precondition_call(&mut walk.arena, words, callee, params, claims, args, span, scope, at, ask, model, escape);
    for found in outcome.findings.iter() { walk.findings.push(found.clone()); }
    let mut written: String = String::from("");
    for arg in args.iter() {
        if !written.is_empty() { written.push_str(", "); }
        written.push_str(&written_of(arg));
    }
    let key = (callee.to_owned(), written);
    let before = walk.reaches.remove(&key);
    if before.is_some() { walk.reaches.insert(key, joined_reach(nikaia_std::index::or(before, || CallReach::Proved), outcome.reach)); } else { walk.reaches.insert(key, outcome.reach); }
}

fn prover_foreign_contract(walk: &mut ProverWalk, key: &str, own: &Ledger, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> Option<Foreign> {
    let cached = prover_cached_foreign(&walk.state.foreign, key);
    if cached.is_some() { return cached; }
    let contract = match *nikaia_std::index::get(&own.functions, key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let shape = foreign_shape(contract);
    let mut requires: Vec<i64> = vec![];
    for text in contract.requires.iter() { requires.push(prover_condition_term(&mut walk.arena, text, &shape.names, condition)); }
    let mut ensures: Vec<i64> = vec![];
    for text in contract.ensures.iter() { ensures.push(prover_condition_term(&mut walk.arena, text, &shape.names, condition)); }
    let foreign = foreign_from(contract, shape, &requires, &ensures);
    walk.state.foreign.insert(key.to_owned(), Some(foreign.clone()));
    Some(foreign)
}

fn prover_condition_term(arena: &mut TermArena, text: &str, names: &collections::BTreeSet<String>, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> i64 {
    let nodes = condition(text, names);
    if nodes.is_empty() { return -1; }
    arena.adopt(&nodes)
}

#[allow(clippy::too_many_arguments)]
fn prover_postconditions_of(walk: &mut ProverWalk, callee: &str, args: &[Expr], bound: &str, scope: &ProverScope, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> Vec<i64> {
    let posts = standing_posts(&walk.state.postconditions, callee);
    if posts.is_some() {
        let function = match free_function(program, words, callee) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
        return postconditions_for(&mut walk.arena, &nikaia_std::index::or(posts, || vec![].into()), &function.params, args, bound, scope, words);
    }
    let foreign = match prover_foreign_contract(walk, callee, own, condition) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    postconditions_for(&mut walk.arena, &foreign.ensures, &foreign.params, args, bound, scope, words)
}

fn prover_returns_whole(walk: &mut ProverWalk, callee: &str, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, condition: &impl Fn(&str, &collections::BTreeSet<String>) -> Vec<SolverTerm>) -> bool {
    let function = free_function(program, words, callee);
    if function.is_some() {
        let found = match function { Some(__nikaia_value) => __nikaia_value, None => return false };
        return found.whole_result;
    }
    let foreign = match prover_foreign_contract(walk, callee, own, condition) { Some(__nikaia_value) => __nikaia_value, None => return false };
    foreign.whole_result
}

fn prover_throws(call: &Expr, at: &ProverWhere, program: &Program, words: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, unaliased: &impl Fn(&str) -> String) -> bool { may_throw(call, at.throws_out, program, words, own, library, unaliased) }

fn prover_called(func: &Expr, words: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> Option<String> {
    match func {
        Expr::Variable(name) => { let name = *name; Some(words.resolve(name).to_owned()) },
        Expr::Path(segments) => Some(prover_qualified(segments, words, unaliased)),
        _ => None,
    }
}

fn prover_bound_callee(func: &Expr, scope: &ProverScope, words: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> Option<String> {
    match func {
        Expr::Variable(name) => {
            let name = *name;
            let text = words.resolve(name);
            if scope.locals.contains(text) { return None; }
            Some(text.to_owned())
        },
        Expr::Path(segments) => Some(prover_qualified(segments, words, unaliased)),
        _ => None,
    }
}

fn prover_qualified(segments: &[winnow_grammar::Symbol], words: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String) -> String {
    let mut joined: String = String::from("");
    for segment in segments.iter() {
        if !joined.is_empty() { joined.push_str("::"); }
        joined.push_str(words.resolve(*segment));
    }
    unaliased(&joined)
}

fn prover_an_assert_call(func: &Expr, args: &[Expr], span: &Span, claims: &collections::BTreeSet<(i64, String)>, shape_of: &impl Fn(&Expr) -> String) -> bool {
    let named = matches!(func, Expr::Variable(_));
    if !named || args.len() != 1 { return false; }
    claims.contains(&(span.start as i64, shape_of(nikaia_std::index::get(&args, 0))))
}

fn prover_message(config: &[ConfigArg], words: &winnow_grammar::InternerContext) -> Option<String> {
    for c in config.iter() {
        if words.resolve(c.name) == "message" {
            match &c.value {
                Expr::LitStr { text, .. } => return Some(text.to_owned()),
                _ => { },
            }
        }
    }
    None
}

fn prover_returned_name(stmt: &Stmt, words: &winnow_grammar::InternerContext) -> Option<String> {
    match stmt {
        Stmt::Return(value) => prover_variable_named((value).as_ref(), words),
        _ => None,
    }
}

fn prover_variable_named(value: Option<&Expr>, words: &winnow_grammar::InternerContext) -> Option<String> {
    let present = match value { Some(__nikaia_value) => __nikaia_value, None => return None };
    match present {
        Expr::Variable(name) => { let name = *name; Some(words.resolve(name).to_owned()) },
        _ => None,
    }
}

fn prover_an_if(stmt: &Stmt) -> bool {
    match stmt {
        Stmt::Expr(expr) => matches!(expr, Expr::If { .. }),
        _ => false,
    }
}

fn prover_symbol_text(symbol: Option<&winnow_grammar::Symbol>, words: &winnow_grammar::InternerContext) -> Option<String> {
    let present = match symbol { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(words.resolve(*present).to_owned())
}

fn prover_typed(ty: Option<&Type>, words: &winnow_grammar::InternerContext, asked: i64) -> bool {
    let t = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    let name = words.resolve(t.name);
    if asked == 0 { return t.generics.is_empty() && is_whole_number(name); }
    if asked == 1 { return name.starts_with("u"); }
    has_a_length(name)
}

fn prover_a_test_function(name: Option<&str>) -> bool {
    let text = match name { Some(__nikaia_value) => __nikaia_value, None => return false };
    let prefix = "__nikaia_test_";
    if !text.starts_with(prefix) || (text.len() as i64) == prefix.len() as i64 { return false; }
    let c: Vec<scalar> = nikaia_std::list::chars(text.chars());
    for k in 14..c.len() as i64 { if *nikaia_std::index::get(&c, (k) as usize) < '0' || *nikaia_std::index::get(&c, (k) as usize) > '9' { return false; } }
    true
}

fn prover_precondition_in(map: &collections::BTreeMap<String, Precondition>, callee: &str) -> Option<Precondition> {
    let found = match *nikaia_std::index::get(&map, callee) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(found.clone())
}

fn prover_cached_foreign(map: &collections::BTreeMap<String, Option<Foreign>>, key: &str) -> Option<Foreign> {
    let found = match nikaia_std::index::flat(*nikaia_std::index::get(&map, key)) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(found.clone())
}

fn prover_named_main(own: Option<&str>) -> bool {
    let name = match own { Some(__nikaia_value) => __nikaia_value, None => return false };
    name == "main"
}


// --- render.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Marked {
    pub span: Span,
    pub word: String,
    pub text: String,
    pub main: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Shown {
    pub warning: bool,
    pub code: String,
    pub message: String,
    pub notes: Vec<String>,
    pub help: Option<String>,
    pub span: Span,
    pub labels: Vec<Marked>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Placed {
    line: i64,
    column: i64,
    width: i64,
    label: Marked,
}

pub fn rendered(shown: &Shown, path: &str, source: &str) -> String {
    let chars: Vec<scalar> = nikaia_std::list::chars(source.chars());
    let lines: Vec<&str> = source.split("\n").collect::<Vec<_>>();
    let mut labels: Vec<Marked> = shown.labels.to_owned();
    if labels.is_empty() { labels.push(Marked { span: shown.span.clone(), word: String::from(""), text: String::from(""), main: true }); }
    let mut placed: Vec<Placed> = vec![];
    for label in labels.iter() {
        let at = line_column(&chars, label.span.start);
        let text = line_of(&lines, at.0);
        let found = if label.word.is_empty() { (at.1, spanned_width(&chars, &label.span)) } else { word_in(&text, at.1, &label.word) };
        placed.push(Placed { line: at.0, column: found.0, width: found.1, label: label.clone() });
    }
    let placed = in_order(&placed);
    let mut line: i64 = -1;
    let mut column: i64 = -1;
    for one in placed.iter() {
        if line < 0 && one.label.main {
            line = one.line;
            column = one.column;
        }
    }
    if line < 0 {
        let at = line_column(&chars, shown.span.start);
        line = at.0;
        column = at.1;
    }
    let mut gutter: i64 = 1;
    for one in placed.iter() {
        let digits = format!("{}", one.line).len() as i64;
        if digits > gutter { gutter = digits; }
    }
    let mut bar = spaces(gutter + 1);
    bar.push_str(" |");
    let level = if shown.warning { "warning" } else { "error" };
    let mut out = headed(level, &shown.code);
    out.push_str(": ");
    out.push_str(&said(&shown.message));
    out.push('\n');
    out.push_str(&spaces(gutter + 1));
    out.push_str(&format!("--> {}:{}:{}", path, line, column));
    out.push('\n');
    out.push_str(&bar);
    out.push('\n');
    let mut shown_line: i64 = -1;
    for one in placed.iter() {
        if shown_line != one.line {
            if shown_line >= 0 && one.line - shown_line > 1 {
                out.push_str(&spaces(gutter + 2));
                out.push_str("...");
                out.push('\n');
            }
            out.push(' ');
            out.push_str(&right_aligned(&format!("{}", one.line), gutter));
            out.push_str(" | ");
            out.push_str(&line_of(&lines, one.line).trim_end());
            out.push('\n');
            shown_line = one.line;
        }
        let mark = if one.label.main { "^" } else { "-" };
        let mut marked = bar.to_owned();
        marked.push(' ');
        marked.push_str(&spaces(one.column - 1));
        marked.push_str(&mark.repeat(nikaia_std::count::of(one.width)));
        marked.push(' ');
        marked.push_str(&one.label.text);
        out.push_str(&marked.trim_end());
        out.push('\n');
    }
    out.push_str(&bar);
    out.push('\n');
    let indent = spaces(gutter + 2);
    for note in shown.notes.iter() {
        out.push_str(&indent);
        out.push_str("= note: ");
        out.push_str(&said(note));
        out.push('\n');
    }
    out.push_str(&helped(&indent, (shown.help).as_deref()));
    out
}

fn helped(indent: &str, help: Option<&str>) -> String {
    let given = match help { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
    format!("{}= help: {}\n", indent, said(given))
}

fn in_order(placed: &[Placed]) -> Vec<Placed> {
    let mut out: Vec<Placed> = vec![];
    for one in placed.iter() {
        let mut at = out.len() as i64;
        while at > 0 && (nikaia_std::index::get(&out, nikaia_std::index::at(at - 1)).line > one.line || nikaia_std::index::get(&out, nikaia_std::index::at(at - 1)).line == one.line && nikaia_std::index::get(&out, nikaia_std::index::at(at - 1)).column > one.column) { at -= 1; }
        out.insert(nikaia_std::count::of(at), one.clone());
    }
    out
}

fn line_of(lines: &[&str], line: i64) -> String {
    if line < 1 || line > lines.len() as i64 { return String::from(""); }
    (*nikaia_std::index::get(&lines, nikaia_std::index::at(line - 1))).to_owned()
}

fn line_column(chars: &[scalar], offset: u32) -> (i64, i64) {
    let wanted = offset as i64;
    let mut bytes: i64 = 0;
    let mut line = 1;
    let mut column = 1;
    for c in chars.iter() {
        let c = nikaia_std::num::value(c);
        if bytes >= wanted { break; }
        bytes += utf8_width(c);
        if c == '\n' {
            line += 1;
            column = 1;
        } else { column += 1; }
    }
    (line, column)
}

fn spanned_width(chars: &[scalar], span: &Span) -> i64 {
    let start = span.start as i64;
    let end = span.end as i64;
    let mut bytes: i64 = 0;
    let mut covered: String = String::from("");
    for c in chars.iter() {
        let c = nikaia_std::num::value(c);
        if bytes >= end { break; }
        if bytes >= start {
            if c == '\n' { break; }
            covered.push(c);
        }
        bytes += utf8_width(c);
    }
    let width = covered.trim_end().chars().count() as i64;
    if width < 1 { return 1; }
    width
}

fn utf8_width(c: scalar) -> i64 {
    let point = c as u32;
    if point < 128u32 { return 1; }
    if point < 2048u32 { return 2; }
    if point < 65536u32 { return 3; }
    4
}

fn spaces(n: i64) -> String { " ".repeat(nikaia_std::count::of(n)) }

fn right_aligned(text: &str, width: i64) -> String {
    let mut out = spaces(width - text.len() as i64);
    out.push_str(&text);
    out
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Pause {
    pub span: Span,
    pub caller: String,
    pub promise: String,
    pub callee: String,
    pub from_library: bool,
    pub unpromised: bool,
    pub construct: bool,
}

pub fn paused(pause: &Pause) -> Shown {
    let caller = pause.caller.to_owned();
    let promise = pause.promise.to_owned();
    let callee = pause.callee.to_owned();
    if pause.unpromised {
        let split = package_and_function(&callee);
        let package = &split.0;
        let function = &split.1;
        return Shown { warning: false, code: String::from("NK2202"), message: format!("`{}` is `{}`, but it calls `{}`, which doesn't promise that it never pauses.", caller, promise, callee), notes: vec![format!("`{}` is `{}`'s, and its source doesn't say `sync`. That its body doesn't pause today is not a promise another package can rely on.", callee, package)], help: Some(format!("Write `sync` after the result of `{}` in `{}`, or remove `{}` from `{}`.", function, package, promise, caller)), span: pause.span.clone(), labels: vec![Marked { span: pause.span.clone(), word: callee.to_owned(), text: String::from("doesn't promise `sync`"), main: true }] };
    }
    let ledger = if pause.from_library { "`std`" } else { "this program" };
    let article = an_or_a(&callee);
    let mut notes: Vec<String> = vec![String::from("A `sync` function promises that it never pauses and does no I/O.")];
    if pause.construct {
        let capital = said(&article);
        notes.push(format!("{} `{}` block waits for its branches to finish, which is a pause.", capital, callee));
    } else { notes.push(format!("`{}` isn't declared `sync` in {}.", callee, ledger)); }
    let message = if pause.construct { format!("`{}` is `{}`, but it contains {} `{}` block, which can pause.", caller, promise, article, callee) } else { format!("`{}` is `{}`, but it calls `{}`, which can pause.", caller, promise, callee) };
    Shown { warning: false, code: String::from("NK2202"), message, notes, help: Some(format!("Remove `{}` from `{}`, or move the call out of it.", promise, caller)), span: pause.span.clone(), labels: vec![Marked { span: pause.span.clone(), word: callee.to_owned(), text: String::from("this can pause"), main: true }] }
}

fn package_and_function(callee: &str) -> (String, String) {
    let parts: Vec<&str> = callee.splitn(2, "::").collect::<Vec<_>>();
    if parts.len() < 2 { return (String::from("its package"), callee.to_owned()); }
    ((*nikaia_std::index::get(&parts, 0)).to_owned(), (*nikaia_std::index::get(&parts, 1)).to_owned())
}

pub fn an_or_a(word: &str) -> String {
    let first: Vec<scalar> = nikaia_std::list::chars(word.chars());
    if !first.is_empty() && (*nikaia_std::index::get(&first, 0) == 'i' || *nikaia_std::index::get(&first, 0) == 'a' || *nikaia_std::index::get(&first, 0) == 'e' || *nikaia_std::index::get(&first, 0) == 'o' || *nikaia_std::index::get(&first, 0) == 'I' || *nikaia_std::index::get(&first, 0) == 'A' || *nikaia_std::index::get(&first, 0) == 'E' || *nikaia_std::index::get(&first, 0) == 'O') { return String::from("an"); }
    String::from("a")
}

fn after_help(note: &str) -> String {
    let rest = match note.strip_prefix("help: ") { Some(__nikaia_value) => __nikaia_value, None => return note.to_owned() };
    after_help(rest)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Relayed {
    pub level: String,
    pub message: String,
    pub internal: Option<String>,
    pub generated_line: i64,
    pub located: bool,
    pub span: Span,
    pub word: String,
    pub notes: Vec<String>,
}

pub fn relayed(message: &Relayed, path: &str, source: &str, generated_path: &str) -> String {
    let mut at = generated_path.to_owned();
    if message.generated_line > 0 { at = format!("{}:{}", generated_path, message.generated_line); }
    if message.internal.is_some() {
        let original = match message.internal.as_deref() { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
        if message.located {
            let shown = Shown { warning: false, code: String::from(""), message: String::from("This is a bug in Nikaia, not in your program. Please report it."), notes: vec![String::from("The compiler generated two different types for one of yours."), format!("What the Rust compiler said: {}", original)], help: None, span: message.span.clone(), labels: vec![] };
            let out = rendered(&shown, path, source);
            if out.starts_with("error:") { return format!("internal {}", out); }
            return out;
        }
        return format!("internal error: {}: This is a bug in Nikaia, not in your program. Please report it.\n   = note: The compiler generated two different types for one of yours.\n   = note: What the Rust compiler said: {}\n", at, original);
    }
    if message.located {
        let mut notes: Vec<String> = vec![];
        let mut help: Option<String> = None;
        for note in message.notes.iter() { if note.starts_with("help: ") { help = Some(after_help(note)); } else { notes.push(note.to_owned()); } }
        let shown = Shown { warning: message.level == "warning", code: String::from(""), message: message.message.to_owned(), notes, help, span: message.span.clone(), labels: vec![Marked { span: message.span.clone(), word: message.word.to_owned(), text: String::from(""), main: true }] };
        return rendered(&shown, path, source);
    }
    let mut out = format!("{}: {}: {} (no Nikaia source maps to this)\n", message.level, at, message.message);
    for note in message.notes.iter() { out.push_str(&format!("   = note: {}\n", said(note))); }
    out
}


// --- rust.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Part<'a> {
    pub name: &'a str,
    pub ty: &'a str,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Fun<'a> {
    pub name: &'a str,
    pub generics: &'a str,
    pub calls: Vec<&'a str>,
    pub wheres: &'a str,
    pub pauses: bool,
    pub parts: Vec<Part<'a>>,
    pub result: &'a str,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Rec<'a> {
    pub what: &'a str,
    pub name: &'a str,
    pub parts: Vec<Part<'a>>,
    pub derives: Vec<&'a str>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Group<'a> {
    pub what: &'a str,
    pub name: &'a str,
    pub via: &'a str,
    pub visible: bool,
    pub items: Vec<RustItem<'a>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RustItem<'a> {
    Fun(Fun<'a>),
    Rec(Rec<'a>),
    Group(Group<'a>),
    Hidden(Fun<'a>),
    Used(&'a str),
    Export(&'a str),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Found<'a> {
    One(RustItem<'a>),
    Skip,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Called<'a> {
    One(&'a str),
    Many(Vec<&'a str>),
    Nothing,
}

grammar! {
    grammar Rust {

        rule WSE =
            multispace1
            -> { }

        rule WS =
            (WSE | LINE | BLOCK)*
            -> { }

        rule LINE =
            "//" until(line_ending)
            -> { }

        rule BLOCK =
            "/*" until("*/") "*/"
            -> { }

        pub rule file -> Vec<RustItem<'a>> =
            items:public eof
            -> { items }

        rule public -> Vec<RustItem<'a>> =
            found:found*
            -> { kept(found) }

        rule exposed -> Vec<RustItem<'a>> =
            found:found_exposed*
            -> { kept(found) }

        rule found -> Found<'a> =
            i:item
            -> { Found::One(i) }
          | f:method
            -> { Found::One(RustItem::Hidden(f)) }
          | JUNK
            -> { Found::Skip }

        rule found_exposed -> Found<'a> =
            f:method
            -> { Found::One(RustItem::Fun(f)) }
          | i:item
            -> { Found::One(i) }
          | JUNK
            -> { Found::Skip }

        rule item -> RustItem<'a> =
            f:function
            -> { RustItem::Fun(f) }
          | r:record
            -> { RustItem::Rec(r) }
          | g:group
            -> { RustItem::Group(g) }
          | e:export
            -> { RustItem::Export(e) }
          | u:import
            -> { RustItem::Used(u) }

        rule export -> &'a str =
            PUB USE t:USE_TEXT ";"
            -> { t }

        rule import -> &'a str =
            USE t:USE_TEXT ";"
            -> { t }

        rule USE_TEXT -> &'a str =
            s:text(USE_RUN)
            -> { s.trim() }

        rule USE_RUN =
            USE_PIECE+
            -> { }

        rule USE_PIECE =
            not(";") (BRACES | LINE | BLOCK | ANY)
            -> { }

        rule function -> Fun<'a> =
            PUB f:method
            -> { f }

        rule method -> Fun<'a> =
            pauses:qualifiers FN name:IDENT g:generics parts:parameters result:result w:where_clause c:tail
            -> { Fun { name, generics: g, wheres: w, calls: c, pauses, parts, result } }

        rule qualifiers -> bool =
            qs:qualifier*
            -> {
                let mut pauses = false;
                for q in qs.into_iter() { if q { pauses = true; } }
                pauses
            }

        rule qualifier -> bool =
            ASYNC
            -> { true }
          | CONST
            -> { false }
          | UNSAFE
            -> { false }
          | EXTERN abi
            -> { false }

        rule abi =
            string
            -> { }
          | empty
            -> { }

        rule tail -> Vec<&'a str> =
            cs:inside
            -> { cs }
          | ";"
            -> { Vec::new() }

        rule inside -> Vec<&'a str> =
            "{" cs:inside_run "}"
            -> { cs }

        rule inside_run -> Vec<&'a str> =
            pieces:inside_piece*
            -> { every_call(pieces) }

        rule inside_piece -> Called<'a> =
            not("}") STRING
            -> { Called::Nothing }
          | not("}") CHAR
            -> { Called::Nothing }
          | not("}") LINE
            -> { Called::Nothing }
          | not("}") BLOCK
            -> { Called::Nothing }
          | not("}") inner:inside
            -> { Called::Many(inner) }
          | not("}") p:CALL
            -> { Called::One(p) }
          | not("}") ANY
            -> { Called::Nothing }

        rule CALL -> &'a str =
            p:text(PATH) TURBOFISH "("
            -> { p }

        rule PATH =
            raw_ident(PATH_TAIL)*
            -> { }

        rule PATH_TAIL =
            "::" raw_ident
            -> { }

        rule TURBOFISH =
            "::" ANGLES
            -> { }
          | empty
            -> { }

        rule parameters -> Vec<Part<'a>> =
            "(" ps:parameter_list ")"
            -> { ps }

        rule parameter_list -> Vec<Part<'a>> =
            head:parameter tail:parameter_tail* COMMA
            -> {
                let mut all = Vec::new();
                all.push(head);
                for p in tail.into_iter() { all.push(p); }
                all
            }
          | empty
            -> { Vec::new() }

        rule parameter_tail -> Part<'a> =
            "," p:parameter
            -> { p }

        rule parameter -> Part<'a> =
            t:text(receiver)
            -> { Part { name: "self", ty: t.trim() } }
          | MUT n:IDENT ":" t:PARAM_TYPE
            -> { Part { name: n, ty: t } }
          | n:IDENT ":" t:PARAM_TYPE
            -> { Part { name: n, ty: t } }
          | n:HOLE ":" t:PARAM_TYPE
            -> { Part { name: n, ty: t } }

        rule receiver =
            "&" LIFETIME MUT SELF
            -> { }
          | "&" LIFETIME SELF
            -> { }
          | "&" MUT SELF
            -> { }
          | "&" SELF
            -> { }
          | MUT SELF
            -> { }
          | SELF
            -> { }

        rule record -> Rec<'a> =
            ds:attributes PUB STRUCT name:IDENT generics where_clause "{" fs:field_list "}"
            -> { Rec { what: "struct", name, parts: fs, derives: ds } }
          | ds:attributes PUB STRUCT name:IDENT generics tuple_body where_clause ";"
            -> { Rec { what: "struct", name, parts: Vec::new(), derives: ds } }
          | ds:attributes PUB ENUM name:IDENT generics where_clause "{" vs:variant_list "}"
            -> { Rec { what: "enum", name, parts: vs, derives: ds } }

        rule attributes -> Vec<&'a str> =
            all:attribute*
            -> {
                let mut derives = Vec::new();
                for d in all.into_iter() { if !d.is_empty() { derives.push(d); } }
                derives
            }

        rule attribute -> &'a str =
            "#" "[" DERIVE "(" d:text(TUPLE_INNER) ")" "]"
            -> { d.trim() }
          | "#" "[" BRACKET_INNER "]"
            -> { "" }

        rule tuple_body =
            "(" TUPLE_INNER ")"
            -> { }
          | empty
            -> { }

        rule field_list -> Vec<Part<'a>> =
            head:field tail:field_tail* COMMA
            -> {
                let mut all = Vec::new();
                all.push(head);
                for f in tail.into_iter() { all.push(f); }
                all
            }
          | empty
            -> { Vec::new() }

        rule field_tail -> Part<'a> =
            "," f:field
            -> { f }

        rule field -> Part<'a> =
            PUB n:IDENT ":" t:FIELD_TYPE
            -> { Part { name: n, ty: t } }
          | n:IDENT ":" t:FIELD_TYPE
            -> { Part { name: n, ty: t } }

        rule variant_list -> Vec<Part<'a>> =
            head:variant tail:variant_tail* COMMA
            -> {
                let mut all = Vec::new();
                all.push(head);
                for v in tail.into_iter() { all.push(v); }
                all
            }
          | empty
            -> { Vec::new() }

        rule variant_tail -> Part<'a> =
            "," v:variant
            -> { v }

        rule variant -> Part<'a> =
            n:IDENT t:text(payload)
            -> { Part { name: n, ty: t.trim() } }

        rule payload =
            "(" TUPLE_INNER ")"
            -> { }
          | "{" BRACE_INNER "}"
            -> { }
          | empty
            -> { }

        rule group -> Group<'a> =
            UNSAFE IMPL generics v:IMPL_TYPE FOR t:IMPL_TYPE where_clause "{" items:exposed "}"
            -> { Group { what: "unsafe impl", name: t, via: v, visible: true, items } }
          | UNSAFE IMPL generics t:IMPL_TYPE where_clause "{" items:public "}"
            -> { Group { what: "unsafe impl", name: t, via: "", visible: true, items } }
          | IMPL generics v:IMPL_TYPE FOR t:IMPL_TYPE where_clause "{" items:exposed "}"
            -> { Group { what: "impl", name: t, via: v, visible: true, items } }
          | IMPL generics t:IMPL_TYPE where_clause "{" items:public "}"
            -> { Group { what: "impl", name: t, via: "", visible: true, items } }
          | PUB TRAIT name:IDENT generics where_clause "{" items:exposed "}"
            -> { Group { what: "trait", name, via: "", visible: true, items } }
          | PUB MOD name:IDENT "{" items:public "}"
            -> { Group { what: "mod", name, via: "", visible: true, items } }
          | PUB MOD name:IDENT ";"
            -> { Group { what: "mod", name, via: "", visible: true, items: Vec::new() } }
          | MOD name:IDENT "{" items:public "}"
            -> { Group { what: "mod", name, via: "", visible: false, items } }
          | MOD name:IDENT ";"
            -> { Group { what: "mod", name, via: "", visible: false, items: Vec::new() } }

        rule generics -> &'a str =
            "<" g:text(ANGLE_INNER) ">"
            -> { g.trim() }
          | empty
            -> { "" }

        rule where_clause -> &'a str =
            WHERE w:text(WHERE_RUN)
            -> { w.trim() }
          | empty
            -> { "" }

        rule PARAM_TYPE -> &'a str =
            s:text(PARAM_RUN)
            -> { s.trim() }

        rule PARAM_RUN =
            PARAM_PIECE+
            -> { }

        rule PARAM_PIECE =
            not(",") not(")") SPAN
            -> { }

        rule FIELD_TYPE -> &'a str =
            s:text(FIELD_RUN)
            -> { s.trim() }

        rule FIELD_RUN =
            FIELD_PIECE+
            -> { }

        rule FIELD_PIECE =
            not(",") not("}") SPAN
            -> { }

        rule result -> &'a str =
            "->" t:RESULT_TYPE
            -> { t }
          | empty
            -> { "" }

        rule RESULT_TYPE -> &'a str =
            s:text(RESULT_RUN)
            -> { s.trim() }

        rule RESULT_RUN =
            RESULT_PIECE+
            -> { }

        rule RESULT_PIECE =
            not("{") not(";") not(WHERE) SPAN
            -> { }

        rule WHERE_RUN =
            WHERE_PIECE+
            -> { }

        rule WHERE_PIECE =
            not("{") not(";") SPAN
            -> { }

        rule IMPL_TYPE -> &'a str =
            s:text(IMPL_RUN)
            -> { s.trim() }

        rule IMPL_RUN =
            IMPL_PIECE+
            -> { }

        rule IMPL_PIECE =
            not("{") not(WHERE) not(FOR) SPAN
            -> { }

        rule SPAN =
            (ANGLES | PARENS | BRACKETS | STRING | CHAR | LINE | BLOCK | ANY)
            -> { }

        rule JUNK =
            not("}") (STRING | CHAR | LINE | BLOCK | BRACES | ANY)
            -> { }

        rule BRACES =
            "{" BRACE_INNER "}"
            -> { }

        rule BRACE_INNER =
            BRACE_PIECE*
            -> { }

        rule BRACE_PIECE =
            not("}") (STRING | CHAR | LINE | BLOCK | BRACES | ANY)
            -> { }

        rule PARENS =
            "(" TUPLE_INNER ")"
            -> { }

        rule TUPLE_INNER =
            PAREN_PIECE*
            -> { }

        rule PAREN_PIECE =
            not(")") (STRING | CHAR | LINE | BLOCK | PARENS | BRACES | BRACKETS | ANGLES | ANY)
            -> { }

        rule BRACKETS =
            "[" BRACKET_INNER "]"
            -> { }

        rule BRACKET_INNER =
            BRACKET_PIECE*
            -> { }

        rule BRACKET_PIECE =
            not("]") (STRING | CHAR | LINE | BLOCK | PARENS | BRACES | BRACKETS | ANGLES | ANY)
            -> { }

        rule ANGLES =
            "<" ANGLE_INNER ">"
            -> { }

        rule ANGLE_INNER =
            ANGLE_PIECE*
            -> { }

        rule ANGLE_PIECE =
            not(">") (STRING | CHAR | LINE | BLOCK | PARENS | BRACKETS | ANGLES | ANY)
            -> { }

        rule STRING =
            "\"" (SESC | SPLAIN)* "\""
            -> { }

        rule SESC =
            "\\" any
            -> { }

        rule SPLAIN =
            not("\"") not("\\") any
            -> { }

        rule CHAR =
            "'" (CESC | CPLAIN) "'"
            -> { }

        rule CESC =
            "\\" any
            -> { }

        rule CPLAIN =
            not("'") not("\\") any
            -> { }

        rule ANY =
            any
            -> { }

        rule PUB =
            "pub" not(WORD) not("(")
            -> { }

        rule FN =
            "fn" not(WORD)
            -> { }

        rule ASYNC =
            "async" not(WORD)
            -> { }

        rule CONST =
            "const" not(WORD)
            -> { }

        rule UNSAFE =
            "unsafe" not(WORD)
            -> { }

        rule EXTERN =
            "extern" not(WORD)
            -> { }

        rule STRUCT =
            "struct" not(WORD)
            -> { }

        rule DERIVE =
            "derive" not(WORD)
            -> { }

        rule ENUM =
            "enum" not(WORD)
            -> { }

        rule TRAIT =
            "trait" not(WORD)
            -> { }

        rule IMPL =
            "impl" not(WORD)
            -> { }

        rule MOD =
            "mod" not(WORD)
            -> { }

        rule FOR =
            "for" not(WORD)
            -> { }

        rule WHERE =
            "where" not(WORD)
            -> { }

        rule MUT =
            "mut" not(WORD)
            -> { }

        rule USE =
            "use" not(WORD)
            -> { }

        rule SELF =
            "self" not(WORD)
            -> { }

        rule WORD =
            alpha1
            -> { }
          | digit
            -> { }
          | "_"
            -> { }

        rule IDENT -> &'a str =
            s:raw_ident
            -> { s }

        rule HOLE -> &'a str =
            s:text("_")
            -> { s }

        rule LIFETIME =
            "'" raw_ident
            -> { }

        rule COMMA =
            ","
            -> { }
          | empty
            -> { }
    }
}

fn every_call(pieces: Vec<Called<'_>>) -> Vec<&str> {
    let mut all = Vec::new();
    for piece in pieces.into_iter() {
        match piece {
            Called::One(one) => { all.push(one); },
            Called::Many(ref many) => {
                for one in many.iter() {
                    let one = *one;
                    all.push(one);
                }
            },
            Called::Nothing => { },
        }
    }
    all
}

fn kept(found: Vec<Found<'_>>) -> Vec<RustItem<'_>> {
    let mut all = Vec::new();
    for f in found.into_iter() {
        match f {
            Found::One(item) => { all.push(item); },
            Found::Skip => { },
        }
    }
    all
}


// --- rustc_words.nika ---

pub fn in_this_language(message: &str) -> String {
    let mut out = shared_names(message);
    out = replaced(&out, "nikaia_std::lock::Crossing", "Locked");
    out = replaced(&out, "nikaia_std::lock::Local", "Locked");
    out = replaced(&out, "lock::Crossing", "Locked");
    out = replaced(&out, "lock::Local", "Locked");
    out = replaced(&out, "Crossing<", "Locked<");
    out = replaced(&out, "Local<", "Locked<");
    out = replaced(&out, ", BuildHasherDefault<FxHasher>>", ">");
    out = replaced(&out, "nikaia_std::hash::TrustedMap", "HashMap");
    out = replaced(&out, "nikaia_std::hash::TrustedSet", "HashSet");
    out = replaced(&out, "TrustedMap", "HashMap");
    out = replaced(&out, "TrustedSet", "HashSet");
    out = replaced(&out, "`Option::<T>::map` takes ownership of the receiver `self`", "`?.` over a member that is not copied takes the value it reaches through ");
    out = replaced(&out, "`Option::<T>::and_then` takes ownership of the receiver `self`", "`?.` over a member that is not copied takes the value it reaches through ");
    out
}

pub fn is_rust_internal(note: &str) -> bool {
    for internal in ["#[deny(", "#[warn(", "#[allow(", "#[forbid(", "Cargo.toml", "cargo add", "RUST_BACKTRACE", "rustc --explain", "consider using the type `u32`", "consider using the type `u64`", "consider using the type `usize`", "consider calling `.as_ref()`", "consider calling `.as_mut()`", "you can `clone` the value and consume it"] { if note.contains(internal) { return true; } }
    false
}

pub fn both_sides_the_same(message: &str) -> Option<String> {
    let expected = match backticked_after(message, "expected ") { Some(__nikaia_value) => __nikaia_value, None => return None };
    let found = match backticked_after(message, "found ") { Some(__nikaia_value) => __nikaia_value, None => return None };
    if expected == found { return Some(expected); }
    None
}

fn backticked_after(message: &str, word: &str) -> Option<String> {
    let c: Vec<scalar> = nikaia_std::list::chars(message.chars());
    let w: Vec<scalar> = nikaia_std::list::chars(word.chars());
    let at = find_text(&c, 0, word);
    if at < 0 { return None; }
    let open = find(&c, at + w.len() as i64, '`');
    if open < 0 { return None; }
    let close = find(&c, open + 1, '`');
    if close < 0 { return None; }
    Some(slice(&c, open + 1, close))
}

fn shared_names(message: &str) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(message.chars());
    let mut out: String = String::from("");
    let mut last = ' ';
    let mut at: i64 = 0;
    while at < c.len() as i64 {
        let mut taken = false;
        for hull in ["std::rc::Rc<", "alloc::rc::Rc<", "std::sync::Arc<", "alloc::sync::Arc<", "Rc<", "Arc<"] {
            if !taken && begins_at(&c, at, hull) {
                let preceded_by_a_name = !hull.contains("::") && at > 0 && (last.is_alphanumeric() || last == '_' || last == ':');
                let h: Vec<scalar> = nikaia_std::list::chars(hull.chars());
                let close = closing_angle(&c, at + h.len() as i64);
                if !preceded_by_a_name && close >= 0 {
                    out.push_str("Shared[");
                    out.push_str(&shared_names(&slice(&c, at + h.len() as i64, close)));
                    out.push(']');
                    last = ']';
                    at = close + 1;
                    taken = true;
                }
            }
        }
        if !taken {
            out.push(*nikaia_std::index::get(&c, nikaia_std::index::at(at)));
            last = *nikaia_std::index::get(&c, nikaia_std::index::at(at));
            at += 1;
        }
    }
    out
}

fn closing_angle(c: &[scalar], from: i64) -> i64 {
    let mut depth = 1;
    for at in from..c.len() as i64 {
        if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '<' { depth += 1; } else if *nikaia_std::index::get(&c, nikaia_std::index::at(at)) == '>' {
            depth -= 1;
            if depth == 0 { return at; }
        }
    }
    -1
}

fn begins_at(c: &[scalar], at: i64, word: &str) -> bool {
    let w: Vec<scalar> = nikaia_std::list::chars(word.chars());
    if (at + w.len() as i64) > c.len() as i64 { return false; }
    for k in 0..w.len() as i64 { if *nikaia_std::index::get(&c, nikaia_std::index::at(at + k)) != *nikaia_std::index::get(&w, (k) as usize) { return false; } }
    true
}

fn replaced(text: &str, from: &str, to: &str) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(text.chars());
    let f: Vec<scalar> = nikaia_std::list::chars(from.chars());
    let mut out: String = String::from("");
    let mut at: i64 = 0;
    let mut next = find_text(&c, 0, from);
    while next >= 0 {
        out.push_str(&slice(&c, at, next));
        out.push_str(to);
        at = next + f.len() as i64;
        next = find_text(&c, at, from);
    }
    out.push_str(&slice(&c, at, c.len() as i64));
    out
}

pub fn said(text: &str) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(text.trim_end().chars());
    if c.is_empty() { return String::from(""); }
    let mut first: String = String::from("");
    first.push(*nikaia_std::index::get(&c, 0));
    let mut out = first.to_uppercase();
    for k in 1..c.len() as i64 { out.push(*nikaia_std::index::get(&c, (k) as usize)); }
    let last = *nikaia_std::index::get(&c, nikaia_std::index::at(c.len() as i64 - 1));
    let mut closed = last == '.' || last == '?' || last == '!' || last == ':';
    if c.len() >= 2 && last == ')' && (*nikaia_std::index::get(&c, nikaia_std::index::at(c.len() as i64 - 2)) == '.' || *nikaia_std::index::get(&c, nikaia_std::index::at(c.len() as i64 - 2)) == '?') { closed = true; }
    let break_at = find_last(&c, '\n');
    if break_at >= 0 && break_at + 1 < c.len() as i64 && *nikaia_std::index::get(&c, nikaia_std::index::at(break_at + 1)) == ' ' { closed = true; }
    if !closed { out.push('.'); }
    out
}

pub fn headed(level: &str, code: &str) -> String {
    if code.is_empty() { return level.to_owned(); }
    format!("{}[{}]", level, code)
}

pub fn word_in(line: &str, column: i64, word: &str) -> (i64, i64) {
    let c: Vec<scalar> = nikaia_std::list::chars(line.chars());
    let w: Vec<scalar> = nikaia_std::list::chars(word.chars());
    if w.is_empty() { return (column, 1); }
    let starts_wordy = a_wordy_char(*nikaia_std::index::get(&w, 0));
    let ends_wordy = a_wordy_char(*nikaia_std::index::get(&w, nikaia_std::index::at(w.len() as i64 - 1)));
    let mut from = column - 1;
    if from < 0 { from = 0; }
    if from > c.len() as i64 { from = c.len() as i64; }
    for start in [from, 0] {
        let mut at = find_text(&c, start, word);
        while at >= 0 {
            let free_before = !starts_wordy || at == 0 || !a_wordy_char(*nikaia_std::index::get(&c, nikaia_std::index::at(at - 1)));
            let after = at + w.len() as i64;
            let free_after = !ends_wordy || after >= c.len() as i64 || !a_wordy_char(*nikaia_std::index::get(&c, nikaia_std::index::at(after)));
            if free_before && free_after { return (at + 1, w.len() as i64); }
            at = find_text(&c, at + w.len() as i64, word);
        }
    }
    (column, 1)
}

fn a_wordy_char(c: scalar) -> bool { c.is_alphanumeric() || c == '_' }


// --- sharing.nika ---

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Fallback {
    PublicSignature,
    PublicField,
    UnseenCall,
    UnseenMethod,
    UncoveredArgument,
    UnseenOrigin,
    ForeignFile,
}

impl Fallback {
    pub fn as_str(&self) -> String {
        match self {
            Fallback::PublicSignature => String::from("a public signature"),
            Fallback::PublicField => String::from("a public field"),
            Fallback::UnseenCall => String::from("a call nothing describes"),
            Fallback::UnseenMethod => String::from("a method nothing describes"),
            Fallback::UncoveredArgument => String::from("an argument position no contract covers"),
            Fallback::UnseenOrigin => String::from("an origin this analysis cannot see"),
            Fallback::ForeignFile => String::from("a slot another file owns"),
        }
    }
    pub fn remedy(&self) -> String {
        match self {
            Fallback::PublicSignature => String::from("nothing here - whether it crosses is decided by callers this build does not read, so an answer would be a promise about somebody else's code"),
            Fallback::PublicField => String::from("keep the field out of the published surface, or accept the atomic - code this build does not read can take the value out of it"),
            Fallback::UnseenCall => String::from("describe the callee in a ledger, so the compiler can see what it does"),
            Fallback::UnseenMethod => String::from("describe the callee in a ledger, so the compiler can see what it does"),
            Fallback::UncoveredArgument => String::from("describe the callee in a ledger, so the compiler can see what it does"),
            Fallback::UnseenOrigin => String::from("write down the call the value came out of, so this analysis can follow it to the allocation"),
            Fallback::ForeignFile => String::from("nothing here - the file that declares the field or the function decides its count, and this run reads only one of the two"),
        }
    }
}

pub fn every_fallback() -> Vec<Fallback> { vec![Fallback::PublicSignature, Fallback::PublicField, Fallback::UnseenCall, Fallback::UnseenMethod, Fallback::UncoveredArgument, Fallback::UnseenOrigin, Fallback::ForeignFile] }

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Decision {
    pub function: String,
    pub value: String,
    pub ty: String,
    pub count: Count,
    pub why: Option<String>,
    pub fallback: Option<Fallback>,
    pub duplications: Vec<String>,
    pub copied_out: Vec<String>,
    pub kept_its_lock: Option<String>,
}

impl Decision {
    pub fn undecided(&self) -> bool { self.fallback.is_some() }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Sharing {
    pub decisions: Vec<Decision>,
    pub summaries: collections::BTreeMap<String, Vec<Class>>,
    pub counts: collections::BTreeMap<String, Count>,
}

impl Sharing {
    pub fn count_of(&self, function: &str, value: &str) -> Count { nikaia_std::index::or(*nikaia_std::index::get(&self.counts, &(slot(function, value))), || Count::Atomic) }
}

pub fn every_count_plain(sharing: &mut Sharing) {
    for i in 0..sharing.decisions.len() as i64 {
        sharing.decisions[nikaia_std::index::at(i)].count = Count::Plain;
        sharing.decisions[nikaia_std::index::at(i)].why = None;
        sharing.decisions[nikaia_std::index::at(i)].fallback = None;
    }
    let mut keys: Vec<String> = vec![];
    for key in sharing.counts.keys() { keys.push(key.to_owned()); }
    for key in keys.iter() { sharing.counts.insert(key.to_owned(), Count::Plain); }
    let mut functions: Vec<String> = vec![];
    for key in sharing.summaries.keys() { functions.push(key.to_owned()); }
    for function in functions.iter() {
        let classes = nikaia_std::index::or(match *nikaia_std::index::get(&sharing.summaries, function) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        let mut plain: Vec<Class> = vec![];
        for class in classes.iter() { plain.push(Class { members: class.members.to_owned(), count: Count::Plain }); }
        sharing.summaries.insert(function.to_owned(), plain);
    }
}

pub fn sharing_report(sharing: &Sharing) -> String {
    if sharing.decisions.is_empty() { return String::from("no `Shared` value here, so there is nothing to choose.\n"); }
    let mut out: String = String::from("");
    let mut at: String = String::from("");
    let mut atomic: i64 = 0;
    let mut undecided = 0;
    let mut caught: Vec<String> = vec![];
    for decision in sharing.decisions.iter() {
        if at != decision.function {
            out.push_str(&format!("{}:\n", decision.function));
            at = decision.function.to_owned();
        }
        let count = decision.count.as_str();
        out.push_str(&format!("    {} `{}` ({})\n", padded_right(&count, 7), decision.value, decision.ty));
        out.push_str(&why_line(decision));
        out.push_str(&kept_line((decision.kept_its_lock).as_deref()));
        for site in decision.copied_out.iter() { out.push_str(&format!("             copied out: {} each time - `access` reads it in place\n", site)); }
        if decision.duplications.is_empty() { out.push_str("             one handle, so the count is never stepped\n"); }
        for site in decision.duplications.iter() { out.push_str(&format!("             duplicated: {}\n", site)); }
        if decision.count != Count::Plain { atomic += 1; }
        if decision.undecided() {
            undecided += 1;
            caught.push(fallback_text((decision.fallback).as_ref()));
        }
    }
    let all = sharing.decisions.len() as i64;
    let plain = all - atomic;
    out.push_str(&format!("\n{} `Shared` value(s): {} plain, {} atomic, of which {} because this analysis could not decide.\n", all, plain, atomic, undecided));
    out.push_str("An atomic count is the safe default. A plain count is an optimisation, and where it isn't taken the reason is one of these:\n");
    for fallback in every_fallback() {
        let said = fallback.as_str();
        let mark = if nikaia_std::list::contains(&caught, &said) { "*" } else { " " };
        let remedy = fallback.remedy();
        out.push_str(&format!("  {} {} - {}\n", mark, said, remedy));
    }
    out.push_str("The ones that need a contract get sharper as `std`'s contracts grow.\n");
    out
}

fn fallback_text(fallback: Option<&Fallback>) -> String {
    let row = match fallback { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
    row.as_str()
}

fn kept_line(kept: Option<&str>) -> String {
    let said = match kept { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
    format!("             {}\n", said)
}

fn why_line(decision: &Decision) -> String { why_said(decision, (decision.why).as_deref()) }

fn why_said(decision: &Decision, said: Option<&str>) -> String {
    let why = match said { Some(__nikaia_value) => __nikaia_value, None => return String::from("             nothing crosses a thread with it, so the count is lowered\n") };
    if decision.undecided() { return format!("             could not decide: {}\n", why); }
    if decision.count == Count::Word { return format!("             crosses: {}\n             a word, and no door over several locks takes it, so its `update` is a compare-and-swap and there is no lock\n", why); }
    format!("             crosses: {}\n", why)
}

pub fn slot(function: &str, name: &str) -> String { format!("{}::{}", function, name) }

pub fn split_slot(key: &str) -> (String, String) {
    let parts: Vec<&str> = key.split("::").collect::<Vec<_>>();
    if parts.len() < 2 { return (String::from(""), key.to_owned()); }
    let name = (*nikaia_std::index::get(&parts, nikaia_std::index::at(parts.len() as i64 - 1))).to_owned();
    let mut function: Vec<String> = vec![];
    for i in 0..parts.len() as i64 - 1 { function.push((*nikaia_std::index::get(&parts, (i) as usize)).to_owned()); }
    (function.join("::"), name)
}

pub fn holds_a_word(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; !view && name == "SharedMut" && args.len() == 1 && a_word(nikaia_std::index::get(&args, 0)) },
        _ => false,
    }
}

const WORD_TYPES: [&str; 13] = ["i8", "i16", "i32", "i64", "u8", "u16", "u32", "u64", "f32", "f64", "bool", "char", "scalar"];

fn a_word(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, view } => { let view = *view; !view && args.is_empty() && one_of(&WORD_TYPES, name) },
        _ => false,
    }
}

pub fn held_that_does_not_copy(ty: &Ty) -> Option<String> {
    match ty {
        Ty::Named { name, args, .. } => a_held_value(ty, name, args),
        _ => None,
    }
}

fn a_held_value(ty: &Ty, name: &str, args: &[Ty]) -> Option<String> {
    if name != "SharedMut" || args.len() != 1 || holds_a_word(ty) || (*nikaia_std::index::get(&args, 0)).is_unknown() { return None; }
    Some((*nikaia_std::index::get(&args, 0)).text())
}

pub fn literal_type(expr: &Expr) -> Option<String> {
    match expr {
        Expr::LitStr { .. } => Some(String::from("String")),
        Expr::LitInterpolated { .. } => Some(String::from("String")),
        Expr::LitInt { .. } => Some(String::from("i64")),
        Expr::LitFloat(_) => Some(String::from("f64")),
        Expr::LitBool(_) => Some(String::from("bool")),
        Expr::LitChar(_) => Some(String::from("scalar")),
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); literal_type(expr) },
        _ => None,
    }
}

pub fn published_reason(key: &str, at: &str) -> String {
    if at == RESULT_POSITION { return format!("`{}` is public and hands a `Shared` back, so what the caller does with it is in a unit this build cannot see", key); }
    format!("`{}` is public, so its callers are in a unit this build cannot see, and one of them may cross a thread with it", key)
}

pub fn handed_on_to(key: &str, param: &str) -> String { format!("handed to `{}` as `{}`, which takes a handle of its own", key, param) }

pub fn unseen(callee: Option<&str>) -> String {
    let named = nikaia_std::index::or(callee, || "the callee");
    format!("the compiler knows nothing about `{}`, so it has to assume it might start a thread", named)
}

pub fn by_value_shared(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, view, .. } => { let view = *view; !view && (name == "Shared" || name == "SharedMut") },
        _ => false,
    }
}

pub fn is_hull(name: &str) -> bool { name == "Shared" || name == "SharedMut" || name == "Locked" }

pub fn holds_shared(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, .. } => name == "Shared" || name == "SharedMut" || any_holds_shared(args),
        Ty::Tuple(parts) => any_holds_shared(parts),
        _ => false,
    }
}

fn any_holds_shared(types: &[Ty]) -> bool {
    for ty in types.iter() { if holds_shared(ty) { return true; } }
    false
}

pub fn shared_fields(ty: &str, asked: &Asked<'_>) -> Vec<String> {
    let name = without_a_view(ty);
    let contract = match ledger_type(&name, asked.own, asked.library) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    let mut out: Vec<String> = vec![];
    for field in contract.fields.iter() { if holds_shared(&field.ty) { out.push(format!("{}.{}", name, field.name)); } }
    out
}

pub fn declared_field_type(ty: &str, field: &str, asked: &Asked<'_>) -> Option<Ty> {
    let contract = match ledger_type(&without_a_view(ty), asked.own, asked.library) { Some(__nikaia_value) => __nikaia_value, None => return None };
    for declared in contract.fields.iter() { if declared.name == field { return Some(declared.ty.clone()); } }
    None
}

fn without_a_view(ty: &str) -> String {
    let mut out: String = String::from("");
    let mut leading = true;
    for c in ty.chars() {
        if leading && c == '&' { continue; }
        leading = false;
        out.push(c);
    }
    out
}

pub fn rust_name(count: Count) -> String {
    match count {
        Count::Plain => String::from("std::rc::Rc"),
        Count::Word => String::from("std::sync::Arc"),
        Count::Atomic => String::from("std::sync::Arc"),
    }
}

pub fn lock_name(count: Count) -> String {
    match count {
        Count::Plain => String::from("nikaia_std::lock::Local"),
        Count::Word => String::from("nikaia_std::lock::Word"),
        Count::Atomic => String::from("nikaia_std::lock::Crossing"),
    }
}

pub const FIELDS: &str = "<field>";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Handle {
    pub function: String,
    pub value: String,
    pub ty: Ty,
    pub internal: bool,
    pub position: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Forced {
    pub key: String,
    pub why: String,
    pub fallback: Option<Fallback>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Slots {
    pub declared_here: collections::BTreeSet<String>,
    pub handles: collections::BTreeMap<String, Handle>,
    pub index: collections::BTreeMap<String, i64>,
    pub parent: Vec<i64>,
    pub forced: Vec<Forced>,
    pub duplicated: Vec<(String, String)>,
    pub held_together: Vec<String>,
    pub copies: Vec<(String, String)>,
}

impl Slots {
    pub fn new(declared_here: collections::BTreeSet<String>) -> Slots { Slots { declared_here, handles: collections::BTreeMap::new(), index: collections::BTreeMap::new(), parent: vec![], forced: vec![], duplicated: vec![], held_together: vec![], copies: vec![] } }
    pub fn id(&mut self, key: &str) -> i64 {
        let found = *nikaia_std::index::get(&self.index, key);
        if found.is_some() { return nikaia_std::index::or(found, || 0); }
        let fresh = self.parent.len() as i64;
        self.parent.push(fresh);
        self.index.insert(key.to_owned(), fresh);
        fresh
    }
    pub fn root(&mut self, start: i64) -> i64 {
        let mut at = start;
        while *nikaia_std::index::get(&self.parent, nikaia_std::index::at(at)) != at {
            let up = *nikaia_std::index::get(&self.parent, nikaia_std::index::at(at));
            { let __nikaia_stored = *nikaia_std::index::get(&self.parent, nikaia_std::index::at(up)); nikaia_std::index::set(&mut self.parent, nikaia_std::index::at(at), __nikaia_stored); }
            at = *nikaia_std::index::get(&self.parent, nikaia_std::index::at(at));
        }
        at
    }
    pub fn class_of(&mut self, key: &str) -> i64 {
        let id = self.id(key);
        self.root(id)
    }
    pub fn join(&mut self, left: &str, right: &str) {
        let one = self.class_of(left);
        let other = self.class_of(right);
        if one != other { { let __nikaia_stored = other; nikaia_std::index::set(&mut self.parent, nikaia_std::index::at(one), __nikaia_stored); } }
    }
    pub fn note(&mut self, function: &str, value: &str, ty: Ty, internal: bool, position: bool) {
        let key = slot(function, value);
        self.id(&key);
        if !self.handles.contains_key(&key) { self.handles.insert(key.to_owned(), Handle { function: function.to_owned(), value: value.to_owned(), ty, internal, position }); }
    }
    pub fn force(&mut self, function: &str, value: &str, why: String, fallback: Option<Fallback>) {
        let key = slot(function, value);
        self.id(&key);
        self.forced.push(Forced { key, why, fallback });
    }
    pub fn duplicates(&mut self, function: &str, value: &str, site: String) {
        let key = slot(function, value);
        self.id(&key);
        self.duplicated.push((key, site));
    }
    fn foreign_slots_hold_the_floor(&mut self) {
        let field_prefix = format!("{}::", FIELDS);
        let mut foreign: Vec<(String, String)> = vec![];
        for key in self.index.keys() {
            if !key.contains("::") { continue; }
            let mut owner = before_last(key, "::");
            let mut named = key.to_owned();
            if key.starts_with(&field_prefix) {
                let parts: Vec<&str> = key.splitn(2, "::").collect::<Vec<_>>();
                named = (*nikaia_std::index::get(&parts, 1)).to_owned();
                owner = before_last(&named, ".");
            }
            if !self.declared_here.contains(&owner) { foreign.push((key.to_owned(), named)); }
        }
        for (key, named) in foreign.iter() {
            let why = format!("`{}` belongs to another file of this package, and that file's own pass decides its count - this one reads only one of the two", named);
            self.forced.push(Forced { key: key.to_owned(), why, fallback: Some(Fallback::ForeignFile) });
        }
    }
}

fn before_last(text: &str, separator: &str) -> String {
    let parts: Vec<&str> = text.split(separator).collect::<Vec<_>>();
    if parts.len() < 2 { return text.to_owned(); }
    let mut kept: Vec<String> = vec![];
    for i in 0..parts.len() as i64 - 1 { kept.push((*nikaia_std::index::get(&parts, (i) as usize)).to_owned()); }
    kept.join(separator)
}

pub fn decided(slots: &mut Slots) -> Sharing {
    slots.foreign_slots_hold_the_floor();
    let mut why_of: collections::BTreeMap<i64, String> = collections::BTreeMap::new();
    let mut fallback_of: collections::BTreeMap<i64, Fallback> = collections::BTreeMap::new();
    let mut floor: collections::BTreeSet<i64> = collections::BTreeSet::new();
    let forced = slots.forced.to_owned();
    for one in forced.iter() {
        let root = slots.class_of(&one.key);
        if one.fallback.is_some() { floor.insert(root); }
        if !why_of.contains_key(&root) || fallback_of.contains_key(&root) && one.fallback.is_none() {
            why_of.insert(root, one.why.to_owned());
            set_fallback(&mut fallback_of, root, one.fallback);
        }
    }
    let mut held: collections::BTreeSet<i64> = collections::BTreeSet::new();
    let together = slots.held_together.to_owned();
    for key in together.iter() { held.insert(slots.class_of(key)); }
    let keys: Vec<String> = handle_keys(&slots);
    let mut not_a_word: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for key in keys.iter() {
        let root = slots.class_of(key);
        if !holds_a_word(&handle_type(&slots, key)) { not_a_word.insert(root); }
    }
    let duplicated = sites_by_slot(&slots.duplicated);
    let copied_out = sites_by_slot(&slots.copies);
    let mut decisions: Vec<Decision> = vec![];
    let mut counts: collections::BTreeMap<String, Count> = collections::BTreeMap::new();
    let mut classes: collections::BTreeMap<String, collections::BTreeMap<i64, Class>> = collections::BTreeMap::new();
    for key in keys.iter() {
        let root = slots.class_of(key);
        let handle = match match *nikaia_std::index::get(&slots.handles, key) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => continue };
        let a_word = !not_a_word.contains(&root);
        let mut count = Count::Plain;
        let mut why: Option<String> = None;
        let mut fallback: Option<Fallback> = None;
        if why_of.contains_key(&root) {
            why = match *nikaia_std::index::get(&why_of, &root) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
            fallback = nikaia_std::index::or_maybe(*nikaia_std::index::get(&fallback_of, &root), || None);
            count = Count::Atomic;
            if fallback.is_none() && a_word && !floor.contains(&root) && !held.contains(&root) { count = Count::Word; }
        }
        if handle.position { put_in_class(&mut classes, &handle.function, root, &handle.value, count); }
        counts.insert(key.to_owned(), count);
        if !handle.internal {
            decisions.push(Decision { function: handle.function.to_owned(), value: handle.value.to_owned(), ty: handle.ty.text(), count, why, fallback, duplications: nikaia_std::index::or(match *nikaia_std::index::get(&duplicated, key) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || vec![].into()), copied_out: nikaia_std::index::or(match *nikaia_std::index::get(&copied_out, key) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || vec![].into()), kept_its_lock: lock_kept(&count, a_word, held.contains(&root)) });
        }
    }
    let mut summaries: collections::BTreeMap<String, Vec<Class>> = collections::BTreeMap::new();
    for (function, roots) in classes.iter() {
        let mut found: Vec<Class> = vec![];
        for (_, class) in roots.iter() { found.push(Class { members: sorted_once(&class.members), count: class.count }); }
        summaries.insert(function.to_owned(), in_class_order(&found));
    }
    Sharing { decisions, summaries, counts }
}

fn set_fallback(fallback_of: &mut collections::BTreeMap<i64, Fallback>, root: i64, fallback: Option<Fallback>) {
    fallback_of.remove(&root);
    let row = match fallback { Some(__nikaia_value) => __nikaia_value, None => return };
    fallback_of.insert(root, row);
}

fn handle_keys(slots: &Slots) -> Vec<String> {
    let mut keys: Vec<String> = vec![];
    for key in slots.handles.keys() { keys.push(key.to_owned()); }
    keys
}

fn handle_type(slots: &Slots, key: &str) -> Ty {
    let handle = match *nikaia_std::index::get(&slots.handles, key) { Some(__nikaia_value) => __nikaia_value, None => return Ty::Unknown };
    handle.ty.clone()
}

fn sites_by_slot(pairs: &[(String, String)]) -> collections::BTreeMap<String, Vec<String>> {
    let mut out: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for (key, site) in pairs.iter() {
        let mut sites = nikaia_std::index::or(match *nikaia_std::index::get(&out, key) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        if !nikaia_std::list::contains(&sites, &site) { sites.push(site.to_owned()); }
        out.insert(key.to_owned(), sites);
    }
    out
}

fn put_in_class(classes: &mut collections::BTreeMap<String, collections::BTreeMap<i64, Class>>, function: &str, root: i64, member: &str, count: Count) {
    let mut roots = nikaia_std::index::or(match *nikaia_std::index::get(&classes, function) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || collections::BTreeMap::new().into());
    let mut class = nikaia_std::index::or(match *nikaia_std::index::get(&roots, &root) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || Class { members: vec![], count });
    class.members.push(member.to_owned());
    class.count = class.count.join(count);
    roots.insert(root, class);
    classes.insert(function.to_owned(), roots);
}

fn lock_kept(count: &Count, a_word: bool, held_together: bool) -> Option<String> {
    if *count != Count::Atomic || !a_word { return None; }
    if held_together { return Some(String::from("a word, but a door over several locks takes it, and a compare-and-swap cannot be held, so it keeps its lock")); }
    Some(String::from("a word, but the floor answered for it rather than a crossing, so it keeps its lock"))
}

fn sorted_once(members: &[String]) -> Vec<String> {
    let mut sorted = members.to_owned();
    sorted.sort();
    let mut out: Vec<String> = vec![];
    for one in sorted.iter() { if out.is_empty() || *nikaia_std::index::get(&out, nikaia_std::index::at(out.len() as i64 - 1)) != *one { out.push(one.to_owned()); } }
    out
}

fn in_class_order(classes: &[Class]) -> Vec<Class> {
    let mut out: Vec<Class> = vec![];
    for class in classes.iter() {
        let mut at = out.len() as i64;
        while at > 0 && class_before(class, nikaia_std::index::get(&out, nikaia_std::index::at(at - 1))) { at -= 1; }
        out.insert(nikaia_std::count::of(at), class.clone());
    }
    out
}

fn class_before(a: &Class, b: &Class) -> bool {
    let shorter = if (a.members.len() as i64) < b.members.len() as i64 { a.members.len() as i64 } else { b.members.len() as i64 };
    for i in 0..shorter { if *nikaia_std::index::get(&a.members, (i) as usize) != *nikaia_std::index::get(&b.members, (i) as usize) { return *nikaia_std::index::get(&a.members, (i) as usize) < *nikaia_std::index::get(&b.members, (i) as usize); } }
    if (a.members.len() as i64) != b.members.len() as i64 { return (a.members.len() as i64) < b.members.len() as i64; }
    a.count.rank() < b.count.rank()
}

const PARALLEL: [&str; 3] = ["par_iter", "par_fold", "par_map"];

pub fn declared_here(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for item in items.iter() {
        match &item.node {
            Item::Struct { name, .. } => {
                let name = *name;
                out.insert(names.resolve(name).to_owned());
            },
            Item::Enum { name, .. } => {
                let name = *name;
                out.insert(names.resolve(name).to_owned());
            },
            Item::Fn { name, .. } => {
                let name = *name;
                let own = a_symbols_text(names, name);
                if !own.is_empty() { out.insert(own); }
            },
            Item::Impl { target, methods, .. } => {
                let owner = names.resolve(target.name).to_owned();
                for method in methods.iter() {
                    let own = method_name(names, &method.node);
                    if !own.is_empty() { out.insert(format!("{}::{}", owner, own)); }
                }
                out.insert(owner);
            },
            _ => { },
        }
    }
    out
}

fn method_name(names: &winnow_grammar::InternerContext, item: &Item) -> String {
    match item {
        Item::Fn { name, .. } => { let name = *name; if name.is_none() { String::from("new") } else { a_symbols_text(names, name) } },
        _ => String::from(""),
    }
}

pub fn allocates_here(expr: &Expr, asked: &Asked<'_>) -> bool {
    match expr {
        Expr::LitInt { .. } => true,
        Expr::LitFloat(_) => true,
        Expr::LitStr { .. } => true,
        Expr::LitInterpolated { .. } => true,
        Expr::LitChar(_) => true,
        Expr::LitBool(_) => true,
        Expr::LitNull => true,
        Expr::StructLit { .. } => true,
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); a_call_that_allocates((call_path(func, asked.names)).as_deref(), asked) },
        Expr::MethodCall { method, .. } => { let method = *method; hands_back_a_plain_value(asked.names.resolve(method), asked) },
        Expr::SafeMethod { method, .. } => { let method = *method; hands_back_a_plain_value(asked.names.resolve(method), asked) },
        _ => false,
    }
}

fn a_call_that_allocates(path: Option<&str>, asked: &Asked<'_>) -> bool {
    let callee = match path { Some(__nikaia_value) => __nikaia_value, None => return false };
    is_hull(callee) || hands_back_a_plain_value(callee, asked)
}

pub fn hands_back_a_plain_value(callee: &str, asked: &Asked<'_>) -> bool {
    let suffix = format!("::{}", callee);
    if has_an_entry(asked.own, callee, &suffix) { return plain_in(asked.own, callee, &suffix); }
    plain_in(asked.library, callee, &suffix)
}

fn has_an_entry(ledger: &Ledger, callee: &str, suffix: &str) -> bool {
    if ledger.functions.contains_key(callee) { return true; }
    for key in ledger.functions.keys() { if key.ends_with(&suffix) { return true; } }
    false
}

fn plain_in(ledger: &Ledger, callee: &str, suffix: &str) -> bool {
    let exact = *nikaia_std::index::get(&ledger.functions, callee);
    if exact.is_some() { return a_plain_result(exact); }
    for (key, contract) in ledger.functions.iter() { if key.ends_with(&suffix) { return a_plain_result(Some(contract)); } }
    false
}

fn a_plain_result(contract: Option<&FnContract>) -> bool {
    let found = match contract { Some(__nikaia_value) => __nikaia_value, None => return false };
    let signature = match found.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    let result = match signature.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return false };
    !result.is_unknown() && !holds_shared(result)
}

pub fn origin_reason(expr: &Expr, names: &winnow_grammar::InternerContext) -> String {
    let from = where_it_came_from(expr, names);
    format!("{}, so this analysis did not watch the allocation being made - and the count belongs to the allocation. A call handed to another thread hands its result back across one (ADR-292)", from)
}

fn where_it_came_from(expr: &Expr, names: &winnow_grammar::InternerContext) -> String {
    match expr {
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); a_call_that_hands_it_back((call_path(func, names)).as_deref()) },
        Expr::MethodCall { method, .. } => { let method = *method; format!("`{}` hands it back", names.resolve(method)) },
        Expr::SafeMethod { method, .. } => { let method = *method; format!("`{}` hands it back", names.resolve(method)) },
        Expr::Field { name, .. } => { let name = *name; format!("it is read out of `{}`", names.resolve(name)) },
        Expr::Index { .. } => String::from("it is read out of a collection"),
        _ => String::from("it comes from an expression this analysis does not follow"),
    }
}

fn a_call_that_hands_it_back(path: Option<&str>) -> String {
    let callee = match path { Some(__nikaia_value) => __nikaia_value, None => return String::from("a call hands it back") };
    format!("`{}` hands it back", callee)
}

pub fn named_handle(expr: &Expr, names: &winnow_grammar::InternerContext, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    match expr {
        Expr::Variable(name) => { let name = *name; a_handle_in_scope(names.resolve(name), scope) },
        Expr::Block(block) => a_handle_at_the_tail(block, names, scope),
        _ => None,
    }
}

fn a_handle_in_scope(name: &str, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    let ty = match *nikaia_std::index::get(&scope, name) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if holds_shared(ty) { return Some(name.to_owned()); }
    None
}

fn a_handle_at_the_tail(block: &Block, names: &winnow_grammar::InternerContext, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    if block.stmts.is_empty() { return None; }
    match &nikaia_std::index::get(&block.stmts, nikaia_std::index::at(block.stmts.len() as i64 - 1)).node {
        Stmt::Expr(tail) => named_handle(tail, names, scope),
        _ => None,
    }
}

pub fn named_type(expr: &Expr, names: &winnow_grammar::InternerContext, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    match expr {
        Expr::Variable(name) => { let name = *name; scope_type_name(names.resolve(name), scope) },
        _ => None,
    }
}

fn scope_type_name(name: &str, scope: &collections::BTreeMap<String, Ty>) -> Option<String> {
    let ty = match *nikaia_std::index::get(&scope, name) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(without_a_view(&ty.text()))
}

pub fn walks_in_parallel(receiver: &Expr, names: &winnow_grammar::InternerContext, parallel: &collections::BTreeSet<String>) -> bool {
    match receiver {
        Expr::Variable(name) => { let name = *name; parallel.contains(names.resolve(name)) },
        Expr::MethodCall { receiver, method, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; a_parallel_method(names.resolve(method)) || walks_in_parallel(receiver, names, parallel) },
        _ => false,
    }
}

pub fn a_parallel_method(method: &str) -> bool {
    for one in PARALLEL.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn call_path(func: &Expr, names: &winnow_grammar::InternerContext) -> Option<String> {
    match func {
        Expr::Variable(name) => { let name = *name; Some(names.resolve(name).to_owned()) },
        Expr::Path(segments) => Some(joined_segments(segments, names)),
        _ => None,
    }
}

const RESULT: &str = "<result>";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SharingWalk {
    pub slots: Slots,
    pub parallel: collections::BTreeSet<String>,
    pub function: String,
    pub scope: collections::BTreeMap<String, Ty>,
}

pub fn sharing_of(program: &Program, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, crossings_are_possible: bool) -> Sharing {
    let mut walk = SharingWalk { slots: Slots::new(declared_here(asked.names, &program.items)), parallel: collections::BTreeSet::new(), function: String::from(""), scope: collections::BTreeMap::new() };
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { .. } => sharing_function(&item.node, "", asked, holes_of, ty_of, &mut walk),
            Item::Impl { target, methods, .. } => {
                let owner = asked.names.resolve(target.name).to_owned();
                for method in methods.iter() { sharing_function(&method.node, &owner, asked, holes_of, ty_of, &mut walk); }
            },
            Item::Struct { name, fields, is_public, .. } => {
                let is_public = *is_public; let name = *name;
                if is_public { public_fields(asked.names.resolve(name), fields, asked, ty_of, &mut walk); }
            },
            _ => { },
        }
    }
    let mut sharing = decided(&mut walk.slots);
    if !crossings_are_possible { every_count_plain(&mut sharing); }
    sharing
}

fn public_fields(owner: &str, fields: &[FieldDef], asked: &Asked<'_>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    for field in fields.iter() {
        if !field.is_public { continue; }
        let ty = ty_of(&field.ty);
        if !holds_shared(&ty) { continue; }
        let key = format!("{}.{}", owner, asked.names.resolve(field.name));
        walk.slots.note(FIELDS, &key, ty, true, false);
        walk.slots.force(FIELDS, &key, format!("`{}` is a public field of a public type, so code this build cannot see may take the value out of it and cross with it", key), Some(Fallback::PublicField));
    }
}

fn sharing_function(item: &Item, owner: &str, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    match item {
        Item::Fn { name, args, body, ret_type, is_public, .. } => {
            let is_public = *is_public; let name = *name;
            walk.function = key_of_function((name).as_ref(), owner, asked.names);
            walk.scope = collections::BTreeMap::new();
            for arg in args.iter() {
                let ty = ty_of(&arg.ty);
                let named = asked.names.resolve(arg.name).to_owned();
                position(&named, &ty, is_public, asked, walk);
                walk.scope.insert(named, ty);
            }
            if ret_type.is_some() {
                let result = match ret_type { Some(__nikaia_value) => __nikaia_value, None => return };
                position(RESULT, &ty_of(result), is_public, asked, walk);
            }
            sharing_block(body, asked, holes_of, ty_of, walk);
        },
        _ => { },
    }
}

fn position(named: &str, ty: &Ty, is_public: bool, asked: &Asked<'_>, walk: &mut SharingWalk) {
    let function = walk.function.to_owned();
    if holds_shared(ty) {
        walk.slots.note(&function, named, ty.clone(), named == RESULT, true);
        if is_public { walk.slots.force(&function, named, published_reason(&function, named), Some(Fallback::PublicSignature)); }
    } else if is_public { for field in shared_fields(&ty.text(), asked) { walk.slots.force(FIELDS, &field, published_reason(&function, named), Some(Fallback::PublicSignature)); } }
}

fn sharing_block(block: &Block, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) { for stmt in block.stmts.iter() { sharing_statement(&stmt.node, asked, holes_of, ty_of, walk); } }

fn sharing_statement(stmt: &Stmt, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    match stmt {
        Stmt::Let { names, ty, value, .. } => {
            if names.len() != 1 { return; }
            let_binding(asked.names.resolve(*nikaia_std::index::get(&names, 0)).to_owned(), (ty).as_ref(), value, asked, ty_of, walk);
            sharing_expression(value, asked, holes_of, ty_of, walk);
        },
        Stmt::Comptime { .. } => { },
        Stmt::Assign { target, value, .. } => {
            let target_slot = slot_of(target, asked, walk);
            if target_slot.is_some() {
                let known = nikaia_std::index::or(target_slot, || "".into());
                let source = slot_of(value, asked, walk);
                if source.is_none() {
                    let (at, named) = split_slot(&known);
                    origin_unseen(&at, &named, value, asked, walk);
                } else { walk.slots.join(&known, nikaia_std::index::or(source.as_deref(), || "")); }
            }
            sharing_expression(target, asked, holes_of, ty_of, walk);
            sharing_expression(value, asked, holes_of, ty_of, walk);
        },
        Stmt::For { iter, body, .. } => {
            sharing_expression(iter, asked, holes_of, ty_of, walk);
            sharing_block(body, asked, holes_of, ty_of, walk);
        },
        Stmt::While { cond, body } => {
            sharing_expression(cond, asked, holes_of, ty_of, walk);
            sharing_block(body, asked, holes_of, ty_of, walk);
        },
        Stmt::Return(value) => {
            let returned = match value { Some(__nikaia_value) => __nikaia_value, None => return };
            hands_back(returned, asked, walk);
            sharing_expression(returned, asked, holes_of, ty_of, walk);
        },
        Stmt::Expr(value) => {
            hands_back(value, asked, walk);
            sharing_expression(value, asked, holes_of, ty_of, walk);
        },
        _ => { },
    }
}

fn let_binding(named: String, written: Option<&Type>, value: &Expr, asked: &Asked<'_>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    if walks_in_parallel(value, asked.names, &walk.parallel) { walk.parallel.insert(named.to_owned()); }
    let aliased = named_handle(value, asked.names, &walk.scope);
    let ty = match binding_type(written, (aliased).as_deref(), value, asked, ty_of, &walk.scope) { Some(__nikaia_value) => __nikaia_value, None => return };
    if holds_shared(&ty) {
        let function = walk.function.to_owned();
        walk.slots.note(&function, &named, ty.clone(), false, false);
        if aliased.is_some() { walk.slots.join(&slot(&function, &named), &slot(&function, nikaia_std::index::or(aliased.as_deref(), || ""))); } else {
            let source = slot_of(value, asked, walk);
            if source.is_some() { walk.slots.join(&slot(&function, &named), nikaia_std::index::or(source.as_deref(), || "")); } else if !(by_value_shared(&ty) && allocates_here(value, asked)) { origin_unseen(&function, &named, value, asked, walk); }
        }
    }
    walk.scope.insert(named, ty);
}

fn binding_type(written: Option<&Type>, aliased: Option<&str>, value: &Expr, asked: &Asked<'_>, ty_of: &impl Fn(&Type) -> Ty, scope: &collections::BTreeMap<String, Ty>) -> Option<Ty> {
    if written.is_some() { return Some(ty_of(match written { Some(__nikaia_value) => __nikaia_value, None => return None })); }
    if aliased.is_some() {
        let handle = match aliased { Some(__nikaia_value) => __nikaia_value, None => return None };
        let ty = match *nikaia_std::index::get(&scope, handle) { Some(__nikaia_value) => __nikaia_value, None => return None };
        return Some(ty.clone());
    }
    match value {
        Expr::StructLit { name, .. } => { let name = *name; Some(plain_type(asked.names.resolve(name))) },
        Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); hull_written(func, args, asked) },
        _ => None,
    }
}

fn hull_written(func: &Expr, args: &[Expr], asked: &Asked<'_>) -> Option<Ty> {
    let named = match func {
        Expr::Variable(name) => { let name = *name; asked.names.resolve(name).to_owned() },
        _ => return None,
    };
    if !is_hull(&named) { return None; }
    if args.len() == 1 {
        let held = match literal_type(nikaia_std::index::get(&args, 0)) { Some(__nikaia_value) => __nikaia_value, None => return Some(plain_type(&named)) };
        return Some(Ty::Named { name: named, args: vec![plain_type(&held)], view: false });
    }
    Some(plain_type(&named))
}

fn plain_type(name: &str) -> Ty { Ty::Named { name: name.to_owned(), args: vec![], view: false } }

fn hands_back(value: &Expr, asked: &Asked<'_>, walk: &mut SharingWalk) {
    let source = match slot_of(value, asked, walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    walk.slots.join(&slot(&walk.function, RESULT), &source);
}

fn origin_unseen(function: &str, named: &str, value: &Expr, asked: &Asked<'_>, walk: &mut SharingWalk) { walk.slots.force(function, named, origin_reason(value, asked.names), Some(Fallback::UnseenOrigin)); }

fn a_crossing_reaches(named: &str, why: &str, fallback: Option<Fallback>, asked: &Asked<'_>, walk: &mut SharingWalk) {
    let ty = match match *nikaia_std::index::get(&walk.scope, named) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    if holds_shared(&ty) {
        walk.slots.force(&walk.function, named, why.to_owned(), fallback);
        return;
    }
    for field in shared_fields(&ty.text(), asked) { walk.slots.force(FIELDS, &field, why.to_owned(), fallback); }
}

fn slot_of(expr: &Expr, asked: &Asked<'_>, walk: &mut SharingWalk) -> Option<String> {
    let handle = named_handle(expr, asked.names, &walk.scope);
    if handle.is_some() { return Some(slot(&walk.function, nikaia_std::index::or(handle.as_deref(), || ""))); }
    match expr {
        Expr::Field { base, name } => { let base = nikaia_std::boxed::open(base); let name = *name; field_slot(base, asked.names.resolve(name), asked, walk) },
        _ => None,
    }
}

fn field_slot(base: &Expr, field: &str, asked: &Asked<'_>, walk: &mut SharingWalk) -> Option<String> {
    let owner = match named_type(base, asked.names, &walk.scope) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let ty = match declared_field_type(&owner, field, asked) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if !holds_shared(&ty) { return None; }
    let key = format!("{}.{}", owner, field);
    walk.slots.note(FIELDS, &key, ty, true, false);
    Some(slot(FIELDS, &key))
}

fn sharing_expression(expr: &Expr, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    match expr {
        Expr::Spawn { body, .. } => {
            let body = nikaia_std::boxed::open(body);
            for named in names_used_by(body, asked) {
                if a_handle_by_value(&named, &walk) { walk.slots.duplicates(&walk.function, &named, String::from("used by a `spawn` body, which takes a handle of its own")); }
                a_crossing_reaches(&named, "a `spawn` body uses it, and a task runs on a thread of its own", None, asked, walk);
            }
            sharing_expression(body, asked, holes_of, ty_of, walk);
        },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            let callee = call_path(func, asked.names);
            let path = nikaia_std::index::or(match callee.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || "".into());
            if path == "access_all" || path == "update_all" {
                for arg in args.iter() {
                    let handle = match named_handle(arg, asked.names, &walk.scope) { Some(__nikaia_value) => __nikaia_value, None => continue };
                    walk.slots.held_together.push(slot(&walk.function, &handle));
                }
            }
            sharing_arguments(&SharingCall { callee, is_method: false }, args, config, asked, holes_of, ty_of, walk);
            sharing_expression(func, asked, holes_of, ty_of, walk);
        },
        Expr::MethodCall { .. } => sharing_method(expr, asked, holes_of, ty_of, walk),
        Expr::SafeMethod { .. } => sharing_method(expr, asked, holes_of, ty_of, walk),
        Expr::StructLit { name, fields } => {
            let name = *name;
            let owner = asked.names.resolve(name).to_owned();
            for field in fields.iter() { struct_field(&owner, field, asked, holes_of, ty_of, walk); }
        },
        Expr::LitInterpolated { .. } => { for hole in holes_of(expr) { sharing_expression(&hole, asked, holes_of, ty_of, walk); } },
        Expr::Closure { body, .. } => {
            a_kept_lambda_uses(expr, asked, walk);
            sharing_block(body, asked, holes_of, ty_of, walk);
        },
        Expr::Block(block) => sharing_block(block, asked, holes_of, ty_of, walk),
        Expr::Overlap(block) => sharing_block(block, asked, holes_of, ty_of, walk),
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            sharing_expression(cond, asked, holes_of, ty_of, walk);
            sharing_block(then_branch, asked, holes_of, ty_of, walk);
            sharing_block(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, asked, holes_of, ty_of, walk);
        },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            sharing_expression(value, asked, holes_of, ty_of, walk);
            for arm in arms.iter() { sharing_expression(&arm.body, asked, holes_of, ty_of, walk); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            sharing_expression(lhs, asked, holes_of, ty_of, walk);
            sharing_expression(rhs, asked, holes_of, ty_of, walk);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); sharing_expression(expr, asked, holes_of, ty_of, walk) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); sharing_expression(inner, asked, holes_of, ty_of, walk) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); sharing_expression(inner, asked, holes_of, ty_of, walk) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); sharing_expression(expr, asked, holes_of, ty_of, walk) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); sharing_expression(base, asked, holes_of, ty_of, walk) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); sharing_expression(base, asked, holes_of, ty_of, walk) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            sharing_expression(base, asked, holes_of, ty_of, walk);
            sharing_expression(index, asked, holes_of, ty_of, walk);
        },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            sharing_expression(value, asked, holes_of, ty_of, walk);
            sharing_expression(fallback, asked, holes_of, ty_of, walk);
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            sharing_expression(expr, asked, holes_of, ty_of, walk);
            sharing_block(handler, asked, holes_of, ty_of, walk);
        },
        Expr::Tuple(parts) => { for part in parts.iter() { sharing_expression(part, asked, holes_of, ty_of, walk); } },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            sharing_expression(start, asked, holes_of, ty_of, walk);
            sharing_expression(end, asked, holes_of, ty_of, walk);
        },
        Expr::ListLit { items, .. } => { for item in items.iter() { sharing_expression(item, asked, holes_of, ty_of, walk); } },
        _ => { },
    }
}

fn a_kept_lambda_uses(lambda: &Expr, asked: &Asked<'_>, walk: &mut SharingWalk) {
    for named in names_used_by(lambda, asked) {
        if a_handle_by_value(&named, &walk) { walk.slots.duplicates(&walk.function, &named, String::from("used by a kept lambda, which takes a handle of its own")); }
        a_crossing_reaches(&named, "a kept lambda uses it, and a kept function may be called on any thread", None, asked, walk);
    }
}

fn names_used_by(expr: &Expr, asked: &Asked<'_>) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    names_in(expr, asked.names, &mut out);
    out
}

fn a_handle_by_value(named: &str, walk: &SharingWalk) -> bool {
    let ty = match *nikaia_std::index::get(&walk.scope, named) { Some(__nikaia_value) => __nikaia_value, None => return false };
    by_value_shared(ty)
}

fn struct_field(owner: &str, field: &FieldInit, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    let field_name = asked.names.resolve(field.name).to_owned();
    let value = nikaia_std::index::or(match field.value.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || Expr::Variable(field.name));
    let key = format!("{}.{}", owner, field_name);
    let handle = named_handle(&value, asked.names, &walk.scope);
    if handle.is_some() {
        let named = nikaia_std::index::or(handle, || "".into());
        let ty = match match *nikaia_std::index::get(&walk.scope, &named) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return };
        walk.slots.note(FIELDS, &key, ty, true, false);
        walk.slots.join(&slot(&walk.function, &named), &slot(FIELDS, &key));
    } else {
        let declared = declared_field_type(owner, &field_name, asked);
        if declared.is_some() && holds_shared(nikaia_std::index::or(declared.as_ref(), || &Ty::Unknown)) {
            walk.slots.note(FIELDS, &key, nikaia_std::index::or(declared, || Ty::Unknown), true, false);
            let source = slot_of(&value, asked, walk);
            if source.is_none() { origin_unseen(FIELDS, &key, &value, asked, walk); } else { walk.slots.join(nikaia_std::index::or(source.as_deref(), || ""), &slot(FIELDS, &key)); }
        }
    }
    sharing_expression(&value, asked, holes_of, ty_of, walk);
}

fn sharing_method(call: &Expr, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    let (receiver, method, args, config) = match call {
        Expr::MethodCall { receiver, method, args, config } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; (receiver, asked.names.resolve(method).to_owned(), args, config) },
        Expr::SafeMethod { receiver, method, args, config } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; (receiver, asked.names.resolve(method).to_owned(), args, config) },
        _ => return,
    };
    if method == "get" && args.is_empty() { a_copy_out_of_the_lock(receiver, asked, walk); }
    if a_parallel_method(&method) || method == "spawn" || walks_in_parallel(receiver, asked.names, &walk.parallel) {
        let why = format!("a lambda handed to `{}` uses it, and that lambda runs on a thread the program asked for", method);
        for arg in args.iter() { for named in names_used_by(arg, asked) { a_crossing_reaches(&named, &why, None, asked, walk); } }
    }
    sharing_arguments(&SharingCall { callee: Some(method), is_method: true }, args, config, asked, holes_of, ty_of, walk);
    sharing_expression(receiver, asked, holes_of, ty_of, walk);
}

fn a_copy_out_of_the_lock(receiver: &Expr, asked: &Asked<'_>, walk: &mut SharingWalk) {
    let handle = match named_handle(receiver, asked.names, &walk.scope) { Some(__nikaia_value) => __nikaia_value, None => return };
    let ty = match *nikaia_std::index::get(&walk.scope, &handle) { Some(__nikaia_value) => __nikaia_value, None => return };
    let held = match held_that_does_not_copy(ty) { Some(__nikaia_value) => __nikaia_value, None => return };
    walk.slots.copies.push((slot(&walk.function, &handle), format!("`{}.get()` copies the whole `{}` out of the lock", handle, held)));
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct SharingCall {
    callee: Option<String>,
    is_method: bool,
}

fn sharing_arguments(called: &SharingCall, args: &[Expr], config: &[ConfigArg], asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    let described = parameters_of((called.callee).as_deref(), asked);
    for at in 0..args.len() as i64 {
        let arg = nikaia_std::index::get(&args, nikaia_std::index::at(at));
        let handle = named_handle(&arg, asked.names, &walk.scope);
        if handle.is_none() {
            an_argument_that_is_not_a_handle(called, (described).as_ref(), at, &arg, asked, walk);
            a_lambda_handed_on((described).as_ref(), at, &arg, asked, holes_of, ty_of, walk);
            continue;
        }
        a_handle_handed_on(called, (described).as_ref(), at, nikaia_std::index::or(handle.as_deref(), || ""), walk);
    }
    for setting in config.iter() {
        let why = format!("it is handed to `{}` as the option `{}`, and no contract says what happens to a `Shared` in an option", nikaia_std::index::or(match called.callee.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || "the callee".into()), asked.names.resolve(setting.name));
        for named in names_used_by(&setting.value, asked) { a_crossing_reaches(&named, &why, Some(Fallback::UncoveredArgument), asked, walk); }
        sharing_expression(&setting.value, asked, holes_of, ty_of, walk);
    }
}

fn a_lambda_handed_on(described: Option<&Described>, at: i64, arg: &Expr, asked: &Asked<'_>, holes_of: &impl Fn(&Expr) -> Vec<Expr>, ty_of: &impl Fn(&Type) -> Ty, walk: &mut SharingWalk) {
    match arg {
        Expr::Closure { body, .. } => {
            if described.is_some() && a_kept_position(match described { Some(__nikaia_value) => __nikaia_value, None => return }, at) { a_kept_lambda_uses(arg, asked, walk); }
            sharing_block(body, asked, holes_of, ty_of, walk);
        },
        _ => sharing_expression(arg, asked, holes_of, ty_of, walk),
    }
}

fn a_kept_position(known: &Described, at: i64) -> bool { at < known.params.len() as i64 && known.keeps.contains(&nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).0) }

fn an_argument_that_is_not_a_handle(called: &SharingCall, described: Option<&Described>, at: i64, arg: &Expr, asked: &Asked<'_>, walk: &mut SharingWalk) {
    if described.is_none() {
        let why = unseen((called.callee).as_deref());
        for named in names_used_by(arg, asked) { a_crossing_reaches(&named, &why, Some(unseen_kind(called)), asked, walk); }
        return;
    }
    let known = match described { Some(__nikaia_value) => __nikaia_value, None => return };
    if at >= known.params.len() as i64 { return; }
    let param = nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).0.to_owned();
    if !by_value_shared(&nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).1) { return; }
    let source = match slot_of(arg, asked, walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    let (owner, named) = split_slot(&source);
    walk.slots.duplicates(&owner, &named, handed_on_to(&known.key, &param));
    walk.slots.join(&source, &slot(&known.key, &param));
}

fn a_handle_handed_on(called: &SharingCall, described: Option<&Described>, at: i64, handle: &str, walk: &mut SharingWalk) {
    let function = walk.function.to_owned();
    if described.is_none() {
        walk.slots.force(&function, handle, unseen((called.callee).as_deref()), Some(unseen_kind(called)));
        return;
    }
    let known = match described { Some(__nikaia_value) => __nikaia_value, None => return };
    if at >= known.params.len() as i64 {
        let callee = nikaia_std::index::or(match called.callee.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || "the callee".into());
        walk.slots.force(&function, handle, format!("`{}` takes it in a position no contract describes", callee), Some(Fallback::UncoveredArgument));
        return;
    }
    let param = nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).0.to_owned();
    if by_value_shared(&nikaia_std::index::get(&known.params, nikaia_std::index::at(at)).1) { walk.slots.duplicates(&function, handle, handed_on_to(&known.key, &param)); }
    walk.slots.join(&slot(&function, handle), &slot(&known.key, &param));
}

fn unseen_kind(called: &SharingCall) -> Fallback {
    if called.is_method { return Fallback::UnseenMethod; }
    Fallback::UnseenCall
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Described {
    key: String,
    params: Vec<(String, Ty)>,
    keeps: Vec<String>,
}

fn parameters_of(callee: Option<&str>, asked: &Asked<'_>) -> Option<Described> {
    let named = match callee { Some(__nikaia_value) => __nikaia_value, None => return None };
    let in_own = described_key(named, asked.own);
    if in_own.is_some() { return described_by(nikaia_std::index::or(in_own.as_deref(), || ""), asked.own); }
    let in_library = match described_key(named, asked.library) { Some(__nikaia_value) => __nikaia_value, None => return None };
    described_by(&in_library, asked.library)
}

fn described_key(callee: &str, ledger: &Ledger) -> Option<String> {
    if ledger.functions.contains_key(callee) { return Some(callee.to_owned()); }
    let suffix = format!("::{}", callee);
    for (one, _) in ledger.functions.iter() { if one.ends_with(&suffix) { return Some(one.to_owned()); } }
    None
}

fn described_by(key: &str, ledger: &Ledger) -> Option<Described> {
    let contract = match *nikaia_std::index::get(&ledger.functions, key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
    let mut params: Vec<(String, Ty)> = vec![];
    let mut first = true;
    for (name, ty) in signature.params.iter() {
        if !(first && name == "self") { params.push((name.to_owned(), ty.clone())); }
        first = false;
    }
    Some(Described { key: key.to_owned(), params, keeps: contract.keeps.to_owned() })
}


// --- signature.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Translated {
    pub ty: Ty,
    pub kept: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Resulted {
    pub ty: Ty,
    pub fails: Option<String>,
}

pub fn translate(written: &str, crate_word: &str, parameters: &[String], types: &collections::BTreeSet<String>, mentioned: &mut collections::BTreeSet<String>) -> Translated {
    let text = written.trim();
    if text.starts_with("&mut ") { return Translated { ty: Ty::Unknown, kept: false }; }
    if text.starts_with("&") {
        let c: Vec<scalar> = nikaia_std::list::chars(text.chars());
        let rest = slice(&c, 1, c.len() as i64);
        let inner = translate(&rest, crate_word, parameters, types, mentioned);
        return Translated { ty: view_of(inner.ty), kept: false };
    }
    let optional = generic_of(text, "Option");
    if optional.is_some() {
        let inner = translate(nikaia_std::index::or(optional.as_deref(), || ""), crate_word, parameters, types, mentioned);
        return Translated { ty: Ty::Nullable(Box::new(inner.ty)), kept: inner.kept };
    }
    let listed = generic_of(text, "Vec");
    if listed.is_some() {
        let inner = translate(nikaia_std::index::or(listed.as_deref(), || ""), crate_word, parameters, types, mentioned);
        return Translated { ty: Ty::Named { name: String::from("Vec"), args: vec![inner.ty], view: false }, kept: true };
    }
    for parameter in parameters.iter() { if text == parameter { return Translated { ty: Ty::Var { name: text.to_owned(), view: false }, kept: true }; } }
    if is_plain(text) { return Translated { ty: Ty::Named { name: text.to_owned(), args: vec![], view: false }, kept: false }; }
    if text == "String" { return Translated { ty: Ty::Named { name: String::from("String"), args: vec![], view: false }, kept: true }; }
    if types.contains(text) {
        mentioned.insert(text.to_owned());
        return Translated { ty: Ty::Named { name: format!("{}::{}", crate_word, text), args: vec![], view: false }, kept: true };
    }
    Translated { ty: Ty::Unknown, kept: true }
}

pub fn result_of(written: &str, crate_word: &str, parameters: &[String], types: &collections::BTreeSet<String>, mentioned: &mut collections::BTreeSet<String>) -> Resulted {
    let resulted = generic_of(written, "Result");
    if resulted.is_none() {
        let plain = translate(written, crate_word, parameters, types, mentioned);
        return Resulted { ty: plain.ty, fails: None };
    }
    let parts = split_top_level(nikaia_std::index::or(resulted.as_deref(), || ""));
    let mut ok: String = String::from("");
    if !parts.is_empty() { ok = (*nikaia_std::index::get(&parts, 0)).to_owned(); }
    let fine = translate(&ok, crate_word, parameters, types, mentioned);
    let mut fails: String = String::from("?");
    if parts.len() > 1 {
        let error = (*nikaia_std::index::get(&parts, 1)).trim();
        if types.contains(error) { fails = format!("{}::{}", crate_word, error); }
    }
    Resulted { ty: fine.ty, fails: Some(fails) }
}

pub fn view_of(ty: Ty) -> Ty {
    match ty {
        Ty::Named { name, args, .. } => Ty::Named { name, args, view: true },
        Ty::Var { name, .. } => Ty::Var { name, view: true },
        _ => ty,
    }
}

pub fn sent_across(names: &[String], types: &[String], bounds: &str) -> Vec<String> {
    let sent = sends(bounds);
    let mut out: Vec<String> = vec![];
    for at in 0..names.len() as i64 {
        let ty = (*nikaia_std::index::get(&types, (at) as usize)).trim();
        let named = unreferenced(ty);
        let mut reached = bounds_send(ty);
        for one in sent.iter() { if *one == named { reached = true; } }
        if reached { out.push((*nikaia_std::index::get(&names, (at) as usize)).to_owned()); }
    }
    out
}

pub fn sends(bounds: &str) -> Vec<String> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let mut out: Vec<String> = vec![];
    for one in split_top_level(bounds) {
        let c: Vec<scalar> = nikaia_std::list::chars(one.chars());
        let colon = find(&c, 0, ':');
        if colon < 0 { continue; }
        let head = __keep_frame.put(slice(&c, 0, colon));
        let name = head.trim();
        let bound = slice(&c, colon + 1, c.len() as i64);
        if bounds_send(&bound) && !name.is_empty() && !name.starts_with("'") && !out.contains(&name.to_owned()) { out.push(name.to_owned()); }
    }
    out.sort();
    out
}

fn unreferenced(ty: &str) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(ty.chars());
    let mut from: i64 = 0;
    while from < c.len() as i64 && (*nikaia_std::index::get(&c, nikaia_std::index::at(from)) == '&' || *nikaia_std::index::get(&c, nikaia_std::index::at(from)) == ' ') { from += 1; }
    let rest = slice(&c, from, c.len() as i64);
    let trimmed = rest.trim();
    if trimmed.starts_with("mut ") {
        let t: Vec<scalar> = nikaia_std::list::chars(trimmed.chars());
        let after = slice(&t, 4, t.len() as i64);
        return after.to_owned();
    }
    trimmed.to_owned()
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WrittenFn {
    pub names: Vec<String>,
    pub types: Vec<String>,
    pub result: String,
    pub pauses: bool,
    pub parameters: Vec<String>,
}

pub fn contract(written: &WrittenFn, crate_word: &str, types: &collections::BTreeSet<String>, mentioned: &mut collections::BTreeSet<String>) -> FnContract {
    let mut keeps: Vec<String> = vec![];
    let mut params: Vec<(String, Ty)> = vec![];
    for at in 0..written.names.len() as i64 {
        let translated = translate(nikaia_std::index::get(&written.types, (at) as usize), crate_word, &written.parameters, types, mentioned);
        if translated.kept { keeps.push((*nikaia_std::index::get(&written.names, (at) as usize)).to_owned()); }
        params.push(((*nikaia_std::index::get(&written.names, (at) as usize)).to_owned(), translated.ty));
    }
    let mut fails: Vec<String> = vec![];
    let mut answer: Option<Ty> = None;
    if !written.result.is_empty() {
        let resulted = result_of(&written.result, crate_word, &written.parameters, types, mentioned);
        if resulted.fails.is_some() { fails.push(nikaia_std::index::or(resulted.fails, || "?".into())); }
        answer = Some(resulted.ty);
    }
    let mut signature = Signature::empty();
    signature.params = params;
    signature.result = answer;
    let mut entry = FnContract::empty();
    entry.public = true;
    entry.sync_claim = if written.pauses { Sync::No } else { Sync::Asserted };
    entry.fails_with = fails;
    entry.keeps = keeps;
    entry.signature = Some(signature);
    entry
}


