pub const RESULT_POSITION: &str = "<result>";

pub const INPUT_POSITION: &str = "input";

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Buffer {
    None,
    Named(String),
    Unknown,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PackageTypes {
    pub borrowing: collections::BTreeSet<String>,
    pub named: collections::BTreeSet<String>,
}

impl PackageTypes {
    pub fn empty() -> PackageTypes { PackageTypes { borrowing: collections::BTreeSet::new(), named: collections::BTreeSet::new() } }
}

pub fn declare_unit(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], package: &mut PackageTypes) {
    for name in borrowing_types(names, items) { package.borrowing.insert(name.to_owned()); }
    for item in items.iter() {
        match &item.node {
            Item::Struct { name, .. } => {
                let name = *name;
                package.named.insert(names.resolve(name).to_owned());
            },
            Item::Enum { name, .. } => {
                let name = *name;
                package.named.insert(names.resolve(name).to_owned());
            },
            _ => { },
        }
    }
}

pub fn a_parse_that_views(names: &winnow_grammar::InternerContext, result: Option<&Type>, package: &PackageTypes) -> bool {
    let ty = match result { Some(__nikaia_value) => __nikaia_value, None => return false };
    let name = names.resolve(ty.name);
    if ty.is_view || package.borrowing.contains(name) { return true; }
    for argument in ty.generics.iter() {
        let inner: Option<Type> = Some(argument.clone());
        if a_parse_that_views(names, (inner).as_ref(), package) { return true; }
    }
    !package.named.contains(name) && !a_type_with_no_room_for_a_view(name)
}

const ROOMLESS: [&str; 28] = ["i8", "i16", "i32", "i64", "i128", "isize", "u8", "u16", "u32", "u64", "u128", "usize", "f32", "f64", "bool", "char", "scalar", "String", "Duration", "Instant", "Vec", "List", "Array", "Option", "Map", "Set", "Shared", "SharedMut"];

fn a_type_with_no_room_for_a_view(name: &str) -> bool {
    let base = base_name(name);
    if base == "Locked" { return true; }
    for one in ROOMLESS.iter() {
        let one = *one;
        if one == base { return true; }
    }
    false
}

pub fn function_views(item: &Item, target: Option<&str>, names: &winnow_grammar::InternerContext, borrowing: &collections::BTreeSet<String>) -> Vec<Held> {
    let mut held: Vec<Held> = vec![];
    match item {
        Item::Fn { receiver, args, ret_type, .. } => {
            if receiver.is_some() && a_borrowing_target(target, borrowing) { held.push(Held { position: String::from("self"), state: State::Borrowed }); }
            for arg in args.iter() { if carries_a_view(names, &arg.ty, borrowing) { held.push(Held { position: names.resolve(arg.name).to_owned(), state: State::Borrowed }); } }
            if result_carries(names, (ret_type).as_ref(), borrowing) { held.push(Held { position: RESULT_POSITION.to_owned(), state: State::Borrowed }); }
        },
        _ => { },
    }
    held
}

fn a_borrowing_target(target: Option<&str>, borrowing: &collections::BTreeSet<String>) -> bool {
    let named = match target { Some(__nikaia_value) => __nikaia_value, None => return false };
    borrowing.contains(named)
}

fn result_carries(names: &winnow_grammar::InternerContext, result: Option<&Type>, borrowing: &collections::BTreeSet<String>) -> bool { carries_a_view(names, match result { Some(__nikaia_value) => __nikaia_value, None => return false }, borrowing) }

pub fn carries_a_view(names: &winnow_grammar::InternerContext, ty: &Type, borrowing: &collections::BTreeSet<String>) -> bool {
    if holds_view(ty) || borrowing.contains(names.resolve(ty.name)) { return true; }
    for argument in ty.generics.iter() { if carries_a_view(names, argument, borrowing) { return true; } }
    false
}

pub fn declares_text(names: &winnow_grammar::InternerContext, ty: Option<&Type>) -> bool {
    let written = match ty { Some(__nikaia_value) => __nikaia_value, None => return false };
    names.resolve(written.name) == "String" && written.generics.is_empty() && !written.is_view && !written.is_nullable
}

pub fn makes_a_buffer(expr: &Expr, asked: &Asked<'_>, unaliased: &impl Fn(&str) -> String) -> Buffer {
    match expr {
        Expr::MethodCall { method, receiver, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; a_method_buffer(asked.names.resolve(method), receiver) },
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); a_call_buffer(func, asked, unaliased) },
        Expr::TryCatch { expr, .. } => { let expr = nikaia_std::boxed::open(expr); makes_a_buffer(expr, asked, unaliased) },
        _ => Buffer::None,
    }
}

fn a_method_buffer(method: &str, receiver: &Expr) -> Buffer {
    if method == "to_owned" { return Buffer::Named(String::from("String")); }
    if method == "to_string" {
        return match receiver {
            Expr::LitStr { .. } => Buffer::None,
            Expr::LitInterpolated { .. } => Buffer::Named(String::from("String")),
            Expr::LitInt { .. } => Buffer::Named(String::from("String")),
            Expr::LitFloat(_) => Buffer::Named(String::from("String")),
            _ => Buffer::Unknown,
        };
    }
    if method == "clone" {
        return match receiver {
            Expr::LitStr { .. } => Buffer::Named(String::from("String")),
            Expr::LitInterpolated { .. } => Buffer::Named(String::from("String")),
            _ => Buffer::None,
        };
    }
    Buffer::None
}

fn a_call_buffer(func: &Expr, asked: &Asked<'_>, unaliased: &impl Fn(&str) -> String) -> Buffer {
    let name = match func {
        Expr::Variable(name) => { let name = *name; asked.names.resolve(name).to_owned() },
        Expr::Path(segments) => unaliased(&joined_segments(segments, asked.names)),
        _ => return Buffer::None,
    };
    let constructor = format!("{}::new", name);
    let contract = match an_entry(&name, asked) { Some(__nikaia_value) => __nikaia_value, None => match an_entry(&constructor, asked) { Some(__nikaia_value) => __nikaia_value, None => return Buffer::Unknown } };
    let signature = match contract.signature { Some(__nikaia_value) => __nikaia_value, None => return Buffer::None };
    let result = match signature.result { Some(__nikaia_value) => __nikaia_value, None => return Buffer::None };
    if is_a_buffer(&result) { return Buffer::Named(result.text()); }
    Buffer::None
}

fn an_entry(key: &str, asked: &Asked<'_>) -> Option<FnContract> {
    let mine: Option<FnContract> = match *nikaia_std::index::get(&asked.own.functions, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    nikaia_std::index::or_maybe(mine, || match *nikaia_std::index::get(&asked.library.functions, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    })
}

fn is_a_buffer(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, args, .. } => a_buffer_name(name, args),
        _ => false,
    }
}

fn a_buffer_name(name: &str, args: &[Ty]) -> bool {
    let base = base_name(name);
    if base == "String" || base == "Bytes" || base == "Mapped" { return true; }
    if (base == "Vec" || base == "List") && !args.is_empty() { return names_u8(nikaia_std::index::get(&args, 0)); }
    false
}

fn names_u8(ty: &Ty) -> bool {
    match ty {
        Ty::Named { name, .. } => base_name(name) == "u8",
        _ => false,
    }
}

fn keep_words(keep: &KeepAt) -> String {
    match keep {
        KeepAt::Param => String::from("in the caller's keep, because views of it leave this function"),
        KeepAt::Frame => String::from("in a keep of this function until it returns, because something outside the loop or block keeps views of it"),
        KeepAt::Local(_) => String::from("in a keep beside the call, as long as what the call hands back"),
        KeepAt::Task => String::from("in a keep the task carries with it (one count per task, not per view)"),
        KeepAt::Element(_) => String::from("in a keep of its own, held by each view kept of it, because what keeps the views drops entries while the loop goes on"),
    }
}

fn goes_in_the_callers_keep(keep: &KeepAt) -> bool { matches!(keep, KeepAt::Param) }

fn lives_in_a_local_keep(keep: &KeepAt) -> bool { matches!(keep, KeepAt::Local(_)) }

fn an_argument(key: &str) -> String {
    let parts: Vec<&str> = key.split("#").collect::<Vec<_>>();
    if parts.len() < 2 { return format!("what `{}` reads", key); }
    let place = nikaia_std::index::or(text::parse_i64(*nikaia_std::index::get(&parts, 1)), || 0) + 1;
    format!("argument {} made in the call to `{}`", place, *nikaia_std::index::get(&parts, 0))
}

fn buffer_named(plan: &BufferPlan, wanted: i64) -> Option<String> {
    for (source, _) in plan.escapes.iter() {
        match source {
            Source::Buffer { at, name, .. } => {
                let at = *at;
                if at == wanted { return Some(format!("`{}`", name)); }
            },
            _ => { },
        }
    }
    None
}

fn padded(word: &str, width: i64) -> String {
    let mut out = word.to_owned();
    let mut n = nikaia_std::list::chars(word.chars()).len() as i64;
    while n < width {
        out.push(' ');
        n = n + 1;
    }
    out
}

pub fn tethers_report(texts: &[String], ledger: &Ledger, here: &collections::BTreeSet<String>, plans: &[BufferPlan], library: &Ledger) -> String {
    let mut lines: Vec<String> = vec![];
    if !texts.is_empty() {
        lines.push(String::from("text (declared `String`):\n"));
        for line in texts.iter() { lines.push(format!("    {}\n", line)); }
    }
    let copying: Vec<&Ledger> = vec![library];
    for (key, contract) in ledger.functions.iter() {
        if contract.views.is_empty() || !here.contains(key) { continue; }
        lines.push(format!("{}:\n", key));
        let mut lent: Vec<String> = vec![];
        if contract.signature.is_some() {
            let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
            let mut at: i64 = 0;
            for (name, ty) in signature.params.iter() {
                if ty.is_a_view() || lends_in(contract, at, &copying) { lent.push(format!("`{}`", name)); }
                at = at + 1;
            }
        }
        for held in contract.views.iter() {
            let state = held.state.as_str();
            let mut from = String::from("");
            if state == "borrowed" && held.position == "<result>" && !lent.is_empty() { from = format!(" - from the caller's argument for {}", lent.join(", ")); }
            lines.push(format!("    {} `{}`{}\n", padded(&state, 9), held.position, from));
        }
    }
    let mut handed: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for plan in plans.iter() {
        let mut names: Vec<String> = vec![];
        for (at, keep) in plan.puts.iter() {
            let at = nikaia_std::num::value(at);
            if goes_in_the_callers_keep(keep) {
                let found = match buffer_named(plan, at) { Some(__nikaia_value) => __nikaia_value, None => continue };
                names.push(found);
            }
        }
        for (id, keep) in plan.calls.iter() {
            let (_, callee) = id;
            if callee.contains("#") && goes_in_the_callers_keep(keep) { names.push(an_argument(&callee)); }
        }
        handed.insert(plan.key.to_owned(), names);
    }
    for plan in plans.iter() {
        let mut said: Vec<String> = vec![];
        for (at, keep) in plan.puts.iter() {
            let at = nikaia_std::num::value(at);
            let name = nikaia_std::index::or(buffer_named(plan, at), || "a buffer".into());
            said.push(format!("    {} lives {}\n", name, keep_words(keep)));
        }
        for (id, keep) in plan.calls.iter() {
            let (_, callee) = id;
            if callee.contains("#") {
                said.push(format!("    {} lives {}\n", an_argument(&callee), keep_words(keep)));
                continue;
            }
            let mut names: Vec<String> = vec![];
            let found = handed.get(callee);
            if found.is_some() {
                let list = match found { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
                for one in list.iter() { names.push(one.to_owned()); }
            }
            if lives_in_a_local_keep(keep) && !names.is_empty() { said.push(format!("    {} lives in `{}`'s keep: handed back by `{}`\n", names.join(", "), plan.key, callee)); } else { said.push(format!("    what `{}` reads lives {}\n", callee, keep_words(keep))); }
        }
        for keeper in plan.element_keepers.iter() {
            if plan.struct_keepers.contains(keeper) {
                let width = nikaia_std::index::or(plan.widths.get(keeper), || 1);
                let mut handles = String::from("a handle on the buffer it points into");
                if width != 1 { handles = format!("a handle on each of the {} buffers it points into", width); }
                said.push(format!("    `{}` holds each struct with {}\n", keeper, handles));
            } else { said.push(format!("    `{}` holds each view with its own handle\n", keeper)); }
        }
        if said.is_empty() { continue; }
        lines.push(format!("{} (keeps):\n", plan.key));
        for line in said.iter() { lines.push(line.to_owned()); }
    }
    if lines.is_empty() { return String::from("no view in a signature here, so there is no state to solve.\n"); }
    lines.join("")
}


// --- text_tiers.nika ---

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Kinds {
    pub owned: bool,
    pub view: bool,
    pub lasting: bool,
    pub either: bool,
}

fn no_kinds() -> Kinds { Kinds { owned: false, view: false, lasting: false, either: false } }

fn owned_kinds() -> Kinds { Kinds { owned: true, view: false, lasting: false, either: false } }

fn view_kinds() -> Kinds { Kinds { owned: false, view: true, lasting: false, either: false } }

fn lasting_kinds() -> Kinds { Kinds { owned: false, view: false, lasting: true, either: false } }

fn either_kinds() -> Kinds { Kinds { owned: false, view: false, lasting: false, either: true } }

fn kinds_joined(a: &Kinds, b: &Kinds) -> Kinds { Kinds { owned: a.owned || b.owned, view: a.view || b.view, lasting: a.lasting || b.lasting, either: a.either || b.either } }

fn same_kinds(a: &Kinds, b: &Kinds) -> bool { a.owned == b.owned && a.view == b.view && a.lasting == b.lasting && a.either == b.either }

fn no_text(kinds: &Kinds) -> bool { !kinds.owned && !kinds.view && !kinds.lasting && !kinds.either }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Tier {
    Owned,
    View,
    Mixed,
}

fn tier_of_kinds(kinds: &Kinds) -> Tier {
    if kinds.either || kinds.view && kinds.owned { return Tier::Mixed; }
    if kinds.view { return Tier::View; }
    Tier::Owned
}

fn mixed(tier: &Tier) -> bool { matches!(tier, Tier::Mixed) }

fn owned_tier(tier: &Tier) -> bool { matches!(tier, Tier::Owned) }

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TextOwner {
    Field(String, String),
    Returned(String),
    Param(String, i64),
    Let(i64),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TextPosition {
    pub owner: TextOwner,
    pub path: Vec<i64>,
}

fn owner_word(owner: &TextOwner) -> String {
    match owner {
        TextOwner::Field(of, field) => format!("field {} {}", of, field),
        TextOwner::Returned(key) => format!("result {}", key),
        TextOwner::Param(key, at) => { let at = *at; format!("param {} {}", key, at) },
        TextOwner::Let(at) => { let at = *at; format!("let {}", at) },
    }
}

fn position_word(owner: &TextOwner, path: &[i64]) -> String {
    let mut word = owner_word(owner);
    word.push_str(" @");
    for step in path.iter() {
        let step = nikaia_std::num::value(step);
        word.push_str(&format!(" {}", step));
    }
    word
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Hand {
    Either,
    Maybe,
    Items,
    Keys,
    Values,
    Pairs,
}

pub fn hand_number(hand: &Hand) -> i64 {
    match hand {
        Hand::Either => 0,
        Hand::Maybe => 1,
        Hand::Items => 2,
        Hand::Keys => 3,
        Hand::Values => 4,
        Hand::Pairs => 5,
    }
}

#[derive(Debug, Clone)]
pub struct TierAsk<'a> {
    pub names: &'a winnow_grammar::InternerContext,
    pub aliases: &'a collections::BTreeMap<String, String>,
    pub library: &'a Ledger,
}

#[derive(Debug, Clone, PartialEq)]
pub struct HoleWrap {
    pub value: Expr,
    pub hand: Hand,
}

#[derive(Debug, Clone, PartialEq)]
pub struct TextTiers {
    pub tiers: Vec<(TextPosition, Tier)>,
    pub lets: collections::BTreeSet<i64>,
    pub text: Option<Type>,
    pub wraps: collections::BTreeMap<i64, Hand>,
    pub hole_wraps: collections::BTreeMap<i64, Vec<HoleWrap>>,
}

pub fn unaliased_in(aliases: &collections::BTreeMap<String, String>, name: &str) -> String {
    if aliases.is_empty() { return name.to_owned(); }
    let mut amp: String = String::from("");
    let mut bare = name.to_owned();
    if name.starts_with("&") {
        amp = String::from("&");
        let chars: Vec<scalar> = nikaia_std::list::chars(name.chars());
        bare = String::from("");
        for k in 1..chars.len() as i64 { bare.push(*nikaia_std::index::get(&chars, (k) as usize)); }
    }
    let parts: Vec<&str> = bare.splitn(2, "::").collect::<Vec<_>>();
    if parts.len() < 2 { return name.to_owned(); }
    let package = match *nikaia_std::index::get(&aliases, *nikaia_std::index::get(&parts, 0)) { Some(__nikaia_value) => __nikaia_value, None => return name.to_owned() };
    format!("{}{}::{}", amp, package, *nikaia_std::index::get(&parts, 1))
}

#[derive(Debug, Clone, PartialEq)]
struct FieldDecl {
    ty: Type,
    published: bool,
}

#[derive(Debug, Clone, PartialEq)]
struct FnDecl {
    params: Vec<Type>,
    result: Option<Type>,
    published: bool,
}

#[derive(Debug, Clone, PartialEq)]
struct TextDeclared {
    fields: collections::BTreeMap<(String, String), FieldDecl>,
    fns: collections::BTreeMap<String, FnDecl>,
    methods: collections::BTreeMap<String, Vec<String>>,
}

fn declared_of(program: &Program, names: &winnow_grammar::InternerContext) -> TextDeclared {
    let mut declared = TextDeclared { fields: collections::BTreeMap::new(), fns: collections::BTreeMap::new(), methods: collections::BTreeMap::new() };
    for item in program.items.iter() {
        match &item.node {
            Item::Struct { name, fields, is_public, .. } => {
                let is_public = *is_public; let name = *name;
                let owner = names.resolve(name).to_owned();
                for field in fields.iter() {
                    let key = (owner.to_owned(), names.resolve(field.name).to_owned());
                    declared.fields.insert(key, FieldDecl { ty: field.ty.clone(), published: is_public && field.is_public });
                }
            },
            Item::Fn { .. } => declare_function(&item.node, None, names, &mut declared),
            Item::Impl { target, methods, .. } => {
                let owner = names.resolve(target.name).to_owned();
                for method in methods.iter() { declare_function(&method.node, Some(owner.to_owned()), names, &mut declared); }
            },
            _ => { },
        }
    }
    declared
}

fn declare_function(item: &Item, target: Option<String>, names: &winnow_grammar::InternerContext, declared: &mut TextDeclared) {
    let (name, args, ret_type, is_public) = match item {
        Item::Fn { name, args, ret_type, is_public, .. } => { let is_public = *is_public; let name = *name; (name, args, ret_type, is_public) },
        _ => return,
    };
    let own = own_name((name).as_ref(), names);
    let key = tier_key((target).as_deref(), &own);
    if target.is_some() {
        let mut keys: Vec<String> = nikaia_std::index::or(match *nikaia_std::index::get(&declared.methods, &own) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        keys.push(key.to_owned());
        declared.methods.insert(own.to_owned(), keys);
    }
    let mut params: Vec<Type> = vec![];
    for arg in args.iter() { params.push(arg.ty.clone()); }
    declared.fns.insert(key, FnDecl { params, result: match ret_type {
        Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
        None => None,
    }, published: is_public });
}

fn own_name(name: Option<&winnow_grammar::Symbol>, names: &winnow_grammar::InternerContext) -> String {
    let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => return String::from("new") };
    names.resolve(*symbol).to_owned()
}

fn tier_key(target: Option<&str>, own: &str) -> String {
    let owner = match target { Some(__nikaia_value) => __nikaia_value, None => return own.to_owned() };
    format!("{}::{}", owner, own)
}

fn position_published(owner: &TextOwner, declared: &TextDeclared) -> bool {
    match owner {
        TextOwner::Field(of, field) => field_published(of, field, declared),
        TextOwner::Returned(key) => fn_published(key, declared),
        TextOwner::Param(key, _) => fn_published(key, declared),
        TextOwner::Let(_) => false,
    }
}

fn field_published(of: &str, field: &str, declared: &TextDeclared) -> bool {
    let key = (of.to_owned(), field.to_owned());
    let found = match *nikaia_std::index::get(&declared.fields, &key) { Some(__nikaia_value) => __nikaia_value, None => return false };
    found.published
}

fn fn_published(key: &str, declared: &TextDeclared) -> bool {
    let found = match *nikaia_std::index::get(&declared.fns, key) { Some(__nikaia_value) => __nikaia_value, None => return false };
    found.published
}

fn string_type(declared: &TextDeclared, names: &winnow_grammar::InternerContext) -> Option<Type> {
    for (_, field) in declared.fields.iter() { if plain_string(names, &field.ty) { return Some(field.ty.clone()); } }
    for (_, function) in declared.fns.iter() {
        for param in function.params.iter() { if plain_string(names, param) { return Some(param.clone()); } }
        let result = match function.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
        if plain_string(names, result) { return Some(result.clone()); }
    }
    None
}

#[derive(Debug, Clone, PartialEq)]
struct Declaring {
    owner: TextOwner,
    ty: Type,
}

#[derive(Debug, Clone, PartialEq)]
struct TierLocal {
    kinds: Kinds,
    of: Option<String>,
    literal: i64,
    declared: Option<Declaring>,
}

#[derive(Debug, Clone, PartialEq)]
struct Flows {
    positions: collections::BTreeMap<String, Kinds>,
    known: collections::BTreeMap<String, TextPosition>,
    literal_lets: collections::BTreeMap<i64, collections::BTreeSet<String>>,
    wraps: collections::BTreeMap<i64, Hand>,
    param_into: collections::BTreeSet<(String, String)>,
    hole_wraps: collections::BTreeMap<i64, Vec<HoleWrap>>,
    links: collections::BTreeSet<(String, String)>,
    unwrappable: collections::BTreeSet<String>,
}

fn no_flows() -> Flows { Flows { positions: collections::BTreeMap::new(), known: collections::BTreeMap::new(), literal_lets: collections::BTreeMap::new(), wraps: collections::BTreeMap::new(), param_into: collections::BTreeSet::new(), hole_wraps: collections::BTreeMap::new(), links: collections::BTreeSet::new(), unwrappable: collections::BTreeSet::new() } }

#[derive(Debug, Clone, PartialEq)]
struct TierWalk {
    declared: TextDeclared,
    tiers: collections::BTreeMap<String, Tier>,
    flows: Flows,
    locals: collections::BTreeMap<String, Vec<TierLocal>>,
    frames: Vec<Vec<String>>,
    result: Option<String>,
    in_hole: bool,
    hole_text: i64,
}

fn open_tier_scope(walk: &mut TierWalk) { walk.frames.push(vec![]); }

fn close_tier_scope(walk: &mut TierWalk) {
    if walk.frames.is_empty() { return; }
    let names = (*nikaia_std::index::get(&walk.frames, nikaia_std::index::at(walk.frames.len() as i64 - 1))).to_owned();
    for name in names.iter() {
        let mut stack = match match *nikaia_std::index::get(&walk.locals, name) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => continue };
        if !stack.is_empty() { stack.pop(); }
        walk.locals.insert(name.to_owned(), stack);
    }
    walk.frames.pop();
}

fn tier_local(name: &str, walk: &TierWalk) -> Option<TierLocal> {
    let stack = match *nikaia_std::index::get(&walk.locals, name) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if stack.is_empty() { return None; }
    Some((*nikaia_std::index::get(&stack, nikaia_std::index::at(stack.len() as i64 - 1))).clone())
}

fn set_tier_local(name: &str, local: TierLocal, walk: &mut TierWalk) {
    let mut stack = match match *nikaia_std::index::get(&walk.locals, name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    if stack.is_empty() { return; }
    stack.pop();
    stack.push(local);
    walk.locals.insert(name.to_owned(), stack);
}

fn bind_tier_local(name: String, local: TierLocal, walk: &mut TierWalk) {
    let mut stack: Vec<TierLocal> = nikaia_std::index::or(match *nikaia_std::index::get(&walk.locals, &name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || vec![].into());
    stack.push(local);
    walk.locals.insert(name.to_owned(), stack);
    if !walk.frames.is_empty() {
        let last = walk.frames.len() as i64 - 1;
        walk.frames[nikaia_std::index::at(last)].push(name);
    }
}

fn plain_local(kinds: Kinds) -> TierLocal { TierLocal { kinds, of: None, literal: -1, declared: None } }

fn tier_at(word: &str, walk: &TierWalk) -> Tier {
    let found = match *nikaia_std::index::get(&walk.tiers, word) { Some(__nikaia_value) => __nikaia_value, None => return Tier::Owned };
    found.clone()
}

fn mixed_at(word: &str, walk: &TierWalk) -> bool { mixed(&tier_at(word, walk)) }

fn seen(owner: &TextOwner, path: &[i64], walk: &mut TierWalk) -> String {
    let word = position_word(owner, path);
    if !walk.flows.known.contains_key(&word) { walk.flows.known.insert(word.to_owned(), TextPosition { owner: owner.clone(), path: path.to_owned() }); }
    word
}

fn a_map(names: &winnow_grammar::InternerContext, ty: &Type) -> bool {
    let name = match container_of(names, ty) { Some(__nikaia_value) => __nikaia_value, None => return false };
    is_a_map_name(&name)
}

fn a_container(names: &winnow_grammar::InternerContext, ty: &Type) -> bool { container_of(names, ty).is_some() }

fn flow_type(owner: &TextOwner, ty: &Type, path: &mut Vec<i64>, kinds: &Kinds, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    if plain_string(ask.names, ty) {
        let word = seen(owner, &path, walk);
        let before = nikaia_std::index::or(match *nikaia_std::index::get(&walk.flows.positions, &word) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || no_kinds().into());
        walk.flows.positions.insert(word, kinds_joined(&before, kinds));
        return;
    }
    if a_container(ask.names, ty) {
        let mut at = 0;
        for arg in ty.generics.iter() {
            path.push(at);
            flow_type(owner, arg, path, kinds, ask, walk);
            path.pop();
            at += 1;
        }
    }
}

fn flow_value(going: &TierGoing, value: Option<&Expr>, kinds: &Kinds, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    let owner = going.owner.clone();
    let ty = going.ty.clone();
    let path = going.path.to_owned();
    let plain = plain_string(ask.names, &ty);
    if plain {
        let from = handed_parameter(value, ask, &walk);
        if from.is_some() {
            let from_word: String = nikaia_std::index::or(from, || "".into());
            let to = seen(&owner, &path, walk);
            walk.flows.param_into.insert((from_word, to));
        }
    }
    let linked = a_container(ask.names, &ty) && comes_whole(value, ask, &walk);
    if !linked { flow_type(&owner, &ty, &mut path.to_owned(), kinds, ask, walk); }
    if walk.in_hole && walk.hole_text < 0 && going.wrap && plain {
        let word = seen(&owner, &path, walk);
        walk.flows.unwrappable.insert(word);
        return;
    }
    let given = match value { Some(__nikaia_value) => __nikaia_value, None => return };
    if plain && going.wrap && !a_null(given) && mixed_at(&position_word(&owner, &path), &walk) { if ty.is_nullable { hand_value_over(given, Hand::Maybe, node_of, walk); } else { hand_value_over(given, Hand::Either, node_of, walk); } }
    kept_literal(given, &owner, &path, &ty, ask, walk);
    if a_container(ask.names, &ty) { flow_whole(going, given, node_of, ask, walk); }
}

#[derive(Debug, Clone, PartialEq)]
struct TierGoing {
    owner: TextOwner,
    ty: Type,
    path: Vec<i64>,
    wrap: bool,
}

fn going_into(owner: &TextOwner, ty: &Type, path: Vec<i64>, wrap: bool) -> TierGoing { TierGoing { owner: owner.clone(), ty: ty.clone(), path, wrap } }

fn a_null(value: &Expr) -> bool { matches!(value, Expr::LitNull) }

fn handed_parameter(value: Option<&Expr>, ask: &TierAsk<'_>, walk: &TierWalk) -> Option<String> {
    let given = match value { Some(__nikaia_value) => __nikaia_value, None => return None };
    let name = match given {
        Expr::Variable(name) => { let name = *name; ask.names.resolve(name).to_owned() },
        _ => return None,
    };
    let local = match tier_local(&name, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let declared = match local.declared { Some(__nikaia_value) => __nikaia_value, None => return None };
    let parameter = matches!(declared.owner, TextOwner::Param(_, _));
    if !parameter || !plain_string(ask.names, &declared.ty) { return None; }
    let empty: Vec<i64> = vec![];
    Some(position_word(&declared.owner, &empty))
}

fn comes_whole(value: Option<&Expr>, ask: &TierAsk<'_>, walk: &TierWalk) -> bool {
    let given = match value { Some(__nikaia_value) => __nikaia_value, None => return false };
    let collected = match given {
        Expr::MethodCall { method, args, .. } => { let method = *method; args.is_empty() && ask.names.resolve(method) == "collect" },
        Expr::ListLit { .. } => true,
        _ => false,
    };
    !collected && source_of(given, ask, walk).is_some()
}

fn flow_whole(going: &TierGoing, value: &Expr, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    let ty = going.ty.clone();
    let a_list = a_container(ask.names, &ty) && !a_map(ask.names, &ty) && !ty.generics.is_empty();
    match value {
        Expr::ListLit { items, .. } => {
            if !a_list { return; }
            let element = (*nikaia_std::index::get(&ty.generics, 0)).clone();
            for item in items.iter() {
                let kinds = tier_expr(item, node_of, ask, walk);
                let mut at = going.path.to_owned();
                at.push(0);
                flow_value(&going_into(&going.owner, &element, at, true), Some(item), &kinds, node_of, ask, walk);
            }
        },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            if ask.names.resolve(method) == "collect" && args.is_empty() {
                collected_into(going, receiver, node_of, ask, walk);
                return;
            }
            link_from(going, value, ask, walk);
        },
        _ => link_from(going, value, ask, walk),
    }
}

fn link_from(going: &TierGoing, value: &Expr, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    let from = match source_of(value, ask, &walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    let to = Declaring { owner: going.owner.clone(), ty: going.ty.clone() };
    link(&from, &mut vec![], &to, &mut going.path.to_owned(), ask, walk);
}

fn collected_into(going: &TierGoing, receiver: &Expr, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    let ty = going.ty.clone();
    if a_map(ask.names, &ty) {
        let keys = mixed_part(going, 0, ask, walk);
        let values = mixed_part(going, 1, ask, walk);
        if keys && values { hand_value_over(receiver, Hand::Pairs, node_of, walk); } else if keys { hand_value_over(receiver, Hand::Keys, node_of, walk); } else if values { hand_value_over(receiver, Hand::Values, node_of, walk); }
        return;
    }
    if !a_container(ask.names, &ty) || ty.generics.is_empty() { return; }
    if !plain_string(ask.names, nikaia_std::index::get(&ty.generics, 0)) { return; }
    let mut at = going.path.to_owned();
    at.push(0);
    let word = seen(&going.owner, &at, walk);
    if walk.in_hole && walk.hole_text < 0 { walk.flows.unwrappable.insert(word); } else if mixed_at(&word, &walk) { hand_value_over(receiver, Hand::Items, node_of, walk); }
}

fn mixed_part(going: &TierGoing, at: i64, ask: &TierAsk<'_>, walk: &mut TierWalk) -> bool {
    if (going.ty.generics.len() as i64) <= at { return false; }
    if !plain_string(ask.names, nikaia_std::index::get(&going.ty.generics, nikaia_std::index::at(at))) { return false; }
    let mut path = going.path.to_owned();
    path.push(at);
    let word = seen(&going.owner, &path, walk);
    if walk.in_hole && walk.hole_text < 0 {
        walk.flows.unwrappable.insert(word);
        return false;
    }
    mixed_at(&word, &walk)
}

fn source_of(value: &Expr, ask: &TierAsk<'_>, walk: &TierWalk) -> Option<Declaring> {
    match value {
        Expr::Variable(_) => place_of(value, ask, walk),
        Expr::Field { .. } => place_of(value, ask, walk),
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); called_result(func, ask, walk) },
        Expr::MethodCall { method, .. } => { let method = *method; method_result(ask.names.resolve(method), walk) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); source_of(inner, ask, walk) },
        _ => None,
    }
}

fn called_result(func: &Expr, ask: &TierAsk<'_>, walk: &TierWalk) -> Option<Declaring> {
    let callee = match tier_callee(func, ask) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let function = match *nikaia_std::index::get(&walk.declared.fns, &callee) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let result = match function.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(Declaring { owner: TextOwner::Returned(callee.to_owned()), ty: result.clone() })
}

fn method_result(method: &str, walk: &TierWalk) -> Option<Declaring> {
    let keys = match *nikaia_std::index::get(&walk.declared.methods, method) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if keys.len() != 1 { return None; }
    let key = (*nikaia_std::index::get(&keys, 0)).to_owned();
    let function = match *nikaia_std::index::get(&walk.declared.fns, &key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let result = match function.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(Declaring { owner: TextOwner::Returned(key.to_owned()), ty: result.clone() })
}

fn tier_callee(func: &Expr, ask: &TierAsk<'_>) -> Option<String> { written_callee(ask.names, func, &|name| { unaliased_in(ask.aliases, name) }) }

fn link(from: &Declaring, from_path: &mut Vec<i64>, to: &Declaring, to_path: &mut Vec<i64>, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    let from_ty = from.ty.clone();
    let to_ty = to.ty.clone();
    if plain_string(ask.names, &from_ty) && plain_string(ask.names, &to_ty) {
        let a = seen(&from.owner, &from_path, walk);
        let b = seen(&to.owner, &to_path, walk);
        if a != b { walk.flows.links.insert((a, b)); }
        return;
    }
    if !a_container(ask.names, &from_ty) || !a_container(ask.names, &to_ty) || (from_ty.generics.len() as i64) != to_ty.generics.len() as i64 { return; }
    for at in 0..from_ty.generics.len() as i64 {
        from_path.push(at);
        to_path.push(at);
        let inner_from = Declaring { owner: from.owner.clone(), ty: (*nikaia_std::index::get(&from_ty.generics, nikaia_std::index::at(at))).clone() };
        let inner_to = Declaring { owner: to.owner.clone(), ty: (*nikaia_std::index::get(&to_ty.generics, nikaia_std::index::at(at))).clone() };
        link(&inner_from, &mut from_path.to_owned(), &inner_to, &mut to_path.to_owned(), ask, walk);
        from_path.pop();
        to_path.pop();
    }
}

fn hand_value_over(value: &Expr, hand: Hand, node_of: &impl Fn(&Expr) -> i64, walk: &mut TierWalk) {
    if walk.in_hole && walk.hole_text >= 0 {
        let at = walk.hole_text;
        let mut wraps: Vec<HoleWrap> = nikaia_std::index::or(match *nikaia_std::index::get(&walk.flows.hole_wraps, &at) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        wraps.push(HoleWrap { value: value.clone(), hand });
        walk.flows.hole_wraps.insert(at, wraps);
        return;
    }
    walk.flows.wraps.insert(node_of(value), hand);
}

fn kinds_of(owner: &TextOwner, ty: &Type, path: &mut Vec<i64>, ask: &TierAsk<'_>, walk: &TierWalk) -> Kinds {
    if plain_string(ask.names, ty) {
        return match tier_at(&position_word(owner, &path), walk) {
            Tier::Owned => owned_kinds(),
            Tier::View => view_kinds(),
            Tier::Mixed => either_kinds(),
        };
    }
    if ty.is_view && ask.names.resolve(ty.name) == "String" { return view_kinds(); }
    if a_container(ask.names, ty) {
        let mut out = no_kinds();
        let mut at = 0;
        for arg in ty.generics.iter() {
            path.push(at);
            out = kinds_joined(&out, &kinds_of(owner, arg, &mut path.to_owned(), ask, walk));
            path.pop();
            at += 1;
        }
        if !no_text(&out) { return out; }
    }
    owned_kinds()
}

fn kinds_of_declared(declared: &Declaring, ask: &TierAsk<'_>, walk: &TierWalk) -> Kinds { kinds_of(&declared.owner, &declared.ty, &mut vec![], ask, walk) }

fn element_kinds(declared: &Declaring, keys: bool, ask: &TierAsk<'_>, walk: &TierWalk) -> Kinds {
    let ty = declared.ty.clone();
    if !a_container(ask.names, &ty) { return kinds_of_declared(declared, ask, walk); }
    let mut at: i64 = 0;
    if a_map(ask.names, &ty) && !keys { at = 1; }
    if ty.generics.len() <= ((at) as usize) { return owned_kinds(); }
    kinds_of(&declared.owner, nikaia_std::index::get(&ty.generics, (at) as usize), &mut vec![at], ask, walk)
}

fn place_of(expr: &Expr, ask: &TierAsk<'_>, walk: &TierWalk) -> Option<Declaring> {
    match expr {
        Expr::Variable(name) => { let name = *name; declared_local(ask.names.resolve(name), walk) },
        Expr::Field { base, name } => { let base = nikaia_std::boxed::open(base); let name = *name; field_place(base, ask.names.resolve(name), ask, walk) },
        _ => None,
    }
}

fn declared_local(name: &str, walk: &TierWalk) -> Option<Declaring> {
    let local = match tier_local(name, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    match local.declared.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

fn field_place(base: &Expr, field: &str, ask: &TierAsk<'_>, walk: &TierWalk) -> Option<Declaring> {
    let owner = match tier_struct_of(base, ask, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    let key = (owner.to_owned(), field.to_owned());
    let found = match *nikaia_std::index::get(&walk.declared.fields, &key) { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(Declaring { owner: TextOwner::Field(owner.to_owned(), field.to_owned()), ty: found.ty.clone() })
}

fn tier_block(block: &Block, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) -> Kinds {
    open_tier_scope(walk);
    let mut tail = no_kinds();
    let mut k: i64 = 0;
    for stmt in block.stmts.iter() {
        let kinds = tier_statement(&stmt.node, stmt.span.start as i64, node_of, ask, walk);
        if ((k + 1) as usize) == block.stmts.len() { tail = kinds; }
        k += 1;
    }
    close_tier_scope(walk);
    tail
}

fn tier_statement(stmt: &Stmt, at: i64, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) -> Kinds {
    match stmt {
        Stmt::Let { names, value, ty, .. } => tier_let(names, value, (ty).as_ref(), at, node_of, ask, walk),
        Stmt::Assign { target, value, .. } => tier_assign(target, value, node_of, ask, walk),
        Stmt::For { bindings, iter, body } => {
            let kinds = tier_expr(iter, node_of, ask, walk);
            open_tier_scope(walk);
            for binding in bindings.iter() { bind_tier_local(ask.names.resolve(*binding).to_owned(), plain_local(kinds.clone()), walk); }
            tier_block(body, node_of, ask, walk);
            close_tier_scope(walk);
        },
        Stmt::While { cond, body } => {
            tier_expr(cond, node_of, ask, walk);
            tier_block(body, node_of, ask, walk);
        },
        Stmt::Return(value) => {
            let given = match value { Some(__nikaia_value) => __nikaia_value, None => return no_kinds() };
            let kinds = tier_expr(given, node_of, ask, walk);
            flow_result(given, &kinds, node_of, ask, walk);
        },
        Stmt::Expr(expr) => return tier_expr(expr, node_of, ask, walk),
        _ => { },
    }
    no_kinds()
}

fn tier_let(names: &[winnow_grammar::Symbol], value: &Expr, ty: Option<&Type>, at: i64, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    let kinds = tier_expr(value, node_of, ask, walk);
    let mut of = tier_struct_of(value, ask, &walk);
    let mut literal: i64 = -1;
    let mut declared: Option<Declaring> = None;
    let written = ty.is_some();
    if written {
        let declared_ty = match match ty {
            Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return };
        of = Some(ask.names.resolve(declared_ty.name).to_owned());
        declared = Some(Declaring { owner: TextOwner::Let(at), ty: declared_ty });
    } else {
        if a_literal_text(value) { literal = at; }
        let source = source_of(value, ask, &walk);
        if container_source((source).as_ref(), ask) { declared = source; }
    }
    let mut bound = kinds;
    if declared.is_some() {
        let found = match match declared.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return };
        if !written { bound = kinds_of_declared(&found, ask, &walk); } else {
            flow_value(&going_into(&found.owner, &found.ty, vec![], true), Some(value), &kinds, node_of, ask, walk);
            bound = kinds_of_declared(&found, ask, &walk);
        }
    }
    if names.len() == 1 {
        let local = TierLocal { kinds: bound, of, literal, declared };
        bind_tier_local(ask.names.resolve(*nikaia_std::index::get(&names, 0)).to_owned(), local, walk);
    }
}

fn container_source(source: Option<&Declaring>, ask: &TierAsk<'_>) -> bool {
    let found = match source { Some(__nikaia_value) => __nikaia_value, None => return false };
    a_container(ask.names, &found.ty)
}

fn a_literal_text(value: &Expr) -> bool {
    match value {
        Expr::LitStr { .. } => true,
        Expr::Block(block) => a_literal_tail(block),
        Expr::If { then_branch, else_branch, .. } => {
            let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return false };
            a_literal_tail(then_branch) && a_literal_tail(otherwise)
        },
        Expr::Match { arms, .. } => {
            if arms.is_empty() { return false; }
            for arm in arms.iter() { if !a_literal_text(&arm.body) { return false; } }
            true
        },
        _ => false,
    }
}

fn a_literal_tail(block: &Block) -> bool {
    if block.stmts.len() != 1 { return false; }
    match &nikaia_std::index::get(&block.stmts, 0).node {
        Stmt::Expr(last) => a_literal_text(last),
        _ => false,
    }
}

fn tier_assign(target: &Expr, value: &Expr, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    let kinds = tier_expr(value, node_of, ask, walk);
    match target {
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            let key = tier_expr(index, node_of, ask, walk);
            let place = match place_of(base, ask, &walk) { Some(__nikaia_value) => __nikaia_value, None => return };
            let ty = place.ty.clone();
            if !a_container(ask.names, &ty) { return; }
            if a_map(ask.names, &ty) {
                if ty.generics.len() == 2 {
                    flow_value(&going_into(&place.owner, nikaia_std::index::get(&ty.generics, 0), vec![0], true), Some(index), &key, node_of, ask, walk);
                    flow_value(&going_into(&place.owner, nikaia_std::index::get(&ty.generics, 1), vec![1], true), Some(value), &kinds, node_of, ask, walk);
                }
                return;
            }
            if !ty.generics.is_empty() { flow_value(&going_into(&place.owner, nikaia_std::index::get(&ty.generics, 0), vec![0], true), Some(value), &kinds, node_of, ask, walk); }
        },
        _ => {
            let place = place_of(target, ask, &walk);
            if place.is_some() {
                let found = match place { Some(__nikaia_value) => __nikaia_value, None => return };
                flow_value(&going_into(&found.owner, &found.ty, vec![], true), Some(value), &kinds, node_of, ask, walk);
            }
            let name = match target {
                Expr::Variable(name) => { let name = *name; ask.names.resolve(name).to_owned() },
                _ => return,
            };
            let mut local = match tier_local(&name, &walk) { Some(__nikaia_value) => __nikaia_value, None => return };
            if local.declared.is_none() { local.kinds = kinds_joined(&local.kinds, &kinds); }
            local.literal = -1;
            set_tier_local(&name, local, walk);
        },
    }
}

fn flow_result(value: &Expr, kinds: &Kinds, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    let key = match match walk.result.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    let function = match match *nikaia_std::index::get(&walk.declared.fns, &key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    let result = match function.result { Some(__nikaia_value) => __nikaia_value, None => return };
    flow_value(&going_into(&TextOwner::Returned(key.to_owned()), &result, vec![], false), Some(value), kinds, node_of, ask, walk);
}

fn kept_literal(value: &Expr, owner: &TextOwner, path: &[i64], ty: &Type, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    if !plain_string(ask.names, ty) { return; }
    let name = match value {
        Expr::Variable(name) => { let name = *name; ask.names.resolve(name).to_owned() },
        _ => return,
    };
    let local = match tier_local(&name, &walk) { Some(__nikaia_value) => __nikaia_value, None => return };
    if local.literal < 0 { return; }
    let word = seen(owner, path, walk);
    let mut kept: collections::BTreeSet<String> = nikaia_std::index::or(match *nikaia_std::index::get(&walk.flows.literal_lets, &local.literal) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || collections::BTreeSet::new().into());
    kept.insert(word);
    walk.flows.literal_lets.insert(local.literal, kept);
}

fn tier_struct_of(expr: &Expr, ask: &TierAsk<'_>, walk: &TierWalk) -> Option<String> {
    match expr {
        Expr::StructLit { name, .. } => { let name = *name; Some(ask.names.resolve(name).to_owned()) },
        Expr::Variable(name) => { let name = *name; struct_of_local(ask.names.resolve(name), walk) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tier_struct_of(expr, ask, walk) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); tier_struct_of(inner, ask, walk) },
        _ => None,
    }
}

fn struct_of_local(name: &str, walk: &TierWalk) -> Option<String> {
    let local = match tier_local(name, walk) { Some(__nikaia_value) => __nikaia_value, None => return None };
    match local.of.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }
}

fn flow_args(key: &str, args: &[Expr], given: &[Kinds], node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    let function = match match *nikaia_std::index::get(&walk.declared.fns, key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    let mut at: i64 = 0;
    while at < args.len() as i64 && at < given.len() as i64 {
        if at < function.params.len() as i64 {
            let owner = TextOwner::Param(key.to_owned(), at);
            flow_value(&going_into(&owner, nikaia_std::index::get(&function.params, nikaia_std::index::at(at)), vec![], false), Some(nikaia_std::index::get(&args, nikaia_std::index::at(at))), nikaia_std::index::get(&given, nikaia_std::index::at(at)), node_of, ask, walk);
        }
        at += 1;
    }
}

fn tier_expr(expr: &Expr, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) -> Kinds {
    match expr {
        Expr::LitStr { .. } => lasting_kinds(),
        Expr::LitNull => no_kinds(),
        Expr::LitInt { .. } => no_kinds(),
        Expr::LitFloat(_) => no_kinds(),
        Expr::LitBool(_) => no_kinds(),
        Expr::LitInterpolated { parts } => {
            let outer = walk.in_hole;
            walk.in_hole = true;
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, at, .. } => {
                        let at = *at;
                        let held = walk.hole_text;
                        walk.hole_text = at as i64;
                        tier_expr(expr, node_of, ask, walk);
                        walk.hole_text = held;
                    },
                    _ => { },
                }
            }
            walk.in_hole = outer;
            owned_kinds()
        },
        Expr::Variable(name) => { let name = *name; kinds_of_local(ask.names.resolve(name), &walk) },
        Expr::MethodCall { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; method_kinds(receiver, ask.names.resolve(method), args, node_of, ask, walk) },
        Expr::SafeMethod { receiver, method, args, .. } => { let receiver = nikaia_std::boxed::open(receiver); let method = *method; method_kinds(receiver, ask.names.resolve(method), args, node_of, ask, walk) },
        Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); call_kinds(func, args, node_of, ask, walk) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); field_kinds(expr, base, node_of, ask, walk) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); field_kinds(expr, base, node_of, ask, walk) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            let received = tier_expr(base, node_of, ask, walk);
            tier_expr(index, node_of, ask, walk);
            if a_range(index) { return viewed(&received); }
            let place = match place_of(base, ask, &walk) { Some(__nikaia_value) => __nikaia_value, None => return received };
            element_kinds(&place, false, ask, &walk)
        },
        Expr::StructLit { name, fields } => {
            let name = *name;
            let owner = ask.names.resolve(name).to_owned();
            for field in fields.iter() { tier_struct_field(&owner, field, node_of, ask, walk); }
            owned_kinds()
        },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            tier_expr(base, node_of, ask, walk);
            let owner = tier_struct_of(base, ask, &walk);
            for field in fields.iter() {
                let value = match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
                let kinds = tier_expr(value, node_of, ask, walk);
                let of = match match owner.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                } { Some(__nikaia_value) => __nikaia_value, None => continue };
                let key = (of.to_owned(), ask.names.resolve(field.name).to_owned());
                let found = match match *nikaia_std::index::get(&walk.declared.fields, &key) {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                } { Some(__nikaia_value) => __nikaia_value, None => continue };
                let into = TextOwner::Field(of.to_owned(), ask.names.resolve(field.name).to_owned());
                flow_value(&going_into(&into, &found.ty, vec![], false), Some(value), &kinds, node_of, ask, walk);
            }
            owned_kinds()
        },
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            tier_expr(cond, node_of, ask, walk);
            let mut out = tier_block(then_branch, node_of, ask, walk);
            if else_branch.is_some() {
                let otherwise = match else_branch { Some(__nikaia_value) => __nikaia_value, None => return out };
                out = kinds_joined(&out, &tier_block(otherwise, node_of, ask, walk));
            }
            out
        },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            tier_expr(value, node_of, ask, walk);
            let mut out = no_kinds();
            for arm in arms.iter() {
                if arm.guard.is_some() {
                    let guard = match arm.guard.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
                    tier_expr(guard, node_of, ask, walk);
                }
                out = kinds_joined(&out, &tier_expr(&arm.body, node_of, ask, walk));
            }
            out
        },
        Expr::Block(block) => tier_block(block, node_of, ask, walk),
        Expr::Unsafe(block) => tier_block(block, node_of, ask, walk),
        Expr::Overlap(block) => tier_block(block, node_of, ask, walk),
        Expr::Closure { body, .. } => {
            let held = match walk.result.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
            walk.result = None;
            tier_block(body, node_of, ask, walk);
            walk.result = held;
            owned_kinds()
        },
        Expr::Spawn { body, .. } => {
            let body = nikaia_std::boxed::open(body);
            let held = match walk.result.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            };
            walk.result = None;
            tier_expr(body, node_of, ask, walk);
            walk.result = held;
            owned_kinds()
        },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            let out = tier_expr(value, node_of, ask, walk);
            kinds_joined(&out, &tier_expr(fallback, node_of, ask, walk))
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            let out = tier_expr(expr, node_of, ask, walk);
            kinds_joined(&out, &tier_block(handler, node_of, ask, walk))
        },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); tier_expr(inner, node_of, ask, walk) },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tier_expr(expr, node_of, ask, walk) },
        Expr::Throw(inner) => {
            let inner = nikaia_std::boxed::open(inner);
            tier_expr(inner, node_of, ask, walk);
            no_kinds()
        },
        Expr::Return(value) => {
            let value = nikaia_std::boxed::open(value);
            let given = match value { Some(__nikaia_value) => __nikaia_value, None => return no_kinds() };
            let kinds = tier_expr(given, node_of, ask, walk);
            flow_result(given, &kinds, node_of, ask, walk);
            no_kinds()
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            tier_expr(lhs, node_of, ask, walk);
            tier_expr(rhs, node_of, ask, walk);
            owned_kinds()
        },
        Expr::Cast { expr, .. } => {
            let expr = nikaia_std::boxed::open(expr);
            tier_expr(expr, node_of, ask, walk);
            owned_kinds()
        },
        Expr::Tuple(items) => items_kinds(items, node_of, ask, walk),
        Expr::ListLit { items, .. } => items_kinds(items, node_of, ask, walk),
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            tier_expr(start, node_of, ask, walk);
            tier_expr(end, node_of, ask, walk);
            owned_kinds()
        },
        _ => owned_kinds(),
    }
}

fn a_range(index: &Expr) -> bool { matches!(index, Expr::Range { .. }) }

fn kinds_of_local(name: &str, walk: &TierWalk) -> Kinds {
    let local = match tier_local(name, walk) { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    local.kinds.clone()
}

fn items_kinds(items: &[Expr], node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) -> Kinds {
    let mut out = no_kinds();
    for item in items.iter() { out = kinds_joined(&out, &tier_expr(item, node_of, ask, walk)); }
    out
}

fn field_kinds(expr: &Expr, base: &Expr, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) -> Kinds {
    tier_expr(base, node_of, ask, walk);
    let place = match place_of(expr, ask, &walk) { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    kinds_of_declared(&place, ask, &walk)
}

fn tier_struct_field(owner: &str, field: &FieldInit, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    let shorthand = Expr::Variable(field.name);
    let kinds = field_value_kinds(field, &shorthand, node_of, ask, walk);
    let name = ask.names.resolve(field.name).to_owned();
    let key = (owner.to_owned(), name.to_owned());
    let found = match match *nikaia_std::index::get(&walk.declared.fields, &key) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    } { Some(__nikaia_value) => __nikaia_value, None => return };
    let into = TextOwner::Field(owner.to_owned(), name);
    flow_value(&going_into(&into, &found.ty, vec![], false), (field.value).as_ref(), &kinds, node_of, ask, walk);
    if field.value.is_none() { kept_literal(&shorthand, &into, &no_path(), &found.ty, ask, walk); }
}

fn field_value_kinds(field: &FieldInit, shorthand: &Expr, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) -> Kinds {
    if field.value.is_some() {
        let value = match field.value.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return no_kinds() };
        return tier_expr(value, node_of, ask, walk);
    }
    tier_expr(shorthand, node_of, ask, walk)
}

fn call_kinds(func: &Expr, args: &[Expr], node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) -> Kinds {
    let mut given: Vec<Kinds> = vec![];
    for arg in args.iter() { given.push(tier_expr(arg, node_of, ask, walk)); }
    let callee = match tier_callee(func, ask) { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    if walk.declared.fns.contains_key(&callee) {
        flow_args(&callee, args, &given, node_of, ask, walk);
        return result_kinds(&callee, ask, &walk);
    }
    if args.is_empty() && is_a_container_name(&callee) { return no_kinds(); }
    std_result(&callee, ask)
}

fn method_kinds(receiver: &Expr, method: &str, args: &[Expr], node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) -> Kinds {
    let received = tier_expr(receiver, node_of, ask, walk);
    let mut given: Vec<Kinds> = vec![];
    for arg in args.iter() { given.push(tier_expr(arg, node_of, ask, walk)); }
    if walk.declared.methods.contains_key(method) {
        let keys: Vec<String> = nikaia_std::index::or(match *nikaia_std::index::get(&walk.declared.methods, method) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || vec![].into());
        for key in keys.iter() { flow_args(key, args, &given, node_of, ask, walk); }
        let mut out = no_kinds();
        for key in keys.iter() { out = kinds_joined(&out, &result_kinds(key, ask, &walk)); }
        return out;
    }
    let place = place_of(receiver, ask, &walk);
    if place.is_some() {
        let found = match place { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
        let ty = found.ty.clone();
        if puts_its_argument(method) && a_container(ask.names, &ty) {
            put_into_container(&found, method, args, &given, node_of, ask, walk);
            return owned_kinds();
        }
        if hands_back_an_element(method) { return element_kinds(&found, method == "keys", ask, &walk); }
    }
    if method == "map" && args.len() == 1 {
        match nikaia_std::index::get(&args, 0) {
            Expr::Closure { params, body, .. } => return mapped(params, body, &received, node_of, ask, walk),
            _ => { },
        }
    }
    if method == "filter" || method == "rev" || method == "skip" || method == "take" || method == "step_by" { return received; }
    if owns_its_text(method) { return owned_kinds(); }
    if views_what_it_is_called_on(method) { return viewed(&received); }
    if hands_back_an_element(method) { return received; }
    owned_kinds()
}

fn put_into_container(place: &Declaring, method: &str, args: &[Expr], given: &[Kinds], node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    let ty = place.ty.clone();
    if a_map(ask.names, &ty) {
        if args.len() == 2 && given.len() == 2 && ty.generics.len() == 2 {
            flow_value(&going_into(&place.owner, nikaia_std::index::get(&ty.generics, 0), vec![0], true), Some(nikaia_std::index::get(&args, 0)), nikaia_std::index::get(&given, 0), node_of, ask, walk);
            flow_value(&going_into(&place.owner, nikaia_std::index::get(&ty.generics, 1), vec![1], true), Some(nikaia_std::index::get(&args, 1)), nikaia_std::index::get(&given, 1), node_of, ask, walk);
        }
        return;
    }
    if ty.generics.is_empty() || args.is_empty() || given.is_empty() { return; }
    let wrap = method != "extend" && method != "append";
    flow_value(&going_into(&place.owner, nikaia_std::index::get(&ty.generics, 0), vec![0], wrap), Some(nikaia_std::index::get(&args, nikaia_std::index::at(args.len() as i64 - 1))), nikaia_std::index::get(&given, nikaia_std::index::at(given.len() as i64 - 1)), node_of, ask, walk);
}

fn mapped(params: &[winnow_grammar::Symbol], body: &Block, received: &Kinds, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) -> Kinds {
    let held = match walk.result.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    walk.result = None;
    open_tier_scope(walk);
    if params.is_empty() { bind_tier_local(String::from("a"), plain_local(received.clone()), walk); }
    for param in params.iter() { bind_tier_local(ask.names.resolve(*param).to_owned(), plain_local(received.clone()), walk); }
    let made = tier_block(body, node_of, ask, walk);
    close_tier_scope(walk);
    walk.result = held;
    made
}

fn result_kinds(key: &str, ask: &TierAsk<'_>, walk: &TierWalk) -> Kinds {
    let function = match *nikaia_std::index::get(&walk.declared.fns, key) { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    let result = match function.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    kinds_of(&TextOwner::Returned(key.to_owned()), result, &mut vec![], ask, walk)
}

fn viewed(received: &Kinds) -> Kinds {
    if received.lasting && !received.owned && !received.view && !received.either { return lasting_kinds(); }
    view_kinds()
}

fn std_result(callee: &str, ask: &TierAsk<'_>) -> Kinds {
    let contract = match *nikaia_std::index::get(&ask.library.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    let signature = match contract.signature.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    let result = match signature.result.as_ref() { Some(__nikaia_value) => __nikaia_value, None => return owned_kinds() };
    if result.text() == "ref String" { return view_kinds(); }
    owned_kinds()
}

fn walk_program(program: &Program, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { .. } => walk_function(&item.node, None, node_of, ask, walk),
            Item::Impl { target, methods, .. } => {
                let owner = ask.names.resolve(target.name).to_owned();
                for method in methods.iter() { walk_function(&method.node, Some(owner.to_owned()), node_of, ask, walk); }
            },
            _ => { },
        }
    }
}

fn walk_function(item: &Item, target: Option<String>, node_of: &impl Fn(&Expr) -> i64, ask: &TierAsk<'_>, walk: &mut TierWalk) {
    let (name, receiver, args, body) = match item {
        Item::Fn { name, receiver, args, body, .. } => { let name = *name; (name, receiver, args, body) },
        _ => return,
    };
    let key = tier_key((target).as_deref(), &own_name((name).as_ref(), ask.names));
    walk.locals = collections::BTreeMap::new();
    walk.frames = vec![];
    walk.result = Some(key.to_owned());
    walk.in_hole = false;
    walk.hole_text = -1;
    open_tier_scope(walk);
    let mut at = 0;
    for arg in args.iter() {
        let owner = TextOwner::Param(key.to_owned(), at);
        let kinds = kinds_of(&owner, &arg.ty, &mut vec![], ask, &walk);
        let of: String = ask.names.resolve(arg.ty.name).to_owned();
        let local = TierLocal { kinds, of: Some(of), literal: -1, declared: Some(Declaring { owner, ty: arg.ty.clone() }) };
        bind_tier_local(ask.names.resolve(arg.name).to_owned(), local, walk);
        at += 1;
    }
    if receiver.is_some() && target.is_some() {
        let local = TierLocal { kinds: owned_kinds(), of: match target.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, literal: -1, declared: None };
        bind_tier_local(String::from("self"), local, walk);
    }
    let tail = tier_block(body, node_of, ask, walk);
    if !body.stmts.is_empty() {
        match &nikaia_std::index::get(&body.stmts, nikaia_std::index::at(body.stmts.len() as i64 - 1)).node {
            Stmt::Expr(last) => flow_result(last, &tail, node_of, ask, walk),
            _ => { },
        }
    }
    close_tier_scope(walk);
}

fn decide_tiers(flows: &Flows, declared: &TextDeclared) -> collections::BTreeMap<String, Tier> {
    let mut positions = flows.positions.to_owned();
    let mut fixed: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (word, _) in positions.iter() { if flows.unwrappable.contains(word) || fixed_by_publishing(word, flows, declared) { fixed.insert(word.to_owned()); } }
    let mut changed = true;
    while changed {
        changed = false;
        for (a, b) in flows.links.iter() {
            let mut both = nikaia_std::index::or(match *nikaia_std::index::get(&positions, a) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || no_kinds().into());
            both = kinds_joined(&both, &nikaia_std::index::or(match *nikaia_std::index::get(&positions, b) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || no_kinds().into()));
            if joins_kinds(a, &both, &mut positions) { changed = true; }
            if joins_kinds(b, &both, &mut positions) { changed = true; }
            if fixed.contains(a) != fixed.contains(b) {
                fixed.insert(a.to_owned());
                fixed.insert(b.to_owned());
                changed = true;
            }
        }
        for (from, to) in flows.param_into.iter() {
            if fixed.contains(to) && !fixed.contains(from) {
                fixed.insert(from.to_owned());
                changed = true;
            }
        }
    }
    let mut out: collections::BTreeMap<String, Tier> = collections::BTreeMap::new();
    for (word, kinds) in positions.iter() {
        let mut tier = tier_of_kinds(kinds);
        if mixed(&tier) && fixed.contains(word) { tier = Tier::Owned; }
        if !owned_tier(&tier) { out.insert(word.to_owned(), tier); }
    }
    out
}

fn joins_kinds(word: &str, both: &Kinds, positions: &mut collections::BTreeMap<String, Kinds>) -> bool {
    let before = nikaia_std::index::or(match *nikaia_std::index::get(&positions, word) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || no_kinds().into());
    if positions.contains_key(word) && same_kinds(&before, both) { return false; }
    positions.insert(word.to_owned(), both.clone());
    true
}

fn fixed_by_publishing(word: &str, flows: &Flows, declared: &TextDeclared) -> bool {
    let position = match *nikaia_std::index::get(&flows.known, word) { Some(__nikaia_value) => __nikaia_value, None => return false };
    if !position_published(&position.owner, declared) { return false; }
    let a_parameter = matches!(position.owner, TextOwner::Param(_, _));
    !(a_parameter && position.path.is_empty())
}

fn same_tiers(a: &collections::BTreeMap<String, Tier>, b: &collections::BTreeMap<String, Tier>) -> bool {
    if (a.len() as i64) != b.len() as i64 { return false; }
    for (word, tier) in a.iter() {
        let other = match *nikaia_std::index::get(&b, word) { Some(__nikaia_value) => __nikaia_value, None => return false };
        if tier_word(tier) != tier_word(other) { return false; }
    }
    true
}

fn tier_word(tier: &Tier) -> String {
    match tier {
        Tier::Owned => String::from("owned"),
        Tier::View => String::from("view"),
        Tier::Mixed => String::from("mixed"),
    }
}

pub fn text_tiers(program: &Program, ask: &TierAsk<'_>, node_of: &impl Fn(&Expr) -> i64) -> TextTiers {
    let declared = declared_of(program, ask.names);
    let text = string_type(&declared, ask.names);
    let mut walk = TierWalk { declared, tiers: collections::BTreeMap::new(), flows: no_flows(), locals: collections::BTreeMap::new(), frames: vec![], result: None, in_hole: false, hole_text: -1 };
    for _ in 0..16 {
        walk.flows = no_flows();
        walk_program(program, node_of, ask, &mut walk);
        let next = decide_tiers(&walk.flows, &walk.declared);
        if same_tiers(&next, &walk.tiers) { break; }
        walk.tiers = next;
    }
    let mut tiers: Vec<(TextPosition, Tier)> = vec![];
    for (word, tier) in walk.tiers.iter() {
        let position = match match *nikaia_std::index::get(&walk.flows.known, word) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => continue };
        tiers.push((position, tier.clone()));
    }
    let mut lets: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for (at, kept) in walk.flows.literal_lets.iter() {
        let at = nikaia_std::num::value(at);
        for word in kept.iter() {
            if !walk.tiers.contains_key(word) {
                lets.insert(at.clone());
                break;
            }
        }
    }
    TextTiers { tiers, lets, text, wraps: walk.flows.wraps.to_owned(), hole_wraps: walk.flows.hole_wraps.to_owned() }
}

fn no_path() -> Vec<i64> { vec![] }


// --- threads.nika ---

const PLAIN_DATA: [&str; 19] = ["bool", "char", "scalar", "str", "String", "i8", "i16", "i32", "i64", "i128", "isize", "u8", "u16", "u32", "u64", "u128", "usize", "f32", "f64"];

const CONTAINER_TYPES: [&str; 11] = ["BTreeMap", "BTreeSet", "HashMap", "HashSet", "List", "Option", "Receiver", "Result", "Sender", "Shared", "Vec"];

const CHOSEN_TYPES: [&str; 3] = ["Locked", "SharedMut", "Shared"];

const CROSSING_DEPTH: i64 = 16;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Going {
    Ours,
    Foreign,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Refusal {
    Lock,
    Count,
    Said,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Crossing {
    May,
    MayNot { part: String, at: Option<String>, why: Refusal },
    Undecided { part: String },
}

impl Crossing {
    pub fn may(&self) -> bool { matches!(self, Crossing::May) }
    pub fn refused_part(&self) -> Option<String> {
        match self {
            Crossing::MayNot { part, .. } => Some(part.to_owned()),
            _ => None,
        }
    }
    pub fn refused_at(&self) -> Option<String> {
        match self {
            Crossing::MayNot { at, .. } => a_copy_of((at).as_deref()),
            _ => None,
        }
    }
    pub fn why(&self) -> Option<Refusal> {
        match self {
            Crossing::MayNot { why, .. } => Some(why.clone()),
            _ => None,
        }
    }
    pub fn way_out(&self) -> Option<String> {
        match self {
            Crossing::MayNot { why, .. } => Some(way_out_of(why)),
            _ => None,
        }
    }
    pub fn note(&self) -> Option<String> {
        match self {
            Crossing::May => None,
            Crossing::MayNot { part, at, why } => Some(refusal_note(part, (at).as_deref(), why)),
            Crossing::Undecided { part } => Some(format!("Nothing says whether `{}` can move to another thread, so the compiler assumes it can't.", part)),
        }
    }
}

fn a_copy_of(text: Option<&str>) -> Option<String> {
    let there = match text { Some(__nikaia_value) => __nikaia_value, None => return None };
    Some(there.to_owned())
}

fn way_out_of(why: &Refusal) -> String {
    match why {
        Refusal::Lock => String::from("Open the lock here and pass the value inside it, so the called code gets an ordinary value and no lock."),
        Refusal::Count => String::from("Pass what the shared value holds, a view or a copy, instead of the shared value itself."),
        Refusal::Said => String::from("Keep it here, and pass the call only what it needs from it."),
    }
}

fn refusal_note(part: &str, at: Option<&str>, why: &Refusal) -> String {
    let clause = held_clause(at);
    match why {
        Refusal::Lock => format!("`{}`{} holds a lock, and a lock can't be passed to code the compiler knows nothing about.", part, clause),
        Refusal::Count => format!("`{}`{} is shared, and how a shared value is counted is decided per value, so code outside Nikaia can't be written to handle it.", part, clause),
        Refusal::Said => format!("`{}`{} is described as a value that can't move to another thread.", part, clause),
    }
}

fn held_clause(at: Option<&str>) -> String {
    let field = match at { Some(__nikaia_value) => __nikaia_value, None => return String::from("") };
    format!(", which its field `{}` holds,", field)
}

pub fn crossing(ty: &Ty, walking: &Walking<'_>) -> Crossing {
    let mut seen: collections::BTreeSet<String> = collections::BTreeSet::new();
    crossing_walk(ty, walking, &mut seen, CROSSING_DEPTH)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Walking<'a> {
    pub own: &'a Ledger,
    pub library: &'a Ledger,
    pub into: Going,
}

fn crossing_walk(ty: &Ty, walking: &Walking<'_>, seen: &mut collections::BTreeSet<String>, depth: i64) -> Crossing {
    if depth == 0 { return Crossing::Undecided { part: ty.text() }; }
    match ty {
        Ty::Unknown => Crossing::Undecided { part: String::from("?") },
        Ty::Count(_) => Crossing::May,
        Ty::Pointed { .. } => Crossing::Undecided { part: ty.text() },
        Ty::Var { .. } => Crossing::Undecided { part: ty.text() },
        Ty::Fn { .. } => Crossing::Undecided { part: ty.text() },
        Ty::Seq { .. } => Crossing::Undecided { part: ty.text() },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); crossing_walk(inner, walking, seen, depth - 1) },
        Ty::Tuple(parts) => all_of(parts, walking, seen, depth),
        Ty::Named { name, args, .. } => named_crossing(ty, name, args, walking, seen, depth),
    }
}

fn named_crossing(ty: &Ty, name: &str, args: &[Ty], walking: &Walking<'_>, seen: &mut collections::BTreeSet<String>, depth: i64) -> Crossing {
    let base = base_name(name);
    if one_of(&PLAIN_DATA, &base) {
        if args.is_empty() { return Crossing::May; }
        return Crossing::Undecided { part: ty.text() };
    }
    let foreign = match walking.into {
        Going::Foreign => true,
        Going::Ours => false,
    };
    if one_of(&CONTAINER_TYPES, &base) {
        let inside = if args.is_empty() { Crossing::Undecided { part: ty.text() } } else { all_of(args, walking, seen, depth) };
        if foreign && one_of(&CHOSEN_TYPES, name) && inside.refused_part().is_none() { return Crossing::MayNot { part: ty.text(), at: None, why: Refusal::Count }; }
        return inside;
    }
    if one_of(&CHOSEN_TYPES, name) {
        if foreign { return Crossing::MayNot { part: ty.text(), at: None, why: Refusal::Lock }; }
        if args.is_empty() { return Crossing::Undecided { part: ty.text() }; }
        return all_of(args, walking, seen, depth);
    }
    described_crossing(ty, name, args, walking, seen, depth)
}

fn described_crossing(ty: &Ty, name: &str, args: &[Ty], walking: &Walking<'_>, seen: &mut collections::BTreeSet<String>, depth: i64) -> Crossing {
    let contract = match ledger_type(name, walking.own, walking.library) { Some(__nikaia_value) => __nikaia_value, None => return Crossing::Undecided { part: ty.text() } };
    if contract.crosses.may_not() { return Crossing::MayNot { part: ty.text(), at: None, why: Refusal::Said }; }
    if contract.crosses.may() && args.is_empty() { return Crossing::May; }
    if contract.fields.is_empty() { return Crossing::Undecided { part: ty.text() }; }
    if !seen.insert(name.to_owned()) { return Crossing::May; }
    let mut worst = Crossing::May;
    for field in contract.fields.iter() {
        let answer = name_the_field(&field.name, crossing_walk(&field.ty, walking, seen, depth - 1));
        worst = worst_of(worst, answer);
    }
    seen.remove(name);
    worst
}

fn all_of(parts: &[Ty], walking: &Walking<'_>, seen: &mut collections::BTreeSet<String>, depth: i64) -> Crossing {
    let mut worst = Crossing::May;
    for part in parts.iter() { worst = worst_of(worst, crossing_walk(part, walking, seen, depth - 1)); }
    worst
}

pub fn worst_of(worst: Crossing, answer: Crossing) -> Crossing {
    match worst {
        Crossing::MayNot { .. } => worst,
        Crossing::Undecided { .. } => match answer {
            Crossing::MayNot { .. } => answer,
            _ => worst,
        },
        Crossing::May => answer,
    }
}

fn name_the_field(field: &str, answer: Crossing) -> Crossing {
    match answer {
        Crossing::MayNot { ref part, ref at, why } => field_named_at(field, part, (at).as_deref(), &why),
        _ => answer,
    }
}

fn field_named_at(field: &str, part: &str, at: Option<&str>, why: &Refusal) -> Crossing {
    let already = match at { Some(__nikaia_value) => __nikaia_value, None => return Crossing::MayNot { part: part.to_owned(), at: Some(field.to_owned()), why: why.clone() } };
    Crossing::MayNot { part: part.to_owned(), at: Some(already.to_owned()), why: why.clone() }
}

fn ledger_type(name: &str, own: &Ledger, library: &Ledger) -> Option<TypeContract> {
    let suffix = format!("::{}", name);
    let mine = in_one_ledger(name, &suffix, own);
    if mine.is_some() { return mine; }
    in_one_ledger(name, &suffix, library)
}

fn in_one_ledger(name: &str, suffix: &str, ledger: &Ledger) -> Option<TypeContract> {
    let whole: Option<TypeContract> = match *nikaia_std::index::get(&ledger.types, name) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    };
    if whole.is_some() { return whole; }
    for (key, contract) in ledger.types.iter() { if key.ends_with(suffix) { return Some(contract.clone()); } }
    None
}

fn base_name(name: &str) -> String {
    let parts: Vec<&str> = name.split("::").collect::<Vec<_>>();
    (*nikaia_std::index::get(&parts, nikaia_std::index::at(parts.len() as i64 - 1))).to_owned()
}

fn one_of(names: &[&str], name: &str) -> bool {
    for one in names.iter() {
        let one = *one;
        if one == name { return true; }
    }
    false
}

pub fn held_across_a_pause(bound: &[(String, i64)], pauses: &[i64], named: &collections::BTreeMap<String, i64>) -> collections::BTreeSet<String> {
    let mut out: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (name, at) in bound.iter() {
        let at = nikaia_std::num::value(at);
        let last = match *nikaia_std::index::get(&named, name) { Some(__nikaia_value) => nikaia_std::num::value(__nikaia_value), None => continue };
        for pause in pauses.iter() {
            let pause = nikaia_std::num::value(pause);
            if pause > at && last > pause { out.insert(name.to_owned()); }
        }
    }
    out
}


// --- throws.nika ---

const UNNAMED: &str = "?";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MethodsCalled {
    pub resolved: collections::BTreeSet<String>,
    pub unseen: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ThrowsGraph {
    pub methods: collections::BTreeMap<String, MethodsCalled>,
    pub direct: collections::BTreeMap<String, collections::BTreeSet<String>>,
    pub calls: collections::BTreeMap<String, collections::BTreeSet<String>>,
}

pub fn unit_throws(program: &Program, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, own: &Ledger, library: &Ledger, graph: &mut ThrowsGraph) {
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, body, can_throw, .. } => {
                let can_throw = *can_throw; let name = *name;
                if can_throw {
                    let thrown = thrown_by(body, names, holes_of, contribution_of);
                    with_methods(&key_of_function((name).as_ref(), "", names), &thrown, own, library, graph);
                }
            },
            Item::Impl { target, methods, .. } => {
                let owner = names.resolve(target.name).to_owned();
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, body, can_throw, .. } => {
                            let can_throw = *can_throw; let name = *name;
                            if can_throw {
                                let thrown = thrown_by(body, names, holes_of, contribution_of);
                                with_methods(&key_of_function((name).as_ref(), &owner, names), &thrown, own, library, graph);
                            }
                        },
                        _ => { },
                    }
                }
            },
            _ => { },
        }
    }
}

fn with_methods(key: &str, thrown: &Thrown, own: &Ledger, library: &Ledger, graph: &mut ThrowsGraph) {
    let mut named = thrown.direct.to_owned();
    let mut called = thrown.calls.to_owned();
    methods_into(*nikaia_std::index::get(&graph.methods, key), own, library, &mut named, &mut called);
    graph.direct.insert(key.to_owned(), named);
    graph.calls.insert(key.to_owned(), called);
}

fn methods_into(resolved: Option<&MethodsCalled>, own: &Ledger, library: &Ledger, named: &mut collections::BTreeSet<String>, called: &mut collections::BTreeSet<String>) {
    let known = match resolved { Some(__nikaia_value) => __nikaia_value, None => return };
    if known.unseen { named.insert(UNNAMED.to_owned()); }
    for callee in known.resolved.iter() { if own.functions.contains_key(callee) { called.insert(callee.to_owned()); } else { for error in fails_with_of(library, callee) { named.insert(error); } } }
}

fn fails_with_of(library: &Ledger, callee: &str) -> Vec<String> {
    let contract = match *nikaia_std::index::get(&library.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return vec![String::from("?")] };
    contract.fails_with.to_owned()
}

pub fn error_sets(direct: &collections::BTreeMap<String, collections::BTreeSet<String>>, calls: &collections::BTreeMap<String, collections::BTreeSet<String>>, own: &Ledger) -> collections::BTreeMap<String, Vec<String>> {
    let mut sets = direct.to_owned();
    let mut changed = true;
    while changed {
        changed = false;
        for (name, callees) in calls.iter() {
            let before = nikaia_std::index::or(match *nikaia_std::index::get(&sets, name) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || collections::BTreeSet::new().into());
            let mut grown = before.to_owned();
            for callee in callees.iter() { for error in theirs(&sets, own, callee) { grown.insert(error); } }
            if (grown.len() as i64) != before.len() as i64 {
                sets.insert(name.to_owned(), grown);
                changed = true;
            }
        }
    }
    let mut settled: collections::BTreeMap<String, Vec<String>> = collections::BTreeMap::new();
    for (name, set) in sets.iter() {
        let contract = match *nikaia_std::index::get(&own.functions, name) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if contract.fails_with.is_empty() { continue; }
        let mut errors: Vec<String> = vec![];
        for error in set.iter() { errors.push(error.to_owned()); }
        if errors.is_empty() { errors.push(String::from("?")); }
        settled.insert(name.to_owned(), errors);
    }
    settled
}

fn theirs(sets: &collections::BTreeMap<String, collections::BTreeSet<String>>, own: &Ledger, callee: &str) -> Vec<String> {
    let mut errors: Vec<String> = vec![];
    if sets.contains_key(callee) {
        let set = match *nikaia_std::index::get(&sets, callee) { Some(__nikaia_value) => __nikaia_value, None => return errors };
        for error in set.iter() { errors.push(error.to_owned()); }
        return errors;
    }
    let contract = match *nikaia_std::index::get(&own.functions, callee) { Some(__nikaia_value) => __nikaia_value, None => return errors };
    for error in contract.fails_with.iter() { errors.push(error.to_owned()); }
    errors
}

pub fn error_type(names: &winnow_grammar::InternerContext, thrown: &Expr) -> Option<String> {
    match thrown {
        Expr::Path(segments) => if segments.len() > 1 { Some(all_but_the_last(names, segments)) } else { None },
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); error_type(names, func) },
        Expr::StructLit { name, .. } => { let name = *name; Some(struct_type(names.resolve(name))) },
        _ => None,
    }
}

fn all_but_the_last(names: &winnow_grammar::InternerContext, segments: &[winnow_grammar::Symbol]) -> String {
    let mut written: String = String::from("");
    for k in 0..segments.len() as i64 - 1 {
        if k > 0 { written = format!("{}::", written); }
        let segment = names.resolve(*nikaia_std::index::get(&segments, (k) as usize));
        written = format!("{}{}", written, segment);
    }
    written
}

fn struct_type(written: &str) -> String {
    let mut parts: Vec<String> = vec![];
    for part in written.split("::") { parts.push(part.to_owned()); }
    if parts.len() < 2 { return written.to_owned(); }
    let mut ty: String = String::from("");
    for k in 0..parts.len() as i64 - 1 {
        if k > 0 { ty = format!("{}::", ty); }
        ty = format!("{}{}", ty, *nikaia_std::index::get(&parts, (k) as usize));
    }
    ty
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Thrown {
    pub direct: collections::BTreeSet<String>,
    pub calls: collections::BTreeSet<String>,
    passes_on: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Contribution {
    pub call: Option<String>,
    pub errors: Vec<String>,
}

pub fn thrown_by(body: &Block, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution) -> Thrown {
    let mut out = Thrown { direct: collections::BTreeSet::new(), calls: collections::BTreeSet::new(), passes_on: false };
    thrown_in_block(body, names, holes_of, contribution_of, false, &mut out);
    out
}

fn thrown_in_block(block: &Block, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, out: &mut Thrown) {
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { value, .. } => thrown_in(value, names, holes_of, contribution_of, in_a_handler, false, out),
            Stmt::Comptime { value, .. } => thrown_in(value, names, holes_of, contribution_of, in_a_handler, false, out),
            Stmt::Expr(value) => thrown_in(value, names, holes_of, contribution_of, in_a_handler, false, out),
            Stmt::Return(value) => thrown_in(match value { Some(__nikaia_value) => __nikaia_value, None => continue }, names, holes_of, contribution_of, in_a_handler, false, out),
            Stmt::Assign { target, value, .. } => {
                thrown_in(target, names, holes_of, contribution_of, in_a_handler, false, out);
                thrown_in(value, names, holes_of, contribution_of, in_a_handler, false, out);
            },
            Stmt::For { iter, .. } => thrown_in(iter, names, holes_of, contribution_of, in_a_handler, false, out),
            Stmt::While { cond, .. } => thrown_in(cond, names, holes_of, contribution_of, in_a_handler, false, out),
            _ => { },
        }
        match &stmt.node {
            Stmt::For { body, .. } => thrown_in_block(body, names, holes_of, contribution_of, in_a_handler, out),
            Stmt::While { body, .. } => thrown_in_block(body, names, holes_of, contribution_of, in_a_handler, out),
            Stmt::Let { value, .. } => thrown_in_blocks(value, names, holes_of, contribution_of, in_a_handler, out),
            Stmt::Comptime { value, .. } => thrown_in_blocks(value, names, holes_of, contribution_of, in_a_handler, out),
            Stmt::Expr(value) => thrown_in_blocks(value, names, holes_of, contribution_of, in_a_handler, out),
            Stmt::Return(value) => thrown_in_blocks(match value { Some(__nikaia_value) => __nikaia_value, None => continue }, names, holes_of, contribution_of, in_a_handler, out),
            Stmt::Assign { target, value, .. } => {
                thrown_in_blocks(target, names, holes_of, contribution_of, in_a_handler, out);
                thrown_in_blocks(value, names, holes_of, contribution_of, in_a_handler, out);
            },
            _ => { },
        }
    }
}

fn thrown_in(expr: &Expr, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, caught: bool, out: &mut Thrown) {
    a_contribution(expr, names, contribution_of, in_a_handler, caught, out);
    for hole in holes_of(expr) { thrown_in(&hole, names, holes_of, contribution_of, in_a_handler, caught, out); }
    match expr {
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            thrown_in(func, names, holes_of, contribution_of, in_a_handler, caught, out);
            for arg in args.iter() { thrown_in(arg, names, holes_of, contribution_of, in_a_handler, caught, out); }
            for setting in config.iter() { thrown_in(&setting.value, names, holes_of, contribution_of, in_a_handler, caught, out); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            thrown_in(receiver, names, holes_of, contribution_of, in_a_handler, caught, out);
            for arg in args.iter() { thrown_in(arg, names, holes_of, contribution_of, in_a_handler, caught, out); }
            for setting in config.iter() { thrown_in(&setting.value, names, holes_of, contribution_of, in_a_handler, caught, out); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            thrown_in(receiver, names, holes_of, contribution_of, in_a_handler, caught, out);
            for arg in args.iter() { thrown_in(arg, names, holes_of, contribution_of, in_a_handler, caught, out); }
            for setting in config.iter() { thrown_in(&setting.value, names, holes_of, contribution_of, in_a_handler, caught, out); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            thrown_in(lhs, names, holes_of, contribution_of, in_a_handler, caught, out);
            thrown_in(rhs, names, holes_of, contribution_of, in_a_handler, caught, out);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); thrown_in(expr, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); thrown_in(inner, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); thrown_in(inner, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); thrown_in(expr, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); thrown_in(base, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); thrown_in(base, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            thrown_in(base, names, holes_of, contribution_of, in_a_handler, caught, out);
            thrown_in(index, names, holes_of, contribution_of, in_a_handler, caught, out);
        },
        Expr::Range { start, end, .. } => {
            let start = nikaia_std::boxed::open(start); let end = nikaia_std::boxed::open(end);
            thrown_in(start, names, holes_of, contribution_of, in_a_handler, caught, out);
            thrown_in(end, names, holes_of, contribution_of, in_a_handler, caught, out);
        },
        Expr::Tuple(parts) => { for part in parts.iter() { thrown_in(part, names, holes_of, contribution_of, in_a_handler, caught, out); } },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            thrown_in(value, names, holes_of, contribution_of, in_a_handler, caught, out);
            thrown_in(fallback, names, holes_of, contribution_of, in_a_handler, caught, out);
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            let into_the_handler = caught || !passes_on(handler, names, holes_of, contribution_of);
            thrown_in(expr, names, holes_of, contribution_of, in_a_handler, into_the_handler, out);
        },
        Expr::If { cond, .. } => { let cond = nikaia_std::boxed::open(cond); thrown_in(cond, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Match { value, arms } => {
            let value = nikaia_std::boxed::open(value);
            thrown_in(value, names, holes_of, contribution_of, in_a_handler, caught, out);
            for arm in arms.iter() {
                maybe_thrown_in((arm.guard).as_ref(), names, holes_of, contribution_of, in_a_handler, caught, out);
                thrown_in(&arm.body, names, holes_of, contribution_of, in_a_handler, caught, out);
            }
        },
        Expr::StructLit { fields, .. } => { for field in fields.iter() { maybe_thrown_in((field.value).as_ref(), names, holes_of, contribution_of, in_a_handler, caught, out); } },
        Expr::ListLit { items, .. } => { for item in items.iter() { thrown_in(item, names, holes_of, contribution_of, in_a_handler, caught, out); } },
        Expr::With { base, fields, .. } => {
            let base = nikaia_std::boxed::open(base);
            thrown_in(base, names, holes_of, contribution_of, in_a_handler, caught, out);
            for field in fields.iter() { maybe_thrown_in((field.value).as_ref(), names, holes_of, contribution_of, in_a_handler, caught, out); }
        },
        Expr::Return(value) => { let value = nikaia_std::boxed::open(value); thrown_in(match value { Some(__nikaia_value) => __nikaia_value, None => return }, names, holes_of, contribution_of, in_a_handler, caught, out) },
        Expr::Select(arms) => { for arm in arms.iter() { thrown_in(&arm.value, names, holes_of, contribution_of, in_a_handler, caught, out); } },
        _ => { },
    }
}

fn maybe_thrown_in(expr: Option<&Expr>, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, caught: bool, out: &mut Thrown) { thrown_in(match expr { Some(__nikaia_value) => __nikaia_value, None => return }, names, holes_of, contribution_of, in_a_handler, caught, out); }

fn thrown_in_blocks(expr: &Expr, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, out: &mut Thrown) {
    match expr {
        Expr::Block(block) => thrown_in_block(block, names, holes_of, contribution_of, in_a_handler, out),
        Expr::Unsafe(block) => thrown_in_block(block, names, holes_of, contribution_of, in_a_handler, out),
        Expr::Overlap(block) => thrown_in_block(block, names, holes_of, contribution_of, in_a_handler, out),
        Expr::Closure { body, .. } => thrown_in_block(body, names, holes_of, contribution_of, in_a_handler, out),
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            thrown_in_blocks(func, names, holes_of, contribution_of, in_a_handler, out);
            for arg in args.iter() { thrown_in_blocks(arg, names, holes_of, contribution_of, in_a_handler, out); }
            for setting in config.iter() { thrown_in_blocks(&setting.value, names, holes_of, contribution_of, in_a_handler, out); }
        },
        Expr::MethodCall { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            thrown_in_blocks(receiver, names, holes_of, contribution_of, in_a_handler, out);
            for arg in args.iter() { thrown_in_blocks(arg, names, holes_of, contribution_of, in_a_handler, out); }
            for setting in config.iter() { thrown_in_blocks(&setting.value, names, holes_of, contribution_of, in_a_handler, out); }
        },
        Expr::SafeMethod { receiver, args, config, .. } => {
            let receiver = nikaia_std::boxed::open(receiver);
            thrown_in_blocks(receiver, names, holes_of, contribution_of, in_a_handler, out);
            for arg in args.iter() { thrown_in_blocks(arg, names, holes_of, contribution_of, in_a_handler, out); }
            for setting in config.iter() { thrown_in_blocks(&setting.value, names, holes_of, contribution_of, in_a_handler, out); }
        },
        Expr::If { then_branch, else_branch, .. } => {
            thrown_in_block(then_branch, names, holes_of, contribution_of, in_a_handler, out);
            thrown_in_block(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, names, holes_of, contribution_of, in_a_handler, out);
        },
        Expr::TryCatch { expr, handler } => {
            let expr = nikaia_std::boxed::open(expr);
            thrown_in_blocks(expr, names, holes_of, contribution_of, in_a_handler, out);
            thrown_in_block(handler, names, holes_of, contribution_of, true, out);
        },
        Expr::Match { arms, .. } => { for arm in arms.iter() { thrown_in_blocks(&arm.body, names, holes_of, contribution_of, in_a_handler, out); } },
        Expr::Select(arms) => { for arm in arms.iter() { thrown_in_block(&arm.body, names, holes_of, contribution_of, in_a_handler, out); } },
        _ => { },
    }
}

fn a_contribution(expr: &Expr, names: &winnow_grammar::InternerContext, contribution_of: &impl Fn(&Expr) -> Contribution, in_a_handler: bool, caught: bool, out: &mut Thrown) {
    let passing = the_caught_error(expr, names);
    if passing { out.passes_on = true; }
    if caught || in_a_handler && passing { return; }
    match expr {
        Expr::Throw(thrown) => {
            let thrown = nikaia_std::boxed::open(thrown);
            out.direct.insert(nikaia_std::index::or(error_type(names, thrown), || "?".into()));
        },
        _ => {
            let given = contribution_of(expr);
            let call = nikaia_std::index::or(given.call, || "".into());
            if !call.is_empty() { out.calls.insert(call); }
            for error in given.errors.iter() { out.direct.insert(error.to_owned()); }
        },
    }
}

fn the_caught_error(expr: &Expr, names: &winnow_grammar::InternerContext) -> bool {
    match expr {
        Expr::Throw(thrown) => { let thrown = nikaia_std::boxed::open(thrown); match thrown {
            Expr::Variable(name) => { let name = *name; names.resolve(name) == "error" },
            _ => false,
        } },
        _ => false,
    }
}

fn passes_on(handler: &Block, names: &winnow_grammar::InternerContext, holes_of: &impl Fn(&Expr) -> Vec<Expr>, contribution_of: &impl Fn(&Expr) -> Contribution) -> bool {
    let mut seen = Thrown { direct: collections::BTreeSet::new(), calls: collections::BTreeSet::new(), passes_on: false };
    thrown_in_block(handler, names, holes_of, contribution_of, false, &mut seen);
    seen.passes_on
}


// --- tiers.nika ---

const OWNS: [&str; 10] = ["clone", "to_owned", "to_string", "clone_text", "to_uppercase", "to_lowercase", "repeat", "replace", "join", "concat"];

const VIEWS: [&str; 17] = ["trim", "trim_start", "trim_end", "trim_matches", "trim_start_matches", "trim_end_matches", "strip_prefix", "strip_suffix", "lines", "split", "split_whitespace", "splitn", "rsplit", "rsplitn", "split_terminator", "matches", "as_str"];

const ELEMENTS: [&str; 13] = ["collect", "next", "unwrap", "first", "last", "get", "iter", "nth", "peek", "pop", "remove", "values", "keys"];

const PUTS: [&str; 6] = ["push", "push_back", "push_front", "insert", "extend", "append"];

const RUNS: [&str; 4] = ["Vec", "List", "VecDeque", "Deque"];

const SETS: [&str; 3] = ["HashSet", "BTreeSet", "Set"];

const MAPS: [&str; 3] = ["HashMap", "BTreeMap", "Map"];

pub fn owns_its_text(method: &str) -> bool {
    for one in OWNS.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn views_what_it_is_called_on(method: &str) -> bool {
    for one in VIEWS.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn hands_back_an_element(method: &str) -> bool {
    for one in ELEMENTS.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn puts_its_argument(method: &str) -> bool {
    for one in PUTS.iter() {
        let one = *one;
        if one == method { return true; }
    }
    false
}

pub fn is_a_map_name(name: &str) -> bool {
    for one in MAPS.iter() {
        let one = *one;
        if one == name { return true; }
    }
    false
}

pub fn is_a_container_name(callee: &str) -> bool {
    let name = last_segment(callee);
    for one in RUNS.iter() {
        let one = *one;
        if one == name { return true; }
    }
    for one in SETS.iter() {
        let one = *one;
        if one == name { return true; }
    }
    is_a_map_name(&name)
}

pub fn plain_string(names: &winnow_grammar::InternerContext, ty: &Type) -> bool { names.resolve(ty.name) == "String" && ty.generics.is_empty() && !ty.is_view && !ty.is_tuple && !ty.is_slice && (*ty.code).is_none() }

pub fn container_of(names: &winnow_grammar::InternerContext, ty: &Type) -> Option<String> {
    if ty.is_view || ty.is_nullable || ty.is_tuple || (*ty.code).is_some() { return None; }
    let name = last_segment(names.resolve(ty.name));
    if is_a_container_name(&name) { return Some(name); }
    None
}


// --- touch.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reached {
    pub kind: String,
    pub named: Option<String>,
    pub unknown: bool,
    pub write: bool,
}

impl Reached {
    pub fn might_be_same(&self, other: &Reached) -> bool {
        if family(&self.kind) != family(&other.kind) { return false; }
        if self.unknown || other.unknown { return true; }
        let mine = match match self.named.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return true };
        let theirs = match match other.named.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => return true };
        mine == theirs
    }
    pub fn conflicts_with(&self, other: &Reached) -> bool { (self.write || other.write) && self.might_be_same(other) }
}

fn family(kind: &str) -> String {
    if kind == "stderr" { return String::from("stdout"); }
    kind.to_owned()
}

pub fn touches_of(unknown: &collections::BTreeMap<String, bool>, outside: &collections::BTreeMap<String, Vec<Touch>>, calls: &collections::BTreeMap<String, collections::BTreeSet<String>>) -> collections::BTreeMap<String, Vec<Touch>> {
    let mut known: collections::BTreeMap<String, bool> = collections::BTreeMap::new();
    for (name, lost) in unknown.iter() {
        let lost = nikaia_std::num::value(lost);
        known.insert(name.to_owned(), !lost);
    }
    let mut changed = true;
    while changed {
        changed = false;
        for (name, called) in calls.iter() {
            let holds = nikaia_std::index::or(*nikaia_std::index::get(&known, name), || false);
            if !holds { continue; }
            let mut reaches_unknown = false;
            for callee in called.iter() {
                let theirs = nikaia_std::index::or(*nikaia_std::index::get(&known, callee), || false);
                if !theirs { reaches_unknown = true; }
            }
            if reaches_unknown {
                known.insert(name.to_owned(), false);
                changed = true;
            }
        }
    }
    let mut settled: collections::BTreeMap<String, Vec<Touch>> = collections::BTreeMap::new();
    for (name, holds) in known.iter() {
        let holds = nikaia_std::num::value(holds);
        if !holds { continue; }
        let mut found: Vec<Touch> = vec![];
        let mut seen: collections::BTreeSet<String> = collections::BTreeSet::new();
        let mut todo: Vec<String> = vec![name.to_owned()];
        while !todo.is_empty() {
            let here = match todo.pop() { Some(__nikaia_value) => __nikaia_value, None => break };
            if seen.contains(&here) { continue; }
            seen.insert(here.to_owned());
            for touch in nikaia_std::index::or(match *nikaia_std::index::get(&outside, &here) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || vec![].into()) { found.push(touch); }
            for callee in nikaia_std::index::or(match *nikaia_std::index::get(&calls, &here) {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            }, || collections::BTreeSet::new().into()) { todo.push(callee); }
        }
        settled.insert(name.to_owned(), found);
    }
    settled
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reach {
    pub unknown: bool,
    pub outside: Vec<Touch>,
    pub calls: collections::BTreeSet<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TouchGraph {
    pub methods: collections::BTreeMap<String, MethodsCalled>,
    pub reaches: collections::BTreeMap<String, Reach>,
}

pub fn unit_touches(program: &Program, names: &winnow_grammar::InternerContext, unaliased: &impl Fn(&str) -> String, holes_of: &impl Fn(&Expr) -> Vec<Expr>, own: &Ledger, library: &Ledger, graph: &mut TouchGraph) {
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, body, .. } => {
                let name = *name;
                let key = key_of_function((name).as_ref(), "", names);
                let mut reach = Reach { unknown: false, outside: vec![], calls: collections::BTreeSet::new() };
                reached_by(&seen_in(body, names, unaliased, holes_of, &no_root, false), program, names, own, library, &mut reach);
                methods_reach(*nikaia_std::index::get(&graph.methods, &key), own, library, &mut reach);
                graph.reaches.insert(key, reach);
            },
            Item::Impl { target, methods, .. } => {
                let owner = names.resolve(target.name).to_owned();
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, body, .. } => {
                            let name = *name;
                            let key = key_of_function((name).as_ref(), &owner, names);
                            let mut reach = Reach { unknown: false, outside: vec![], calls: collections::BTreeSet::new() };
                            reached_by(&seen_in(body, names, unaliased, holes_of, &no_root, false), program, names, own, library, &mut reach);
                            methods_reach(*nikaia_std::index::get(&graph.methods, &key), own, library, &mut reach);
                            graph.reaches.insert(key, reach);
                        },
                        _ => { },
                    }
                }
            },
            Item::Grammar(def) => {
                let mut whole = Reach { unknown: false, outside: vec![], calls: collections::BTreeSet::new() };
                for rule in def.rules.iter() {
                    for alt in rule.alts.iter() {
                        let action = match alt.action.as_ref() { Some(__nikaia_value) => __nikaia_value, None => continue };
                        reached_by(&seen_in(action, names, unaliased, holes_of, &no_root, false), program, names, own, library, &mut whole);
                    }
                }
                rules_into(def, names, &whole, own, library, graph);
            },
            _ => { },
        }
    }
}

pub fn touches_of_graph(graph: &TouchGraph) -> collections::BTreeMap<String, Vec<Touch>> {
    let mut unknown: collections::BTreeMap<String, bool> = collections::BTreeMap::new();
    let mut outside: collections::BTreeMap<String, Vec<Touch>> = collections::BTreeMap::new();
    let mut calls: collections::BTreeMap<String, collections::BTreeSet<String>> = collections::BTreeMap::new();
    for (name, reach) in graph.reaches.iter() {
        unknown.insert(name.to_owned(), reach.unknown);
        outside.insert(name.to_owned(), reach.outside.to_owned());
        calls.insert(name.to_owned(), reach.calls.to_owned());
    }
    touches_of(&unknown, &outside, &calls)
}

fn rules_into(def: &GrammarDef, names: &winnow_grammar::InternerContext, whole: &Reach, own: &Ledger, library: &Ledger, graph: &mut TouchGraph) {
    let named = names.resolve(def.name).to_owned();
    for rule in def.rules.iter() {
        if !rule.is_entry { continue; }
        let key = format!("{}::{}", named, names.resolve(rule.name));
        let mut reach = Reach { unknown: whole.unknown, outside: whole.outside.to_owned(), calls: whole.calls.to_owned() };
        methods_reach(*nikaia_std::index::get(&graph.methods, &key), own, library, &mut reach);
        graph.reaches.insert(key, reach);
    }
}

fn reached_by(seen: &[Seen], program: &Program, names: &winnow_grammar::InternerContext, own: &Ledger, library: &Ledger, reach: &mut Reach) {
    for one in seen.iter() {
        match one {
            Seen::Call { name, .. } => reached_call((callee_named(names, name.to_owned(), own, library, &program.items)).as_ref(), library, reach),
            Seen::Spawn { .. } => { reach.unknown = true; },
            Seen::Opaque { .. } => { reach.unknown = true; },
            _ => { },
        }
    }
}

fn reached_call(callee: Option<&Callee>, library: &Ledger, reach: &mut Reach) {
    let known = match callee { Some(__nikaia_value) => __nikaia_value, None => return };
    match known {
        Callee::Own(name) => { reach.calls.insert(name.to_owned()); },
        Callee::Library { key, .. } => absorb(*nikaia_std::index::get(&library.functions, key), reach),
        Callee::Opaque(_) => { reach.unknown = true; },
        _ => { },
    }
}

fn methods_reach(resolved: Option<&MethodsCalled>, own: &Ledger, library: &Ledger, reach: &mut Reach) {
    let known = match resolved { Some(__nikaia_value) => __nikaia_value, None => return };
    if known.unseen { reach.unknown = true; }
    for callee in known.resolved.iter() { if own.functions.contains_key(callee) { reach.calls.insert(callee.to_owned()); } else { absorb(*nikaia_std::index::get(&library.functions, callee), reach); } }
}

fn absorb(contract: Option<&FnContract>, reach: &mut Reach) {
    if !touches_said(contract) {
        reach.unknown = true;
        return;
    }
    let known = match contract { Some(__nikaia_value) => __nikaia_value, None => return };
    for touch in known.touches.iter() { if touch.parameter.is_some() { reach.unknown = true; } else if !holds_touch(&reach.outside, touch) { reach.outside.push(touch.clone()); } }
}

fn touches_said(contract: Option<&FnContract>) -> bool {
    let known = match contract { Some(__nikaia_value) => __nikaia_value, None => return false };
    known.touches_known
}

fn holds_touch(touches: &[Touch], touch: &Touch) -> bool {
    for one in touches.iter() { if one.kind == touch.kind && one.write == touch.write { return true; } }
    false
}


// --- traits.nika ---

pub fn check_impls(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], own: &Ledger) -> Vec<Finding> {
    let mut found: Vec<Finding> = vec![];
    for item in items.iter() {
        match &item.node {
            Item::Impl { trait_name, target, methods } => {
                let trait_name = *trait_name;
                let written_trait = match trait_name { Some(__nikaia_value) => __nikaia_value, None => continue };
                let named = names.resolve(written_trait).to_owned();
                for one in receivers(names, items, &named, methods) { found.push(one); }
                if !own.traits.contains_key(&named) { continue; }
                let declared = nikaia_std::index::or(match *nikaia_std::index::get(&own.traits, &named) {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, || collections::BTreeSet::new().into());
                let target_name = names.resolve(target.name).to_owned();
                let mut given: Vec<String> = vec![];
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, .. } => {
                            let name = *name;
                            let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                            let written = names.resolve(symbol).to_owned();
                            given.push(written.to_owned());
                            if !declared.contains(&written) {
                                found.push(not_in_the_trait(&named, &target_name, &written, method.span.clone()));
                                continue;
                            }
                            for one in pausing(own, &named, &target_name, &written, method.span.clone()) { found.push(one); }
                        },
                        _ => { },
                    }
                }
                let mut missing: Vec<String> = vec![];
                for wanted in declared.iter() { if !given.contains(&wanted.to_owned()) { missing.push(wanted.to_owned()); } }
                if !missing.is_empty() { found.push(incomplete(&named, &target_name, &missing, item.span.clone())); }
            },
            _ => { },
        }
    }
    found
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Wanted {
    known: bool,
    receiver: Option<Receiver>,
}

fn receivers(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], trait_name: &str, methods: &[Spanned<Item>]) -> Vec<Finding> {
    let mut found: Vec<Finding> = vec![];
    for method in methods.iter() {
        match &method.node {
            Item::Fn { name, receiver, .. } => {
                let name = *name;
                let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => continue };
                let written = names.resolve(symbol).to_owned();
                let wanted = wanted_receiver(names, items, trait_name, &written);
                if !wanted.known || same_receiver(match wanted.receiver.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                }, match receiver.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                    None => None,
                }) { continue; }
                let theirs = receiver_text(match wanted.receiver.as_ref() {
                    Some(__nikaia_it) => Some(__nikaia_it.clone()),
                    None => None,
                });
                let ours = receiver_text(match receiver {
                    Some(__nikaia_it) => Some(__nikaia_it.to_owned()),
                    None => None,
                });
                let notes: Vec<String> = vec![String::from("Callers go through the trait, so they pass the value the way the trait declares.")];
                found.push(refusal("NK1196", method.span.clone(), format!("`{}`'s `{}` takes {}, but this one takes {}.", trait_name, written, theirs, ours), notes, format!("Take it as {}, like `{}` declares.", theirs, trait_name)));
            },
            _ => { },
        }
    }
    found
}

fn wanted_receiver(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], trait_name: &str, method: &str) -> Wanted {
    for item in items.iter() {
        match &item.node {
            Item::Trait { name, methods, .. } => {
                let name = *name;
                if names.resolve(name) == trait_name {
                    for declared in methods.iter() {
                        if names.resolve(declared.node.name) == method {
                            return Wanted { known: true, receiver: match declared.node.receiver.as_ref() {
                                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                                None => None,
                            } };
                        }
                    }
                    return Wanted { known: false, receiver: None };
                }
            },
            _ => { },
        }
    }
    let shared = Receiver { is_ref: true, is_mut: false };
    let changed = Receiver { is_ref: true, is_mut: true };
    if trait_name == "Error" && method == "message" { return Wanted { known: true, receiver: Some(shared) }; }
    if trait_name == "Drop" && method == "drop" || trait_name == "Cleanup" && method == "cleanup" { return Wanted { known: true, receiver: Some(changed) }; }
    Wanted { known: false, receiver: None }
}

fn same_receiver(a: Option<Receiver>, b: Option<Receiver>) -> bool {
    if a.is_none() || b.is_none() { return a.is_none() && b.is_none(); }
    let one = nikaia_std::index::or(a, || Receiver { is_ref: false, is_mut: false });
    let other = nikaia_std::index::or(b, || Receiver { is_ref: false, is_mut: false });
    one.is_ref == other.is_ref && one.is_mut == other.is_mut
}

fn receiver_text(receiver: Option<Receiver>) -> String {
    let taken = match receiver { Some(__nikaia_value) => __nikaia_value, None => return String::from("no `self`") };
    if taken.is_ref && taken.is_mut { return String::from("`ref mut self`"); }
    if taken.is_ref { return String::from("`ref self`"); }
    if taken.is_mut { return String::from("`mut self`"); }
    String::from("`self`")
}

fn pausing(own: &Ledger, trait_name: &str, target: &str, method: &str, span: Span) -> Vec<Finding> {
    let mut found: Vec<Finding> = vec![];
    let implemented = format!("{}::{}", target, method);
    let declaring = format!("{}::{}", trait_name, method);
    if !own.functions.contains_key(&implemented) || !own.functions.contains_key(&declaring) { return found; }
    let contract = nikaia_std::index::or(match *nikaia_std::index::get(&own.functions, &implemented) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || FnContract::empty());
    let declared = nikaia_std::index::or(match *nikaia_std::index::get(&own.functions, &declaring) {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }, || FnContract::empty());
    if declared.sync_claim.is_sync() && !contract.sync_claim.is_sync() {
        let notes: Vec<String> = vec![String::from("`sync` in a trait promises that every implementation never pauses. (The opposite is fine: a body that never pauses can implement a method that may.)")];
        found.push(refusal("NK1129", span.clone(), format!("`{}::{}` can pause, but `{}` declares `{}` as `sync`.", target, method, trait_name, method), notes, format!("Remove `sync` from `{}`'s `{}`, or take out what pauses in the body, such as a file read, a sleep or a `.join()`.", trait_name, method)));
    }
    if declared.fails_with.is_empty() && !contract.fails_with.is_empty() {
        let notes: Vec<String> = vec![String::from("A trait method without `throws` promises that no implementation fails. (The opposite is fine: a body that can't fail can implement one with `throws`.)")];
        found.push(refusal("NK1140", span, format!("`{}::{}` can fail, but `{}` declares `{}` without `throws`.", target, method, trait_name, method), notes, format!("Add `throws` to `{}`'s `{}`, or handle the failure in the body with `catch`.", trait_name, method)));
    }
    found
}

fn not_in_the_trait(trait_name: &str, target: &str, method: &str, span: Span) -> Finding {
    let notes: Vec<String> = vec![format!("`impl {} for {}` can only hold `{}`'s methods. The type's own methods go in a separate `impl {}`.", trait_name, target, trait_name, target)];
    refusal("NK1130", span, format!("`{}` has no method called `{}`.", trait_name, method), notes, format!("Move it to `impl {}`, or add `{}` to `{}` if every type that implements it should have one.", target, method, trait_name))
}

fn incomplete(trait_name: &str, target: &str, missing: &[String], span: Span) -> Finding {
    let mut listed: String = String::from("");
    for at in 0..missing.len() as i64 {
        if at > 0 { listed.push_str(", "); }
        let one = nikaia_std::index::get(&missing, (at) as usize);
        let quoted = format!("`{}`", one);
        listed.push_str(&quoted);
    }
    let pronoun = if missing.len() == 1 { "it" } else { "them" };
    let notes: Vec<String> = vec![String::from("A trait promises that all its methods are there, which is what lets code call them through a bound.")];
    refusal("NK1130", span, format!("`{}` is missing {} from `{}`.", target, listed, trait_name), notes, format!("Add {} to this `impl`, or remove {} from `{}`.", listed, pronoun, trait_name))
}


// --- tree_build.nika ---

#[derive(Debug, Clone, PartialEq)]
pub enum Postfix {
    Field(winnow_grammar::Symbol),
    SafeField(winnow_grammar::Symbol),
    SafeMethod(winnow_grammar::Symbol, Vec<Expr>, Vec<ConfigArg>),
    Method(winnow_grammar::Symbol, Vec<Expr>, Vec<ConfigArg>),
    Index(Expr),
    IndexFrom(Expr, winnow_grammar::Symbol),
    With(Vec<FieldInit>, u32),
}

pub fn split_mut(params: &[(bool, winnow_grammar::Symbol)]) -> (Vec<winnow_grammar::Symbol>, Vec<winnow_grammar::Symbol>) {
    let mut names: Vec<winnow_grammar::Symbol> = vec![];
    let mut mutable: Vec<winnow_grammar::Symbol> = vec![];
    for param in params.iter() {
        names.push(param.1);
        if param.0 { mutable.push(param.1); }
    }
    (names, mutable)
}

pub fn params_of(receiver: Option<Receiver>, args: Vec<FnArg>, zone: Option<ConfigZone>) -> FnParams {
    if zone.is_none() { return FnParams { receiver, args, config: vec![], spread: None }; }
    match nikaia_std::index::or(zone, || ConfigZone::Options(vec![])) {
        ConfigZone::Options(options) => { return FnParams { receiver, args, config: options, spread: None }; },
        ConfigZone::Spread(name) => { return FnParams { receiver, args, config: vec![], spread: Some(name) }; },
    }
}

pub fn guarded(jump: Stmt, cond: Expr, span: Span) -> Stmt { Stmt::Expr(Expr::If { cond: Box::new(cond), then_branch: Block { stmts: vec![Spanned { node: jump, span, doc: None, attributes: vec![] }] }, else_branch: None }) }

pub fn fold_binary(head: Expr, tail: Vec<(BinaryOp, Expr, Span)>) -> Expr {
    let mut lhs = head;
    for step in tail.into_iter() { lhs = Expr::Binary { op: step.0, lhs: Box::new(lhs), rhs: Box::new(step.1), span: step.2, grouped: false }; }
    lhs
}

pub fn grouped(e: Expr) -> Expr {
    match e {
        Expr::Binary { op, lhs, rhs, span, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            return Expr::Binary { op, lhs: Box::new(lhs), rhs: Box::new(rhs), span, grouped: true };
        },
        other => { return other; },
    }
}

pub fn fold_postfix(base: Expr, tail: Vec<Postfix>) -> Expr {
    let mut recv = base;
    for step in tail.into_iter() {
        recv = match step {
            Postfix::Field(name) => Expr::Field { base: Box::new(recv), name },
            Postfix::SafeField(name) => Expr::SafeField { base: Box::new(recv), name },
            Postfix::SafeMethod(method, args, config) => Expr::SafeMethod { receiver: Box::new(recv), method, args, config },
            Postfix::Method(method, args, config) => Expr::MethodCall { receiver: Box::new(recv), method, args, config },
            Postfix::Index(index) => Expr::Index { base: Box::new(recv), index: Box::new(index) },
            Postfix::IndexFrom(start, len) => Expr::Index { base: Box::new(recv.clone()), index: Box::new(Expr::Range { start: Box::new(start), end: Box::new(Expr::MethodCall { receiver: Box::new(recv), method: len, args: vec![], config: vec![] }), inclusive: false }) },
            Postfix::With(fields, at) => Expr::With { base: Box::new(recv), fields, at },
        };
    }
    recv
}


// --- trust.nika ---

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Wrote {
    Anywhere,
    TheFilesystemRoot,
}

pub fn spelled(wrote: &Wrote) -> String {
    match wrote {
        Wrote::Anywhere => String::from("Anywhere"),
        Wrote::TheFilesystemRoot => String::from("Dir(\"/\") - which is every directory"),
    }
}

pub fn written_root(names: &winnow_grammar::InternerContext, arg: &Expr) -> Option<Wrote> {
    match arg {
        Expr::Path(segments) => if ends_with_variant(names, segments, "Anywhere") { Some(Wrote::Anywhere) } else { None },
        Expr::Call { func, args, .. } => { let func = nikaia_std::boxed::open(func); the_whole_filesystem(names, func, args) },
        _ => None,
    }
}

fn the_whole_filesystem(names: &winnow_grammar::InternerContext, func: &Expr, args: &[Expr]) -> Option<Wrote> {
    let is_dir = match func {
        Expr::Path(segments) => ends_with_variant(names, segments, "Dir"),
        _ => false,
    };
    if !is_dir || args.is_empty() { return None; }
    match nikaia_std::index::get(&args, 0) {
        Expr::LitStr { text, .. } => if text == "/" { Some(Wrote::TheFilesystemRoot) } else { None },
        _ => None,
    }
}

fn ends_with_variant(names: &winnow_grammar::InternerContext, segments: &[winnow_grammar::Symbol], variant: &str) -> bool {
    let n = segments.len() as i64;
    n >= 2 && names.resolve(*nikaia_std::index::get(&segments, nikaia_std::index::at(n - 2))) == "Root" && names.resolve(*nikaia_std::index::get(&segments, nikaia_std::index::at(n - 1))) == variant
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Reason {
    pub source: String,
    pub untrusted: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Place {
    pub line: i64,
    pub column: i64,
    pub entry: String,
    pub wrote: Wrote,
}

pub fn render(untrusted: bool, reasons: &[Reason], places: &[Place], path: &str) -> String {
    let mut out = format!("input provenance: {}\n", provenance(untrusted));
    if reasons.is_empty() { out.push_str("    no source is read, so nothing entered from outside\n"); }
    for reason in reasons.iter() { out.push_str(&format!("    {} is {}\n", reason.source, provenance(reason.untrusted))); }
    let hash = if untrusted { "keyed, per-process random seed - key choice cannot be aimed at the table" } else { "fast, fixed seed - no adversary chooses these keys" };
    out.push_str(&format!("hash for a map keyed by the input: {}\n", hash));
    out.push_str("file access with no root to check against:\n");
    if places.is_empty() { out.push_str("    none - every path here names a directory it may not leave\n"); }
    for place in places.iter() { out.push_str(&format!("    {}:{}:{}  {} writes {}\n", path, place.line, place.column, place.entry, spelled(&place.wrote))); }
    out
}

fn provenance(untrusted: bool) -> String { if untrusted { String::from("untrusted") } else { String::from("trusted") } }


#[derive(Debug, Clone, PartialEq, Eq)]
struct KeyDeps {
    known: bool,
    ids: Vec<i64>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MapEnv {
    sources: collections::BTreeSet<String>,
    own: collections::BTreeSet<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MapMade {
    at: i64,
    name: String,
    id: i64,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MapKept {
    id: i64,
    deps: KeyDeps,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct MapWalk {
    scopes: Vec<collections::BTreeMap<String, i64>>,
    given: Vec<Vec<KeyDeps>>,
    made: Vec<MapMade>,
    kept: Vec<MapKept>,
    escapes: collections::BTreeSet<i64>,
    bound: collections::BTreeMap<String, i64>,
    unread: bool,
}

fn tm_never() -> KeyDeps { KeyDeps { known: false, ids: vec![] } }

fn tm_nothing() -> KeyDeps { KeyDeps { known: true, ids: vec![] } }

fn tm_reading(id: i64) -> KeyDeps { KeyDeps { known: true, ids: vec![id] } }

fn tm_join(a: &KeyDeps, b: &KeyDeps) -> KeyDeps {
    if !a.known || !b.known { return tm_never(); }
    let mut ids: Vec<i64> = vec![];
    for id in a.ids.iter() {
        let id = nikaia_std::num::value(id);
        ids.push(id);
    }
    for id in b.ids.iter() {
        let id = nikaia_std::num::value(id);
        ids.push(id);
    }
    KeyDeps { known: true, ids }
}

pub fn trusted_maps(program: &Program, words: &winnow_grammar::InternerContext, library: &Ledger) -> collections::BTreeSet<i64> {
    let mut env = MapEnv { sources: collections::BTreeSet::new(), own: collections::BTreeSet::new() };
    for (key, contract) in library.functions.iter() {
        let provenance = match contract.provenance { Some(__nikaia_value) => __nikaia_value, None => continue };
        if provenance == Provenance::Untrusted {
            let parts: Vec<&str> = key.split("::").collect::<Vec<_>>();
            env.sources.insert((*nikaia_std::index::get(&parts, nikaia_std::index::at(parts.len() as i64 - 1))).to_owned());
        }
    }
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { name, .. } => { let name = *name; tm_remember(name, words, &mut env.own) },
            Item::Impl { methods, .. } => {
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { name, .. } => { let name = *name; tm_remember(name, words, &mut env.own) },
                        _ => { },
                    }
                }
            },
            _ => { },
        }
    }
    let mut out: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for item in program.items.iter() {
        match &item.node {
            Item::Fn { args, body, .. } => tm_walk_function(args, body, words, library, &env, &mut out),
            Item::Impl { methods, .. } => {
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { args, body, .. } => tm_walk_function(args, body, words, library, &env, &mut out),
                        _ => { },
                    }
                }
            },
            _ => { },
        }
    }
    out
}

fn tm_remember(name: Option<winnow_grammar::Symbol>, words: &winnow_grammar::InternerContext, own: &mut collections::BTreeSet<String>) {
    let symbol = match name { Some(__nikaia_value) => __nikaia_value, None => return };
    own.insert(words.resolve(symbol).to_owned());
}

fn tm_walk_function(args: &[FnArg], body: &Block, words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, out: &mut collections::BTreeSet<i64>) {
    let mut first: collections::BTreeMap<String, i64> = collections::BTreeMap::new();
    for arg in args.iter() { first.insert(words.resolve(arg.name).to_owned(), -1); }
    let mut walk = MapWalk { scopes: vec![first], given: vec![], made: vec![], kept: vec![], escapes: collections::BTreeSet::new(), bound: collections::BTreeMap::new(), unread: false };
    tm_walk_block(body, words, library, env, &mut walk);
    if walk.made.is_empty() || walk.unread { return; }
    let trusted = tm_trusted_bindings(&walk.given);
    for made in walk.made.iter() {
        if nikaia_std::index::or(walk.bound.get(&made.name), || 0) != 1 { continue; }
        if walk.escapes.contains(&made.id) { continue; }
        let mut keys_trusted = true;
        for kept in walk.kept.iter() {
            if kept.id != made.id { continue; }
            if !kept.deps.known { keys_trusted = false; }
            for dep in kept.deps.ids.iter() {
                let dep = nikaia_std::num::value(dep);
                if !trusted.contains(&dep) { keys_trusted = false; }
            }
        }
        if keys_trusted { out.insert(made.at); }
    }
}

fn tm_trusted_bindings(given: &[Vec<KeyDeps>]) -> collections::BTreeSet<i64> {
    let mut trusted: collections::BTreeSet<i64> = collections::BTreeSet::new();
    let mut id: i64 = 0;
    while id < given.len() as i64 {
        let mut every = true;
        for one in (*nikaia_std::index::get(&given, nikaia_std::index::at(id))).iter() { if !one.known { every = false; } }
        if every { trusted.insert(id); }
        id = id + 1;
    }
    let mut settled = false;
    while !settled {
        let mut now: collections::BTreeSet<i64> = collections::BTreeSet::new();
        for id in trusted.iter() {
            let id = nikaia_std::num::value(id);
            now.insert(id);
        }
        let mut next: collections::BTreeSet<i64> = collections::BTreeSet::new();
        for id in now.iter() {
            let id = nikaia_std::num::value(id);
            let mut holds = true;
            for one in (*nikaia_std::index::get(&given, nikaia_std::index::at(id))).iter() {
                if !one.known { holds = false; }
                for dep in one.ids.iter() {
                    let dep = nikaia_std::num::value(dep);
                    if !now.contains(&dep) { holds = false; }
                }
            }
            if holds { next.insert(id); }
        }
        if (next.len() as i64) == now.len() as i64 { settled = true; }
        trusted = next;
    }
    trusted
}

fn tm_bind(name: &str, given: &KeyDeps, walk: &mut MapWalk) -> i64 {
    let id = walk.given.len() as i64;
    walk.given.push(vec![KeyDeps { known: given.known, ids: given.ids.to_owned() }]);
    tm_count_binding(name, walk);
    let last = walk.scopes.len() as i64 - 1;
    walk.scopes[nikaia_std::index::at(last)].insert(name.to_owned(), id);
    id
}

fn tm_opaque(name: &str, walk: &mut MapWalk) {
    tm_count_binding(name, walk);
    let last = walk.scopes.len() as i64 - 1;
    walk.scopes[nikaia_std::index::at(last)].insert(name.to_owned(), -1);
}

fn tm_count_binding(name: &str, walk: &mut MapWalk) {
    let before = nikaia_std::index::or(walk.bound.get(name), || 0);
    walk.bound.insert(name.to_owned(), before + 1);
}

fn tm_resolve(name: &str, walk: &MapWalk) -> i64 {
    let mut at = walk.scopes.len() as i64;
    while at > 0 {
        at = at - 1;
        let found = (*nikaia_std::index::get(&walk.scopes, nikaia_std::index::at(at))).get(name);
        if found.is_some() { return nikaia_std::index::or(found, || -2); }
    }
    -2
}

fn tm_walk_block(block: &Block, words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, walk: &mut MapWalk) {
    walk.scopes.push(collections::BTreeMap::new());
    for stmt in block.stmts.iter() {
        match &stmt.node {
            Stmt::Let { names, value, .. } => {
                tm_walk_expr(value, words, library, env, walk);
                let given = tm_deps_of(value, words, library, env, &walk);
                if names.len() == 1 {
                    let name = words.resolve(*nikaia_std::index::get(&names, 0)).to_owned();
                    let id = tm_bind(&name, &given, walk);
                    if is_a_map_made(value, words) { walk.made.push(MapMade { at: stmt.span.start as i64, name: name.to_owned(), id }); }
                } else { for one in names.iter() { tm_opaque(words.resolve(*one), walk); } }
            },
            Stmt::Assign { target, value, .. } => {
                tm_walk_expr(target, words, library, env, walk);
                tm_walk_expr(value, words, library, env, walk);
                match target {
                    Expr::Variable(name) => {
                        let name = *name;
                        let given = tm_deps_of(value, words, library, env, &walk);
                        let id = tm_resolve(words.resolve(name), &walk);
                        if id >= 0 { walk.given[nikaia_std::index::at(id)].push(given); }
                    },
                    _ => { },
                }
            },
            Stmt::For { bindings, iter, body } => {
                match iter {
                    Expr::Variable(name) => {
                        let name = *name;
                        let id = tm_resolve(words.resolve(name), &walk);
                        if id >= 0 { walk.kept.push(MapKept { id, deps: tm_nothing() }); }
                    },
                    _ => tm_walk_expr(iter, words, library, env, walk),
                }
                let given = tm_deps_of(iter, words, library, env, &walk);
                walk.scopes.push(collections::BTreeMap::new());
                for one in bindings.iter() { tm_bind(words.resolve(*one), &given, walk); }
                tm_walk_block(body, words, library, env, walk);
                walk.scopes.pop();
            },
            Stmt::While { cond, body } => {
                tm_walk_expr(cond, words, library, env, walk);
                tm_walk_block(body, words, library, env, walk);
            },
            Stmt::Expr(value) => tm_walk_expr(value, words, library, env, walk),
            Stmt::Return(value) => { if value.is_some() { tm_walk_expr(match value { Some(__nikaia_value) => __nikaia_value, None => return }, words, library, env, walk); } },
            _ => { walk.unread = true; },
        }
    }
    walk.scopes.pop();
}

fn map_named(receiver: &Expr, words: &winnow_grammar::InternerContext, walk: &MapWalk) -> i64 {
    match receiver {
        Expr::Variable(name) => {
            let name = *name;
            let id = tm_resolve(words.resolve(name), walk);
            if id >= 0 { id } else { -1 }
        },
        _ => -1,
    }
}

fn tm_walk_expr(expr: &Expr, words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, walk: &mut MapWalk) {
    match expr {
        Expr::Block(b) => tm_walk_block(b, words, library, env, walk),
        Expr::Unsafe(b) => tm_walk_block(b, words, library, env, walk),
        Expr::If { cond, then_branch, else_branch } => {
            let cond = nikaia_std::boxed::open(cond);
            tm_walk_expr(cond, words, library, env, walk);
            tm_walk_block(then_branch, words, library, env, walk);
            if else_branch.is_some() { tm_walk_block(match else_branch { Some(__nikaia_value) => __nikaia_value, None => return }, words, library, env, walk); }
        },
        Expr::MethodCall { receiver, method, args, config } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let id = map_named(receiver, words, &walk);
            if id >= 0 && words.resolve(method) != "clone" {
                let mut all = tm_nothing();
                for a in args.iter() { all = tm_join(&all, &tm_deps_of(a, words, library, env, &walk)); }
                walk.kept.push(MapKept { id, deps: all });
            } else { tm_walk_expr(receiver, words, library, env, walk); }
            for a in args.iter() { tm_walk_expr(a, words, library, env, walk); }
            for c in config.iter() { tm_walk_expr(&c.value, words, library, env, walk); }
        },
        Expr::Index { base, index } => {
            let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index);
            let id = map_named(base, words, &walk);
            if id >= 0 {
                let deps = tm_deps_of(index, words, library, env, &walk);
                walk.kept.push(MapKept { id, deps });
            } else { tm_walk_expr(base, words, library, env, walk); }
            tm_walk_expr(index, words, library, env, walk);
        },
        Expr::Call { func, args, config } => {
            let func = nikaia_std::boxed::open(func);
            tm_walk_expr(func, words, library, env, walk);
            for a in args.iter() { tm_walk_expr(a, words, library, env, walk); }
            for c in config.iter() { tm_walk_expr(&c.value, words, library, env, walk); }
        },
        Expr::Binary { lhs, rhs, .. } => {
            let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs);
            tm_walk_expr(lhs, words, library, env, walk);
            tm_walk_expr(rhs, words, library, env, walk);
        },
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tm_walk_expr(expr, words, library, env, walk) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tm_walk_expr(expr, words, library, env, walk) },
        Expr::Try(inner) => { let inner = nikaia_std::boxed::open(inner); tm_walk_expr(inner, words, library, env, walk) },
        Expr::Throw(inner) => { let inner = nikaia_std::boxed::open(inner); tm_walk_expr(inner, words, library, env, walk) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); tm_walk_expr(base, words, library, env, walk) },
        Expr::SafeField { base, .. } => { let base = nikaia_std::boxed::open(base); tm_walk_expr(base, words, library, env, walk) },
        Expr::Coalesce { value, fallback } => {
            let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback);
            tm_walk_expr(value, words, library, env, walk);
            tm_walk_expr(fallback, words, library, env, walk);
        },
        Expr::Tuple(items) => { for i in items.iter() { tm_walk_expr(i, words, library, env, walk); } },
        Expr::ListLit { items, .. } => { for i in items.iter() { tm_walk_expr(i, words, library, env, walk); } },
        Expr::LitInterpolated { parts } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => tm_walk_expr(expr, words, library, env, walk),
                    _ => { },
                }
            }
        },
        Expr::Return(value) => {
            let value = nikaia_std::boxed::open(value);
            if value.is_some() { tm_walk_expr(match value { Some(__nikaia_value) => __nikaia_value, None => return }, words, library, env, walk); }
        },
        Expr::Variable(name) => {
            let name = *name;
            let id = tm_resolve(words.resolve(name), &walk);
            if id >= 0 { walk.escapes.insert(id); }
        },
        Expr::Path(_) => { },
        Expr::LitInt { .. } => { },
        Expr::LitFloat(_) => { },
        Expr::LitStr { .. } => { },
        Expr::LitChar(_) => { },
        Expr::LitBool(_) => { },
        Expr::LitNull => { },
        Expr::Break => { },
        Expr::Continue => { },
        _ => { walk.unread = true; },
    }
}

fn tm_all_deps(items: &[Expr], words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, walk: &MapWalk) -> KeyDeps {
    let mut all = tm_nothing();
    for item in items.iter() {
        all = tm_join(&all, &tm_deps_of(item, words, library, env, walk));
        if !all.known { return all; }
    }
    all
}

fn tm_deps_of(value: &Expr, words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, walk: &MapWalk) -> KeyDeps {
    match value {
        Expr::LitInt { .. } => tm_nothing(),
        Expr::LitFloat(_) => tm_nothing(),
        Expr::LitStr { .. } => tm_nothing(),
        Expr::LitChar(_) => tm_nothing(),
        Expr::LitBool(_) => tm_nothing(),
        Expr::LitNull => tm_nothing(),
        Expr::Variable(name) => {
            let name = *name;
            let id = tm_resolve(words.resolve(name), walk);
            if id >= 0 { tm_reading(id) } else { tm_never() }
        },
        Expr::LitInterpolated { parts } => {
            let mut all = tm_nothing();
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => { all = tm_join(&all, &tm_deps_of(expr, words, library, env, walk)); },
                    _ => { },
                }
            }
            all
        },
        Expr::Tuple(items) => tm_all_deps(items, words, library, env, walk),
        Expr::ListLit { items, .. } => tm_all_deps(items, words, library, env, walk),
        Expr::Unary { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tm_deps_of(expr, words, library, env, walk) },
        Expr::Cast { expr, .. } => { let expr = nikaia_std::boxed::open(expr); tm_deps_of(expr, words, library, env, walk) },
        Expr::Binary { lhs, rhs, .. } => { let lhs = nikaia_std::boxed::open(lhs); let rhs = nikaia_std::boxed::open(rhs); tm_join(&tm_deps_of(lhs, words, library, env, walk), &tm_deps_of(rhs, words, library, env, walk)) },
        Expr::Field { base, .. } => { let base = nikaia_std::boxed::open(base); tm_deps_of(base, words, library, env, walk) },
        Expr::Index { base, index } => { let base = nikaia_std::boxed::open(base); let index = nikaia_std::boxed::open(index); tm_join(&tm_deps_of(base, words, library, env, walk), &tm_deps_of(index, words, library, env, walk)) },
        Expr::Coalesce { value, fallback } => { let value = nikaia_std::boxed::open(value); let fallback = nikaia_std::boxed::open(fallback); tm_join(&tm_deps_of(value, words, library, env, walk), &tm_deps_of(fallback, words, library, env, walk)) },
        Expr::Call { func, args, config } => { let func = nikaia_std::boxed::open(func); tm_call_deps(func, args, config, words, library, env, walk) },
        Expr::MethodCall { receiver, method, args, .. } => {
            let receiver = nikaia_std::boxed::open(receiver); let method = *method;
            let name = words.resolve(method);
            if env.sources.contains(name) || env.own.contains(name) { tm_never() } else { tm_join(&tm_deps_of(receiver, words, library, env, walk), &tm_all_deps(args, words, library, env, walk)) }
        },
        _ => tm_never(),
    }
}

fn tm_call_deps(func: &Expr, args: &[Expr], config: &[ConfigArg], words: &winnow_grammar::InternerContext, library: &Ledger, env: &MapEnv, walk: &MapWalk) -> KeyDeps {
    let name = match func {
        Expr::Path(segments) => {
            let mut joined: String = String::from("");
            for segment in segments.iter() {
                if !joined.is_empty() { joined.push_str("::"); }
                joined.push_str(words.resolve(*segment));
            }
            joined
        },
        Expr::Variable(one) => { let one = *one; words.resolve(one).to_owned() },
        _ => return tm_never(),
    };
    if env.own.contains(&name) { return tm_never(); }
    let contract = match *nikaia_std::index::get(&library.functions, &name) { Some(__nikaia_value) => __nikaia_value, None => return tm_never() };
    if contract.provenance.is_some() {
        let provenance = match contract.provenance { Some(__nikaia_value) => __nikaia_value, None => return tm_never() };
        if provenance == Provenance::Trusted { return tm_nothing(); }
        return tm_never();
    }
    let mut all = tm_all_deps(args, words, library, env, walk);
    for c in config.iter() { all = tm_join(&all, &tm_deps_of(&c.value, words, library, env, walk)); }
    all
}

fn is_a_map_made(value: &Expr, words: &winnow_grammar::InternerContext) -> bool {
    match value {
        Expr::Call { func, args, .. } => {
            let func = nikaia_std::boxed::open(func);
            if !args.is_empty() { false } else {
                match func {
                    Expr::Path(segments) => {
                        let last = words.resolve(*nikaia_std::index::get(&segments, nikaia_std::index::at(segments.len() as i64 - 1)));
                        last == "HashMap" || last == "HashSet"
                    },
                    Expr::Variable(one) => {
                        let one = *one;
                        let last = words.resolve(one);
                        last == "HashMap" || last == "HashSet"
                    },
                    _ => false,
                }
            }
        },
        _ => false,
    }
}


// --- ty.nika ---

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Ty {
    Unknown,
    Named { name: String, args: Vec<Ty>, view: bool },
    Tuple(Vec<Ty>),
    Pointed { item: Box<Ty>, slice: bool, mutable: bool },
    Count(i64),
    Var { name: String, view: bool },
    Fn { params: Vec<Ty>, result: Box<Option<Ty>>, is_sync: bool, can_throw: bool },
    Nullable(Box<Ty>),
    Seq { item: Box<Ty>, is_sync: bool, pauses: bool, can_throw: bool, parallel: bool, shape: Shape },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Shape {
    pub ends: bool,
    pub sized: bool,
    pub replays: bool,
}

impl Shape {
    pub fn none() -> Shape { Shape { ends: false, sized: false, replays: false } }
    pub fn meets(&self, wanted: &Shape) -> bool { self.missing(wanted).is_empty() }
    pub fn missing(&self, wanted: &Shape) -> Vec<String> {
        let mut words: Vec<String> = vec![];
        if wanted.ends && !self.ends { words.push(ENDS.to_owned()); }
        if wanted.sized && !self.sized { words.push(SIZED.to_owned()); }
        if wanted.replays && !self.replays { words.push(REPLAYS.to_owned()); }
        words
    }
}

pub const ENDS: &str = "ends";

pub const SIZED: &str = "sized";

pub const REPLAYS: &str = "replays";

pub const SEQ: &str = "Seq";

pub const PAR: &str = "Par";

pub const PAUSES: &str = "pauses";

pub const ARRAY: &str = "Array";

const ARRAY_OPEN: &str = "Array[";

const ARRAY_OPEN_LENGTH: i64 = 6;

pub const TEXT: &str = "String";

pub const TEXT_VIEW: &str = "str";

impl Ty {
    pub fn text(&self) -> String { text(self) }
}

pub fn text(ty: &Ty) -> String {
    match ty {
        Ty::Unknown => String::from("?"),
        Ty::Count(n) => { let n = *n; format!("{}", n) },
        Ty::Pointed { item, slice, mutable } => { let item = nikaia_std::boxed::open(item); let mutable = *mutable; let slice = *slice; pointed(item, slice, mutable) },
        Ty::Tuple(parts) => format!("({})", listed(parts)),
        Ty::Fn { params, result, is_sync, can_throw } => { let result = nikaia_std::boxed::open(result); let can_throw = *can_throw; let is_sync = *is_sync; code(params, (result).as_ref(), is_sync, can_throw) },
        Ty::Var { name, view } => { let view = *view; if view { format!("ref ${}", name) } else { format!("${}", name) } },
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); format!("{}?", text(inner)) },
        Ty::Named { name, args, view } => { let view = *view; named_text(name, args, view) },
        Ty::Seq { item, is_sync, pauses, can_throw, parallel, shape } => { let item = nikaia_std::boxed::open(item); let can_throw = *can_throw; let is_sync = *is_sync; let parallel = *parallel; let pauses = *pauses; sequence(item, is_sync, pauses, can_throw, parallel, shape) },
    }
}

fn listed(parts: &[Ty]) -> String {
    let mut out: String = String::from("");
    for part in parts.iter() {
        if !out.is_empty() { out.push_str(", "); }
        out.push_str(&text(part));
    }
    out
}

fn pointed(item: &Ty, slice: bool, mutable: bool) -> String {
    let mut out: String = String::from("ref ");
    if mutable { out.push_str("mut "); }
    if !slice {
        out.push_str(&text(item));
        return out;
    }
    let written = match item {
        Ty::Nullable(inner) => { let inner = nikaia_std::boxed::open(inner); format!("{}[{}]?", ARRAY, text(inner)) },
        _ => format!("{}[{}]", ARRAY, text(item)),
    };
    out.push_str(&written);
    out
}

fn code(params: &[Ty], result: Option<&Ty>, is_sync: bool, can_throw: bool) -> String {
    let mut out = format!("fn({})", listed(params));
    if result.is_some() {
        let returned = nikaia_std::index::or(match result {
            Some(__nikaia_it) => Some(__nikaia_it.text()),
            None => None,
        }, || "".into());
        out.push_str(&format!(" -> {}", returned));
    }
    if is_sync { out.push_str(" sync"); }
    if can_throw { out.push_str(" throws"); }
    out
}

fn named_text(name: &str, args: &[Ty], view: bool) -> String {
    let mut out: String = if view { String::from("ref ") } else { String::from("") };
    if view && name == TEXT_VIEW { out.push_str(TEXT); } else { out.push_str(name); }
    if !args.is_empty() { out.push_str(&format!("[{}]", listed(args))); }
    out
}

fn sequence(item: &Ty, is_sync: bool, pauses: bool, can_throw: bool, parallel: bool, shape: &Shape) -> String {
    let word = if parallel { PAR } else { SEQ };
    let mut out = format!("{}[{}]", word, text(item));
    if is_sync { out.push_str(" sync"); }
    if pauses { out.push_str(&format!(" {}", PAUSES)); }
    if can_throw { out.push_str(" throws"); }
    for word in Shape::none().missing(shape) { out.push_str(&format!(" {}", word)); }
    out
}

pub fn parse(written: &str) -> Ty {
    let trimmed = written.trim();
    if trimmed.is_empty() || trimmed == "?" { return Ty::Unknown; }
    let count = text::parse_i64(trimmed);
    if count.is_some() { return Ty::Count(nikaia_std::index::or(count, || 0)); }
    let viewed = a_view_of(trimmed);
    let is_a_view = viewed.is_some();
    let marked: String = nikaia_std::index::or(viewed, || "".into());
    if is_a_view {
        let pointer = pointed_at(&marked);
        if pointer.is_some() { return nikaia_std::index::or(pointer, || Ty::Unknown); }
    }
    if trimmed.ends_with("?") { return Ty::Nullable(Box::new(parse(&cut(trimmed, 0, 1)))); }
    if trimmed.starts_with("(") && trimmed.ends_with(")") { return Ty::Tuple(each(&split_args(&cut(trimmed, 1, 1)))); }
    if trimmed.starts_with("fn(") {
        let code = a_function(trimmed);
        if code.is_some() { return nikaia_std::index::or(code, || Ty::Unknown); }
    }
    let sequence = a_sequence(trimmed, SEQ, false);
    if sequence.is_some() { return nikaia_std::index::or(sequence, || Ty::Unknown); }
    let parallel = a_sequence(trimmed, PAR, true);
    if parallel.is_some() { return nikaia_std::index::or(parallel, || Ty::Unknown); }
    if is_a_view { return a_name(marked.trim(), true); }
    a_name(trimmed, false)
}

pub fn split_args(written: &str) -> Vec<String> {
    let mut parts: Vec<String> = vec![];
    let mut depth = 0;
    let mut current: String = String::from("");
    for c in written.chars() {
        if c == '[' || c == '(' {
            depth += 1;
            current.push(c);
        } else if c == ']' || c == ')' {
            if depth > 0 { depth -= 1; }
            current.push(c);
        } else if c == ',' && depth == 0 {
            parts.push(current.trim().to_owned());
            current = String::from("");
        } else { current.push(c); }
    }
    if !current.trim().is_empty() { parts.push(current.trim().to_owned()); }
    parts
}

pub fn a_view_of(written: &str) -> Option<String> {
    if written.starts_with("ref(") {
        let c: Vec<scalar> = nikaia_std::list::chars(written.chars());
        let close = closing(&c, 4, ')');
        if close >= 0 {
            let rest = between(&c, close + 1, c.len() as i64);
            return Some(rest.trim_start().to_owned());
        }
    }
    if written.starts_with("ref ") {
        let rest = cut(written, 4, 0);
        return Some(rest.trim_start().to_owned());
    }
    if written.starts_with("&") {
        let rest = cut(written, 1, 0);
        return Some(rest.trim_start().to_owned());
    }
    None
}

fn each(parts: &[String]) -> Vec<Ty> {
    let mut read: Vec<Ty> = vec![];
    for part in parts.iter() { read.push(parse(part)); }
    read
}

fn between(c: &[scalar], from: i64, to: i64) -> String {
    let mut out: String = String::from("");
    for k in from..to { out.push(*nikaia_std::index::get(&c, nikaia_std::index::at(k))); }
    out
}

fn cut(written: &str, front: i64, back: i64) -> String {
    let c: Vec<scalar> = nikaia_std::list::chars(written.chars());
    between(&c, front, c.len() as i64 - back)
}

fn closing(c: &[scalar], from: i64, closer: scalar) -> i64 {
    let mut depth = 0;
    for at in from..c.len() as i64 {
        let ch = *nikaia_std::index::get(&c, nikaia_std::index::at(at));
        if ch == '(' || ch == '[' { depth += 1; } else if ch == closer {
            if depth == 0 { return at; }
            depth -= 1;
        } else if ch == ')' || ch == ']' {
            if depth == 0 { return -1; }
            depth -= 1;
        }
    }
    -1
}

fn word_off(tail: &str, word: &str) -> Option<String> {
    if !tail.ends_with(word) { return None; }
    let c: Vec<scalar> = nikaia_std::list::chars(tail.chars());
    let w: Vec<scalar> = nikaia_std::list::chars(word.chars());
    let shorter = between(&c, 0, c.len() as i64 - w.len() as i64);
    if shorter.is_empty() { return Some(shorter); }
    if (*nikaia_std::index::get(&c, nikaia_std::index::at(c.len() as i64 - w.len() as i64 - 1))).is_whitespace() { return Some(shorter.trim_end().to_owned()); }
    None
}

fn pointed_at(viewed: &str) -> Option<Ty> {
    let __keep_frame = nikaia_std::tether::Keep::new();
    let mut rest: String = viewed.to_owned();
    let mut mutable = false;
    if rest.starts_with("mut ") {
        mutable = true;
        let shorter = __keep_frame.put(cut(&rest, 4, 0));
        rest = shorter.trim_start().to_owned();
    }
    let mut absent = false;
    if rest.ends_with("?") {
        absent = true;
        let shorter = __keep_frame.put(cut(&rest, 0, 1));
        rest = shorter.trim_end().to_owned();
    }
    let mut slice = false;
    let mut inner: String = String::from("");
    if rest.starts_with(ARRAY_OPEN) && rest.ends_with("]") {
        let args = cut(&rest, ARRAY_OPEN_LENGTH, 1);
        if split_args(&args).len() == 1 {
            slice = true;
            inner = args;
        }
    }
    if !slice && rest.starts_with("[") && rest.ends_with("]") {
        slice = true;
        inner = cut(&rest, 1, 1);
    }
    if !mutable && !slice { return None; }
    if !slice { inner = rest.to_owned(); }
    let item = parse(&inner);
    if absent { return Some(Ty::Pointed { item: Box::new(Ty::Nullable(Box::new(item))), slice, mutable }); }
    Some(Ty::Pointed { item: Box::new(item), slice, mutable })
}

fn a_function(written: &str) -> Option<Ty> {
    let c: Vec<scalar> = nikaia_std::list::chars(written.chars());
    let close = closing(&c, 3, ')');
    if close < 0 { return None; }
    let after = between(&c, close + 1, c.len() as i64);
    let mut tail: String = after.trim().to_owned();
    let mut is_sync = false;
    let mut can_throw = false;
    while !tail.is_empty() {
        let without_throws = word_off(&tail, "throws");
        if without_throws.is_some() {
            can_throw = true;
            tail = nikaia_std::index::or(without_throws, || "".into());
            continue;
        }
        let without_sync = word_off(&tail, "sync");
        if without_sync.is_some() {
            is_sync = true;
            tail = nikaia_std::index::or(without_sync, || "".into());
            continue;
        }
        break;
    }
    let params = each(&split_args(&between(&c, 3, close)));
    if tail.starts_with("->") {
        let result = parse(&cut(&tail, 2, 0));
        return Some(Ty::Fn { params, result: Box::new(Some(result)), is_sync, can_throw });
    }
    Some(Ty::Fn { params, result: Box::new(None), is_sync, can_throw })
}

fn a_sequence(written: &str, word: &str, parallel: bool) -> Option<Ty> {
    if !written.starts_with(word) { return None; }
    let w: Vec<scalar> = nikaia_std::list::chars(word.chars());
    let after_word = cut(written, w.len() as i64, 0);
    let rest: String = after_word.trim_start().to_owned();
    if !rest.starts_with("[") { return None; }
    let c: Vec<scalar> = nikaia_std::list::chars(rest.chars());
    let close = closing(&c, 1, ']');
    if close < 0 { return None; }
    let after = between(&c, close + 1, c.len() as i64);
    let mut tail: String = after.trim().to_owned();
    let mut is_sync = false;
    let mut pauses = false;
    let mut can_throw = false;
    let mut ends = false;
    let mut sized = false;
    let mut replays = false;
    while !tail.is_empty() {
        let without_ends = word_off(&tail, ENDS);
        if without_ends.is_some() {
            ends = true;
            tail = nikaia_std::index::or(without_ends, || "".into());
            continue;
        }
        let without_sized = word_off(&tail, SIZED);
        if without_sized.is_some() {
            sized = true;
            tail = nikaia_std::index::or(without_sized, || "".into());
            continue;
        }
        let without_replays = word_off(&tail, REPLAYS);
        if without_replays.is_some() {
            replays = true;
            tail = nikaia_std::index::or(without_replays, || "".into());
            continue;
        }
        let without_throws = word_off(&tail, "throws");
        if without_throws.is_some() {
            can_throw = true;
            tail = nikaia_std::index::or(without_throws, || "".into());
            continue;
        }
        let without_sync = word_off(&tail, "sync");
        if without_sync.is_some() {
            is_sync = true;
            tail = nikaia_std::index::or(without_sync, || "".into());
            continue;
        }
        let without_pauses = word_off(&tail, PAUSES);
        if without_pauses.is_some() {
            pauses = true;
            tail = nikaia_std::index::or(without_pauses, || "".into());
            continue;
        }
        break;
    }
    if is_sync && pauses { return None; }
    if !tail.is_empty() { return None; }
    let item = parse(&between(&c, 1, close));
    let shape = Shape { ends, sized, replays };
    Some(Ty::Seq { item: Box::new(item), is_sync, pauses, can_throw, parallel, shape })
}

fn a_name(rest: &str, view: bool) -> Ty {
    if rest.starts_with("$") && rest.len() > 1 { return Ty::Var { name: cut(rest, 1, 0), view }; }
    if view && rest == TEXT { return Ty::Named { name: TEXT_VIEW.to_owned(), args: vec![], view: true }; }
    if rest == "char" { return Ty::Named { name: String::from("scalar"), args: vec![], view }; }
    if !rest.ends_with("]") { return Ty::Named { name: rest.to_owned(), args: vec![], view }; }
    let c: Vec<scalar> = nikaia_std::list::chars(rest.chars());
    let mut open: i64 = -1;
    for at in 0..c.len() as i64 { if open < 0 && *nikaia_std::index::get(&c, (at) as usize) == '[' { open = at; } }
    if open >= 0 {
        let named_text = between(&c, 0, open);
        return Ty::Named { name: named_text.trim().to_owned(), args: each(&split_args(&between(&c, open + 1, c.len() as i64 - 1))), view };
    }
    Ty::Named { name: rest.to_owned(), args: vec![], view }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Provenance {
    Trusted,
    Untrusted,
}

impl Provenance {
    pub fn join(self, other: Provenance) -> Provenance {
        if self == Provenance::Untrusted || other == Provenance::Untrusted { return Provenance::Untrusted; }
        Provenance::Trusted
    }
    pub fn as_str(self) -> String {
        match self {
            Provenance::Trusted => String::from("trusted"),
            Provenance::Untrusted => String::from("untrusted"),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Sync {
    No,
    Inferred,
    Asserted,
    From(String),
    Unpromised,
}

impl Sync {
    pub fn is_sync(&self) -> bool { !matches!(self, Sync::No | Sync::Unpromised) }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Lock {
    No,
    Holds,
    Undecided,
}

impl Lock {
    pub fn holds(self) -> bool { self == Lock::Holds }
    pub fn or(self, other: Lock) -> Lock {
        if self == Lock::Holds || other == Lock::Holds { return Lock::Holds; }
        if self == Lock::Undecided || other == Lock::Undecided { return Lock::Undecided; }
        Lock::No
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Crosses {
    May,
    MayNot,
    Undecided,
}

impl Crosses {
    pub fn may(self) -> bool { self == Crosses::May }
    pub fn may_not(self) -> bool { self == Crosses::MayNot }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Threads {
    May,
    MayNot,
    Undecided,
}

impl Threads {
    pub fn may(self) -> bool { self == Threads::May }
    pub fn may_not(self) -> bool { self == Threads::MayNot }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Touch {
    pub kind: String,
    pub parameter: Option<String>,
    pub write: bool,
}

impl Touch {
    pub fn names_a_lock(&self) -> bool { self.kind == "lock" }
    pub fn text(&self) -> String { touched(&self.kind, (self.parameter).as_deref(), self.write) }
}

fn touched(kind: &str, parameter: Option<&str>, write: bool) -> String {
    let access = if write { "write" } else { "read" };
    if parameter.is_none() { return format!("{} {}", kind, access); }
    let named_text = nikaia_std::index::or(parameter, || "");
    format!("{}({}) {}", kind, named_text, access)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Borrowed,
    Tethered,
}

impl State {
    pub fn as_str(self) -> String {
        match self {
            State::Borrowed => String::from("borrowed"),
            State::Tethered => String::from("tethered"),
        }
    }
    pub fn parse(written: &str) -> Option<State> {
        let word = written.trim();
        if word == "borrowed" { return Some(State::Borrowed); }
        if word == "tethered" { return Some(State::Tethered); }
        None
    }
    pub fn or(self, other: State) -> State {
        if self == State::Tethered || other == State::Tethered { return State::Tethered; }
        State::Borrowed
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Held {
    pub position: String,
    pub state: State,
}

impl Held {
    pub fn text(&self) -> String { format!("{}: {}", self.position, self.state.as_str()) }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Count {
    Plain,
    Word,
    Atomic,
}

impl Count {
    pub fn join(self, other: Count) -> Count {
        if self == Count::Atomic || other == Count::Atomic { return Count::Atomic; }
        if self == Count::Word || other == Count::Word { return Count::Word; }
        Count::Plain
    }
    pub fn rank(self) -> i64 {
        match self {
            Count::Plain => 0,
            Count::Word => 1,
            Count::Atomic => 2,
        }
    }
    pub fn as_str(self) -> String {
        match self {
            Count::Plain => String::from("plain"),
            Count::Word => String::from("word"),
            Count::Atomic => String::from("atomic"),
        }
    }
    pub fn parse(written: &str) -> Option<Count> {
        let word = written.trim();
        if word == "plain" { return Some(Count::Plain); }
        if word == "word" { return Some(Count::Word); }
        if word == "atomic" { return Some(Count::Atomic); }
        None
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Class {
    pub members: Vec<String>,
    pub count: Count,
}

impl Class {
    pub fn text(&self) -> String {
        let mut out: String = String::from("");
        for member in self.members.iter() {
            if !out.is_empty() { out.push_str(" | "); }
            out.push_str(member);
        }
        format!("{}: {}", out, self.count.as_str())
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FieldContract {
    pub name: String,
    pub ty: Ty,
    pub public: bool,
    pub default: String,
    pub attributes: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct VariantContract {
    pub name: String,
    pub holds: Vec<FieldContract>,
    pub positional: bool,
    pub attributes: Vec<String>,
}

impl VariantContract {
    pub fn text(&self) -> String {
        if self.holds.is_empty() { return self.name.to_owned(); }
        let mut parts: String = String::from("");
        for field in self.holds.iter() {
            if !parts.is_empty() { parts.push_str(", "); }
            if self.positional { parts.push_str(&field.ty.text()); } else { parts.push_str(&format!("{}: {}", field.name, field.ty.text())); }
        }
        if self.positional { return format!("{}({})", self.name, parts); }
        format!("{} {{ {} }}", self.name, parts)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ConfigContract {
    pub name: String,
    pub ty: Ty,
    pub default: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Signature {
    pub bounds: Vec<(String, Vec<String>)>,
    pub params: Vec<(String, Ty)>,
    pub mutable: Vec<String>,
    pub config: Vec<ConfigContract>,
    pub result: Option<Ty>,
}

impl Signature {
    pub fn empty() -> Signature { Signature { bounds: vec![], params: vec![], mutable: vec![], config: vec![], result: None } }
    pub fn takes_a_receiver(&self) -> bool { !self.params.is_empty() && nikaia_std::index::get(&self.params, 0).0 == "self" }
    pub fn result_or_unit(&self) -> Ty {
        nikaia_std::index::or(match self.result.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || Ty::Tuple(vec![]))
    }
    pub fn text(&self) -> String {
        let mut inside: String = String::from("");
        for (name, ty) in self.params.iter() {
            if !inside.is_empty() { inside.push_str(", "); }
            if name == "self" { inside.push_str(&ty.text()); } else {
                if nikaia_std::list::contains(&self.mutable, &name) { inside.push_str("mut "); }
                inside.push_str(&format!("{}: {}", name, ty.text()));
            }
        }
        if !self.config.is_empty() {
            inside.push_str("; ");
            let mut first = true;
            for option in self.config.iter() {
                if !first { inside.push_str(", "); }
                first = false;
                inside.push_str(&format!("{}: {} = {}", option.name, option.ty.text(), option.default));
            }
        }
        let mut before: String = String::from("");
        if !self.bounds.is_empty() {
            before.push('[');
            let mut first = true;
            for (name, traits) in self.bounds.iter() {
                if !first { before.push_str(", "); }
                first = false;
                before.push_str(name);
                if !traits.is_empty() {
                    before.push_str(": ");
                    let mut one = true;
                    for bound in traits.iter() {
                        if !one { before.push_str(" + "); }
                        one = false;
                        before.push_str(bound);
                    }
                }
            }
            before.push(']');
        }
        if self.result.is_none() { return format!("{}({})", before, inside); }
        format!("{}({}) -> {}", before, inside, self.result_or_unit().text())
    }
}

